  function grundformKandidaten(wort) {
    const roh = String(wort || "").trim().toLowerCase();
    if (roh.length < 3 || /\s/.test(roh)) return [];
    const aus = new Set();
    const dazu = (form) => {
      if (form && form.length >= 3) aus.add(form);
    };
    // Steht die Form in der Tabelle, ist die Sache entschieden.
    if (STARKE_VERBEN[roh]) dazu(STARKE_VERBEN[roh]);

    /* 1. Partizip II: „gegangen" → „gangen"/„gehen", „gekauft" → „kauft".
       Das ge- fällt weg, der Rest wird unten weiterbehandelt. */
    const ohneGe = /^ge[a-zäöüß]{3,}/.test(roh) ? roh.slice(2) : null;

    const stammFormen = [roh];
    if (ohneGe) stammFormen.push(ohneGe);

    stammFormen.forEach((form) => {
      /* 2. Verbendungen abschneiden und den Infinitiv bilden. Die
         Reihenfolge ist wichtig: längere Endungen zuerst, sonst
         verschluckt „t" schon das „est". */
      ["test", "test", "etest", "eten", "etet", "este", "esten",
       "st", "et", "en", "te", "ten", "t", "e"].forEach((endung) => {
        if (!form.endsWith(endung)) return;
        const stamm = form.slice(0, form.length - endung.length);
        if (stamm.length < 2) return;
        dazu(stamm + "en");
        dazu(stamm + "n");          // „sammeln", „ändern"
        dazu(stamm + "eln");
        dazu(stamm + "ern");
        /* Starke Verben bekommen im Präsens einen Umlaut oder einen
           anderen Vokal: „trägt" → tragen, „läuft" → laufen,
           „sieht" → sehen, „nimmt" → nehmen, „gibt" → geben. */
        const rueck = { "ä": "a", "ö": "o", "ü": "u", "äu": "au" };
        Object.entries(rueck).forEach(([um, klar]) => {
          const i = stamm.lastIndexOf(um);
          if (i >= 0) dazu(stamm.slice(0, i) + klar + stamm.slice(i + um.length) + "en");
        });
        // ie → e („sieht" → sehen, „liest" → lesen, „empfiehlt" → empfehlen)
        const ie = stamm.lastIndexOf("ie");
        if (ie >= 0) dazu(stamm.slice(0, ie) + "e" + stamm.slice(ie + 2) + "en");
        // i → e (gibt/geben, nimmt/nehmen, hilft/helfen)
        const j = stamm.lastIndexOf("i");
        if (j >= 0) {
          dazu(stamm.slice(0, j) + "e" + stamm.slice(j + 1) + "en");
          // Doppelkonsonant zurücknehmen: „nimmt" → „nimm" → „nehm" → „nehmen"
          const kurz = stamm.slice(0, j) + "e" + stamm.slice(j + 1).replace(/([bdfgklmnprst])\1$/, "$1");
          dazu(kurz + "en");
        }
        // „ie" im Präteritum: „ging" → gehen, „lief" → laufen, „hielt" → halten
        dazu(stamm + "ien");
      });

      /* 3. Adjektivendungen: „kleine", „kleinen", „kleiner", „kleines",
         „kleinem" → klein. Und der Komparativ: „größer" → groß über den
         Umlaut, „schneller" → schnell. */
      ["esten", "este", "estes", "ester", "estem",
       "ere", "eren", "erer", "eres", "erem", "sten", "ste", "stes", "ster", "stem",
       "en", "em", "er", "es", "e"].forEach((endung) => {
        if (!form.endsWith(endung)) return;
        const stamm = form.slice(0, form.length - endung.length);
        if (stamm.length < 3) return;
        dazu(stamm);
        /* Vor einer Endung fällt das e im Stamm oft aus: „dunklem" steht
           für „dunkel", „teuren" für „teuer", „edler" für „edel". Hier
           wird es versuchsweise wieder eingesetzt. */
        if (/[bdfgklmnprstz][lrn]$/.test(stamm)) {
          dazu(stamm.slice(0, -1) + "e" + stamm.slice(-1));
        }
        const i = Math.max(stamm.lastIndexOf("ä"), stamm.lastIndexOf("ö"), stamm.lastIndexOf("ü"));
        if (i >= 0) {
          const klar = { "ä": "a", "ö": "o", "ü": "u" }[stamm[i]];
          dazu(stamm.slice(0, i) + klar + stamm.slice(i + 1));
          // „größer" → „gross" → „groß"
          dazu((stamm.slice(0, i) + klar + stamm.slice(i + 1)).replace(/ss$/, "ß"));
        }
      });
    });

    aus.delete(roh);
    return [...aus];
  }

  function singularKandidaten(wort) {
    const voll = dictKey(wort);
    const praefix = voll.slice(0, 2);
    if (praefix !== "N:") return []; // nur Nomen haben deutsche Pluralformen dieser Art
    const k = voll.slice(2);
    if (k.length < 4) return [];
    const roh = [];
    ["nen", "en", "er", "se", "e", "n", "s"].forEach((endung) => {
      if (k.endsWith(endung) && k.length - endung.length >= 3) roh.push(k.slice(0, k.length - endung.length));
    });
    roh.push(k);
    const aus = new Set();
    roh.forEach((form) => {
      aus.add(form);
      // Umlaut zurücknehmen: „Kühlschränke" → „kühlschrank", „Bäume" → „baum".
      // Nur der LETZTE Umlaut wird zurückgenommen, damit „Kühl…" erhalten bleibt.
      const idx = Math.max(form.lastIndexOf("ä"), form.lastIndexOf("ö"), form.lastIndexOf("ü"));
      if (idx >= 0) {
        const zurueck = { "ä": "a", "ö": "o", "ü": "u" }[form[idx]];
        aus.add(form.slice(0, idx) + zurueck + form.slice(idx + 1));
      }
    });
    aus.delete(k);
    return [...aus].map((form) => "N:" + form);
  }
  // Der Aufbau der Wörterbuch-Liste geht über mehrere tausend Einträge und wird von
  // mehreren Stellen aufgerufen (Wörterbuch, Vokabelmeister, Prüfung der Eingaben).
  // Deshalb wird das Ergebnis gemerkt und nur neu berechnet, wenn der Lernraum wechselt.
  let dictCache = null;
  let dictCacheRaum = null;
  // Ein Hobby so anzeigen, wie es zum aktuellen Lernraum passt: im Italienisch-Raum
  // mit italienischem Artikel und Wort, darunter klein das deutsche Wort. Genau so
  // gewöhnt man sich die Artikel an, ohne den eigenen Eintrag zu verlieren.
  function hobbyBeschriftung(noun) {
    const h = VocabData.HOBBIES.find((x) => x.noun === noun);
    if (!h) return noun;
    const it = ExerciseData.getLernraum && ExerciseData.getLernraum() === "it" ? (VocabData.HOBBIES_IT || {})[noun] : null;
    if (!it) return `${h.emoji} ${h.article} ${h.noun}`;
    return `${h.emoji} ${it.article}${it.article.endsWith("'") ? "" : " "}${it.noun} <span class="empty-note" style="font-size:0.68rem;">(${h.article} ${h.noun})</span>`;
  }

  let dictCacheWoerter = -1;
  function buildDictionaryEntries() {
    const raum = (ExerciseData.getLernraum && ExerciseData.getLernraum()) || "de";
    if (dictCache && dictCacheRaum === raum && dictCacheWoerter === VocabData.WORDS.length) return dictCache;
    const entries = buildDictionaryEntriesUncached();
    dictCache = entries;
    dictCacheRaum = raum;
    dictCacheWoerter = VocabData.WORDS.length;
    return entries;
  }
  /* Die freigegebenen Zusatzwörter — der Teil des Wörterbuchs, der
     ohne Dateiupload wächst. Sie werden einmal geladen und danach hier
     gehalten, weil der Wörterbuchaufbau synchron läuft. */
  let wortZusatzListe = [];
  async function wortZusatzLaden(frisch) {
    try { wortZusatzListe = (Backend.getWortZusatz ? await Backend.getWortZusatz(frisch) : []) || []; }
    catch (e) { wortZusatzListe = []; }
    dictCache = null;   // das Wörterbuch muss neu gebaut werden
    return wortZusatzListe;
  }

  function buildDictionaryEntriesUncached() {
    const entries = [];
    // Italienisch-Raum: eigener Wortschatz, komplett getrennt vom deutschen.
    if (ExerciseData.getLernraum && ExerciseData.getLernraum() === "it") {
      (ExerciseData.IT_WOERTER || []).forEach((w) => {
        entries.push({ word: w.word, syl: w.syl, meaning: w.de, example: w.example, level: w.level, verified: true, category: w.theme });
      });
      return entries;
    }
    /* Ganz vorn die Wörter, die über die Seite selbst nachgetragen
       wurden: sie sind ausdrücklich freigegeben und sollen eine ältere
       Fassung überschreiben dürfen. */
    wortZusatzListe.forEach((w) => {
      if (!w || !w.word) return;
      entries.push({ word: w.word, syl: w.syl || "", meaning: w.de || "", example: w.example || "",
        level: w.level || "B1", verified: Boolean(w.syl), category: w.theme || "Nachgetragen", nachgetragen: true });
    });
    // Zuerst der nachgelieferte Wortschatz — dadurch gewinnt bei gleichem Stichwort
    // immer die ausdrücklich gepflegte Fassung mit Niveau, Thema und Beispielsatz.
    // Ein Wort darf nur EINMAL im Wörterbuch stehen. Deshalb wird nicht nach dem
    // vollen Stichwort verglichen, sondern nach der Grundform ohne Artikel: sonst
    // stünde „das Buch" (gepflegter Eintrag) neben „Buch" (aus einem Übungstext).
    // Zusätzlich werden reine Pluralformen erkannt und verworfen, wenn der Singular
    // bereits im Wörterbuch steht („Kühlschränke" → „der Kühlschrank").
    const gesehen = new Set();
    function belegen(wort) {
      const k = dictKey(wort);
      if (gesehen.has(k)) return false;
      gesehen.add(k);
      return true;
    }
    function schonDa(wort) {
      if (gesehen.has(dictKey(wort))) return true;
      return singularKandidaten(wort).some((k) => gesehen.has(k));
    }
    // 1. Gepflegter Wortschatz mit ausdrücklichem Niveau und Thema — hat immer Vorrang.
    (VocabData.WORDS || []).forEach((w) => {
      if (!w || !w.word || !belegen(w.word)) return;
      entries.push({ word: w.word, syl: w.syl, meaning: w.de || w.en, example: w.example || "", level: w.level || cefrLevelFor(w.word), verified: true, category: w.theme || categoryForWord(w.word) });
    });
    // 2. Wörter aus den Übungstexten mit eigener Erklärung.
    Object.entries(ExerciseData.WORD_MEANINGS || {}).forEach(([word, meaning]) => {
      if (schonDa(word)) return;
      belegen(word);
      entries.push({ word, syl: (ExerciseData.WORD_SYL || {})[word] || word, meaning, example: "", level: cefrLevelFor(word), verified: true, category: categoryForWord(word) });
    });
    // 3. Wörter, die zwar eine handgeprüfte Betonung in WORD_SYL haben, aber (noch) keine
    // eigene deutsche Erklärung — trotzdem als „geprüft" zählen, die Betonung selbst stimmt.
    Object.entries(ExerciseData.WORD_SYL || {}).forEach(([word, syl]) => {
      if (schonDa(word)) return;
      belegen(word);
      entries.push({ word, syl, meaning: "", example: "", level: cefrLevelFor(word), verified: true, category: categoryForWord(word) });
    });
    // 4. Erweiterter Wortschatz aus allen Übungskategorien — regelbasierte Betonung
    // (nicht handgeprüft), daher ohne feste CEFR-Einstufung. Diese Wörter stammen aus
    // Zitaten in Aufgabentexten und stehen dort oft am Satzanfang, sind also groß
    // geschrieben, ohne Nomen zu sein („Bringen", „Gestern"). Deshalb wird hier
    // zusätzlich die klein geschriebene Fassung geprüft.
    extractExtendedVocabulary().forEach((word) => {
      const roh = String(word).replace(/^(der|die|das)\s+/i, "").trim().toLowerCase();
      if (gesehen.has("w:" + roh) || gesehen.has("N:" + roh)) return;
      if (schonDa(word)) return;
      belegen(word);
      entries.push({ word, syl: kompositumSylString(word) || ruleSylString(word), meaning: "", example: "", level: null, verified: false, category: "Sonstiges" });
    });
    return entries.sort((a, b) => a.word.localeCompare(b.word, "de"));
  }
  let dictLevelFilter = "alle";
  let dictCategoryFilter = "alle";
  let dictNurGemerkte = false;
  // ============================================================================
  // ERSTE SCHRITTE — Brücken-Baukasten für absolute Anfänger:innen. Zeigt statt
  // einer festen englischen Übersetzung automatisch die Muttersprache passend zum
  // im Profil hinterlegten Herkunftsland (Backend.currentProfile().origin) — mit
  // Englisch als Rückfall, wenn kein Land gesetzt ist oder keine Übersetzung für
  // die ermittelte Sprache vorliegt.
  const ORIGIN_TO_LANG = {
    "Ägypten": "ar", "Saudi-Arabien": "ar", "Vereinigte Arabische Emirate": "ar", "Irak": "ar",
    "Syrien": "ar", "Jordanien": "ar", "Marokko": "ar", "Tunesien": "ar", "Algerien": "ar", "Libanon": "ar",
    "Palästina": "ar", "Sudan": "ar", "Libyen": "ar", "Jemen": "ar", "Katar": "ar", "Kuwait": "ar", "Bahrain": "ar", "Oman": "ar",
    "Türkei": "tr",
    "Russland": "ru", "Weißrussland": "ru", "Kasachstan": "ru", "Kirgisistan": "ru", "Usbekistan": "ru",
    "Tadschikistan": "ru", "Turkmenistan": "ru", "Aserbaidschan": "ru", "Armenien": "ru", "Georgien": "ru", "Moldau": "ru",
    "Ukraine": "uk",
    "Iran": "fa", "Afghanistan": "fa",
    "Spanien": "es", "Mexiko": "es", "Argentinien": "es", "Kolumbien": "es", "Chile": "es", "Peru": "es", "Venezuela": "es",
    "Ecuador": "es", "Bolivien": "es", "Uruguay": "es", "Paraguay": "es", "Kuba": "es", "Dominikanische Republik": "es",
    "Guatemala": "es", "Honduras": "es", "El Salvador": "es", "Nicaragua": "es", "Costa Rica": "es", "Panama": "es",
    "Frankreich": "fr", "Belgien": "fr", "Schweiz": "fr", "Senegal": "fr", "Elfenbeinküste": "fr", "Kamerun": "fr",
    "Mali": "fr", "Niger": "fr", "Tschad": "fr", "Guinea": "fr", "Haiti": "fr", "Luxemburg": "fr",
    "Polen": "pl",
    "Portugal": "pt", "Brasilien": "pt", "Angola": "pt", "Mosambik": "pt", "Guinea-Bissau": "pt", "Kap Verde": "pt",
    "USA": "en", "Vereinigtes Königreich": "en",
    "Irland": "en", "Australien": "en", "Neuseeland": "en", "Nigeria": "en", "Kanada": "en",
    "Südafrika": "en", "Kenia": "en", "Ghana": "en", "Pakistan": "en", "Philippinen": "en",
    "Italien": "it", "San Marino": "it", "Vatikanstadt": "it",
    "Indien": "hi",
    "China": "zh", "Taiwan": "zh", "Singapur": "zh",
    "Israel": "he",
  };
  function firstStepsLangFor(profile) {
    const origin = profile?.origin;
    return (origin && ORIGIN_TO_LANG[origin]) || "en";
  }

  /* ============================================================
     DIE HILFSSPRACHE — in welcher Sprache die Erklärung steht
     ------------------------------------------------------------
     GEMELDET: „Manchmal hab ich in der Beschreibung italienischen
     Text, obwohl ich das gar nicht als meine Sprache eingestellt
     hab … es soll die Sprache sein, die ich bei mir eingestellt
     habe, und das in allen Bereichen."

     Und so war es: In der Bilderwelt stand die zweite Zeile fest
     auf Italienisch, weil dort zuerst der Italienischkurs gebaut
     wurde. Jetzt gibt es EINE Stelle, die sagt, welche Sprache die
     Hilfe spricht — und alle Bereiche fragen sie:

       1. Was im Profil ausdrücklich eingestellt ist.
       2. Sonst die Sprache des Herkunftslandes.
       3. Sonst Englisch.

     Zusätzlich kann man eine Sprache als „gerade im Fokus" wählen,
     wenn man nicht Deutsch, sondern etwas anderes übt.
     ============================================================ */
  const HILFSSPRACHEN = {
    en: "English — Englisch", ar: "العربية — Arabisch", tr: "Türkçe — Türkisch",
    ru: "Русский — Russisch", uk: "Українська — Ukrainisch", fa: "فارسی — Persisch",
    es: "Español — Spanisch", pt: "Português — Portugiesisch", fr: "Français — Französisch",
    pl: "Polski — Polnisch", it: "Italiano — Italienisch", hi: "हिन्दी — Hindi",
    zh: "中文 — Chinesisch", he: "עברית — Hebräisch", de: "Deutsch",
  };
  const RTL_SPRACHEN = ["ar", "fa", "he"];
  function istRtl(code) { return RTL_SPRACHEN.indexOf(code) >= 0; }

  function hilfsSprache() {
    const p = Backend.currentProfile();
    const gewaehlt = p && p.extraProfileData && p.extraProfileData.hilfsSprache;
    if (gewaehlt && HILFSSPRACHEN[gewaehlt]) return gewaehlt;
    return firstStepsLangFor(p);
  }
  function hilfsSpracheName(code) { return HILFSSPRACHEN[code] || code; }
  async function hilfsSpracheSetzen(code) {
    const antwort = await Backend.updateExtraProfileField("hilfsSprache", code || null);
    if (antwort && antwort.ok === false) throw new Error(antwort.message || "Konnte nicht gespeichert werden.");
    return true;
  }

  /* ============================================================
     UMGANGSSPRACHE — wie man es wirklich sagt
     ------------------------------------------------------------
     GEWÜNSCHT: „Du brauchst nicht Toilettenpapier sagen, sag lieber
     Klopapier — oder du machst eine Umschaltung in die Umgangssprache,
     sodass man die gewöhnlichen Begriffe hat, die man im Alltag
     wirklich verwendet … aber das musst du erst mal recherchieren, ob
     das überhaupt akkurat ist."

     Deshalb steht hier NUR, was belegt ist. Jeder Eintrag trägt seine
     Stilebene mit:
       „ugs."     im Wörterbuch als umgangssprachlich verzeichnet
       „salopp"   noch eine Stufe lockerer, unter Freunden
       „kurz"     eine übliche Kurzform desselben Wortes
       „regional" nur in einem Teil des Sprachgebiets üblich
     Erfundene „Alltagswörter" stehen hier nicht. Wo es keine gibt,
     bleibt das Wort, wie es ist — das ist kein Loch, sondern die
     Wahrheit über das Wort.
     ============================================================ */
  const UMGANGSSPRACHE = {
    "das Toilettenpapier": { wort: "das Klopapier", syl: "KLO-pa-pier", stil: "ugs." },
    "der Kugelschreiber": { wort: "der Kuli", syl: "KU-li", stil: "ugs." },
    "das Spülmittel": { wort: "das Spüli", syl: "SPÜ-li", stil: "ugs." },
    "die Geschirrspülmaschine": { wort: "die Spülmaschine", syl: "SPÜL-ma-schi-ne", stil: "kurz" },
    "das Federmäppchen": { wort: "das Mäppchen", syl: "MÄPP-chen", stil: "kurz" },
    "das Smartphone": { wort: "das Handy", syl: "HAN-dy", stil: "ugs." },
    "das Mobiltelefon": { wort: "das Handy", syl: "HAN-dy", stil: "ugs." },
    "das Fahrrad": { wort: "das Rad", syl: "RAD", stil: "kurz" },
    "die Universität": { wort: "die Uni", syl: "U-ni", stil: "kurz" },
    "der Personalausweis": { wort: "der Perso", syl: "PER-so", stil: "ugs." },
    "die Limonade": { wort: "die Limo", syl: "LI-mo", stil: "kurz" },
    "die Schokolade": { wort: "die Schoki", syl: "SCHO-ki", stil: "ugs." },
    "das Deodorant": { wort: "das Deo", syl: "DE-o", stil: "kurz" },
    "der Regenschirm": { wort: "der Schirm", syl: "SCHIRM", stil: "kurz" },
    "die Lokomotive": { wort: "die Lok", syl: "LOK", stil: "kurz" },
    "die Fahrkarte": { wort: "das Ticket", syl: "TI-cket", stil: "ugs." },
    "die Mathematik": { wort: "Mathe", syl: "MA-the", stil: "kurz" },
    "der Pullover": { wort: "der Pulli", syl: "PUL-li", stil: "ugs." },
    "das Sofa": { wort: "die Couch", syl: "COUCH", stil: "ugs." },
    "das Motorrad": { wort: "die Maschine", syl: "Ma-SCHI-ne", stil: "ugs." },
    "der Schraubendreher": { wort: "der Schraubenzieher", syl: "SCHRAU-ben-zie-her", stil: "ugs." },
    "die Turnschuhe": { wort: "die Sneaker", syl: "SNEA-ker", stil: "ugs." },
    "die Mülltonne": { wort: "die Tonne", syl: "TON-ne", stil: "kurz" },
    "das Geld": { wort: "die Kohle", syl: "KOH-le", stil: "salopp" },
    "der Fernseher": { wort: "die Glotze", syl: "GLOT-ze", stil: "salopp" },
    "die Arbeit": { wort: "der Job", syl: "JOB", stil: "ugs." },
    "der Großvater": { wort: "der Opa", syl: "O-pa", stil: "ugs." },
    "die Großmutter": { wort: "die Oma", syl: "O-ma", stil: "ugs." },
    "der Vater": { wort: "der Papa", syl: "PA-pa", stil: "ugs." },
    "die Mutter": { wort: "die Mama", syl: "MA-ma", stil: "ugs." },
    "der Taschenrechner": { wort: "der Taschenrechner", syl: "TA-schen-rech-ner", stil: "" },
    "die Straßenbahn": { wort: "die Tram", syl: "TRAM", stil: "regional", wo: "Süddeutschland, Österreich, Schweiz" },
    "das Brötchen": { wort: "die Semmel", syl: "SEM-mel", stil: "regional", wo: "Bayern, Österreich; im Norden „Schrippe“, im Südwesten „Weck“" },
    "die Kartoffel": { wort: "der Erdapfel", syl: "ERD-ap-fel", stil: "regional", wo: "Österreich, Teile Süddeutschlands" },
    "das Mineralwasser": { wort: "der Sprudel", syl: "SPRU-del", stil: "regional", wo: "Südwestdeutschland" },
    "die Semmelbrösel": { wort: "das Paniermehl", syl: "Pa-NIER-mehl", stil: "regional", wo: "Norddeutschland" },
  };
  // Einträge ohne echtes Alltagswort fliegen raus — sie stünden nur im Weg.
  Object.keys(UMGANGSSPRACHE).forEach((k) => {
    if (!UMGANGSSPRACHE[k].stil) delete UMGANGSSPRACHE[k];
  });

  function alltagsWort(standard) { return UMGANGSSPRACHE[standard] || null; }
  function umgangsspracheAn() {
    const p = Backend.currentProfile();
    return Boolean(p && p.extraProfileData && p.extraProfileData.umgangssprache);
  }
  const STIL_TEXT = {
    "ugs.": "umgangssprachlich", "salopp": "salopp — unter Freunden",
    "kurz": "übliche Kurzform", "regional": "regional",
  };
  /* Die kleine Zeile „so sagt man es im Alltag". Sie steht IMMER da —
     auch wenn der Schalter aus ist. Wer Deutsch lernt, soll beides
     kennen: das Wort aus dem Wörterbuch und das Wort von der Straße. */
  function alltagsZeileHtml(standard) {
    const a = alltagsWort(standard);
    if (!a) return "";
    const an = umgangsspracheAn();
    const stil = (STIL_TEXT[a.stil] || a.stil) + (a.wo ? " · " + a.wo : "");
    /* Die Stilangabe gehört immer zum Alltagswort — steht das oben,
       sagt die Zeile das, statt die Angabe an die Wörterbuchform zu
       hängen, wo sie nicht hingehört. */
    return an
      ? `<p class="alltags-zeile">🗣️ Oben steht die Alltagsform <span class="alltags-stil">${escapeHtml(stil)}</span>
           <br>Im Wörterbuch: <strong>${escapeHtml(standard)}</strong></p>`
      : `<p class="alltags-zeile">🗣️ Im Alltag sagt man: <strong>${escapeHtml(a.wort)}</strong>
           <span class="alltags-stil">${escapeHtml(stil)}</span></p>`;
  }

  /* Das Wort in der Hilfssprache. Gibt es dort keine Entsprechung,
     ist Englisch der Rückfall — das steht zu jedem Wort bereit. */
  function inHilfsSprache(teil, code) {
    const c = code || hilfsSprache();
    if (c === "de") return teil.de || "";
    if (c === "it") return teil.it || teil.en || "";
    if (c === "en") return teil.en || "";
    const tabelle = window.DMA_WORTSPRACHEN || {};
    const eintrag = (teil.t) || tabelle[teil.de];
    return (eintrag && eintrag[c]) || teil.en || "";
  }
  function firstStepsTranslate(entry, lang) {
    return entry.translations[lang] || entry.translations.en;
  }
  let firstStepsLangOverride = null; // manuell gewählte Sprache, überschreibt firstStepsLangFor() solange gesetzt
  function firstStepsVocabByKey(key) {
    return ExerciseData.FIRST_STEPS_VOCAB.find((v) => v.de === key);
  }
  function renderFirstSteps() {
    const area = document.getElementById("firstStepsArea");
    if (!area) return;
    const profile = Backend.currentProfile();
    const langNames = { en: "Englisch", ar: "Arabisch", tr: "Türkisch", ru: "Russisch", uk: "Ukrainisch", fa: "Persisch/Farsi", es: "Spanisch", pt: "Portugiesisch", fr: "Französisch", pl: "Polnisch", it: "Italienisch", hi: "Hindi", zh: "Chinesisch", he: "Hebräisch" };
    const lang = firstStepsLangOverride || firstStepsLangFor(profile);
    const rtl = lang === "ar" || lang === "fa" || lang === "he";
    area.innerHTML = `
      <p class="empty-note" style="margin-bottom:14px;">Ein Baukasten für den allerersten Kontakt mit Deutsch — auch ohne ein einziges bereits bekanntes deutsches Wort. Kapitel für Kapitel, wie im Buch: erst ein paar Bausteine lernen, direkt danach damit Sätze bauen — bevor es zum nächsten Kapitel geht.</p>
      <div class="question-card" style="margin-bottom:16px;">
        <p class="eyebrow" style="margin-top:0;">🌍 Übersetzung gerade in: ${langNames[lang]}${lang === "en" && !profile?.origin && !firstStepsLangOverride ? " (Standard — leg dein Herkunftsland im Profil fest, oder wähl unten manuell)" : ""}</p>
        <select id="firstStepsLangSelect" class="challenge-select" style="margin-top:6px;">
          <option value="">Automatisch (aus Herkunftsland)</option>
          ${Object.entries(langNames).map(([code, name]) => `<option value="${code}" ${firstStepsLangOverride === code ? "selected" : ""}>${name}</option>`).join("")}
        </select>
      </div>
      <p class="empty-note" style="margin-bottom:14px;">💡 Die betonte Silbe steht <strong>fett</strong>, und unter ihrem Vokal steht ein Zeichen wie im Duden: ein <strong>Strich</strong> heißt lang gesprochen (T<span class="stress-vokal stress-lang">a</span>g, B<span class="stress-vokal stress-lang">a</span>hn), ein <strong>Punkt</strong> heißt kurz (B<span class="stress-vokal stress-kurz">a</span>nk). Ein kleiner offener Kreis heißt: die Silbe ist betont, aber die Schreibung verrät die Länge nicht eindeutig. Geschrieben wird das Wort ganz normal — die Zeichen gelten nur der Aussprache.</p>

      <p class="eyebrow">🧩 Satz-Baukasten — selbst ausprobieren</p>
      <div class="question-card" style="margin-bottom:20px;">
        <p class="empty-note" style="margin:0 0 10px;">Wähl links eine Verb-Form und rechts einen Infinitiv — der Satz baut sich automatisch zusammen. Manche Kombinationen klingen im Deutschen ungewöhnlich; ein Hinweis darunter sagt dir, wenn das der Fall ist.</p>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <select id="satzbaukastenVerb" class="challenge-select" style="flex:1; min-width:140px;">
            <optgroup label="🎁 HABEN — etwas wollen/brauchen/mögen">
              ${["want", "need", "like", "have"].map((id) => ExerciseData.FIRST_STEPS_CORE_VERBS.find((v) => v.id === id)).map((verb) => verb.forms.map((f) => `<option value="${f.de}" data-verbid="${verb.id}">${f.de}</option>`).join("")).join("")}
            </optgroup>
            <optgroup label="🎯 MACHEN — eine Tätigkeit ausüben (Fähigkeit/Weg)">
              ${["can", "go"].map((id) => ExerciseData.FIRST_STEPS_CORE_VERBS.find((v) => v.id === id)).map((verb) => verb.forms.map((f) => `<option value="${f.de}" data-verbid="${verb.id}">${f.de}</option>`).join("")).join("")}
            </optgroup>
          </select>
          <select id="satzbaukastenInf" class="challenge-select" style="flex:1; min-width:140px;">
            ${ExerciseData.FIRST_STEPS_INFINITIVES.map((v) => `<option value="${v.de}">${v.de}</option>`).join("")}
          </select>
        </div>
        <p id="satzbaukastenPreview" style="font-weight:800; font-size:1.05rem; margin:14px 0 4px;"></p>
        <p id="satzbaukastenQuestion" style="font-weight:700; font-size:0.95rem; color:var(--teal-400); margin:0 0 4px;"></p>
        <p id="satzbaukastenQuestionNote" class="empty-note" style="margin:0 0 8px; font-size:0.78rem;"></p>
        <p id="satzbaukastenHint" class="empty-note" style="margin:0;"></p>
      </div>

      <p class="eyebrow">🔗 Nebensatz-Baukasten — Hauptsatz + Verbindungswort</p>
      <div class="question-card" style="margin-bottom:20px;">
        <p class="empty-note" style="margin:0 0 10px;">Ein Nebensatz braucht ein Verbindungswort — und danach wandert das Verb ans Satzende. Probier verschiedene Verbindungswörter mit derselben Ergänzung aus: das Verb (<span style="color:#c0392b; font-weight:700;">rot markiert</span>) steht in jedem Fall ganz hinten.</p>
        <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:6px;">
          <select id="nebensatzHaupt" class="challenge-select" style="flex:1; min-width:160px;"></select>
        </div>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <select id="nebensatzVerbinder" class="challenge-select" style="flex:1; min-width:100px;">
            <option value="weil">weil</option>
            <option value="obwohl">obwohl</option>
            <option value="wenn">wenn</option>
            <option value="dass">dass</option>
          </select>
          <select id="nebensatzErgaenzung" class="challenge-select" style="flex:1; min-width:160px;"></select>
        </div>
        <p id="nebensatzPreview" style="font-weight:800; font-size:1.05rem; margin:14px 0 0;"></p>
      </div>

      <p class="eyebrow">✂️ Trennbare Verben — Präfix und Verb gehören zusammen</p>
      <div class="question-card" style="margin-bottom:20px;">
        <p class="empty-note" style="margin:0 0 10px;">Manche Verben trennen sich im Satz: der Grundteil bleibt vorne, das kleine Vorsilben-Wort wandert ans Satzende. Beide Teile sind hier in <span style="color:#2f6b3a; font-weight:700;">derselben Farbe</span> markiert, damit klar bleibt: sie gehören zusammen — auch wenn sie im Satz weit auseinanderstehen.</p>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <select id="trennbarPerson" class="challenge-select" style="flex:1; min-width:100px;">
            <option value="ich">ich</option>
            <option value="du">du</option>
            <option value="er/sie/es">er/sie/es</option>
            <option value="wir">wir</option>
          </select>
          <select id="trennbarVerb" class="challenge-select" style="flex:1; min-width:160px;"></select>
        </div>
        <p id="trennbarPreview" style="font-weight:800; font-size:1.05rem; margin:14px 0 0;"></p>
      </div>

      <details style="margin-bottom:20px;">
        <summary style="cursor:pointer; font-weight:700; color:var(--teal-400); padding:8px 0;">📖 Kompletter Wortschatz-Grundkurs (alle 13 Kapitel) — zum Nachschlagen aufklappen</summary>
        <p class="empty-note" style="margin:8px 0 16px;">Der vollständige, buchbasierte Grundwortschatz bleibt hier erhalten — für alle, die zusätzlich einzelne Wörter nachschlagen möchten. Der Fokus zum Sätzebauen liegt aber oben in den drei Baukästen.</p>

        <p class="eyebrow">Kapitel ${ExerciseData.FIRST_STEPS_CHAPTERS[0].title}</p>
        <div class="breakdown-list" style="margin-bottom:20px;">
          ${ExerciseData.FIRST_STEPS_CHAPTERS[0].vocabKeys.map((key) => {
            const v = firstStepsVocabByKey(key);
            if (!v) return "";
            const syl = ExerciseData.FIRST_STEPS_SYLLABLES[key];
            return `<div class="breakdown-row">
              <span style="font-weight:700;">${syl ? stressHtmlKeepCase(syl, v.de) : v.de}</span>
              <span dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(v, lang)}</span>
            </div>`;
          }).join("")}
        </div>

        <p class="eyebrow">Building Bridges 🌉 — das Kern-Werkzeug</p>
        <div class="breakdown-list" style="margin-bottom:16px;">
          ${ExerciseData.FIRST_STEPS_CORE_VERBS.map((verb) => `
            <div class="question-card" style="margin-bottom:8px;">
              <p class="eyebrow" style="margin-top:0;">${ExerciseData.FIRST_STEPS_SYLLABLES[verb.meaningDe] ? stressHtmlKeepCase(ExerciseData.FIRST_STEPS_SYLLABLES[verb.meaningDe], verb.meaningDe) : verb.meaningDe}</p>
              ${verb.forms.map((f) => `
                <div class="breakdown-row" style="background:transparent; padding:4px 0;">
                  <span style="font-weight:700;">${f.de}</span>
                  <span dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(f, lang)}</span>
                </div>`).join("")}
            </div>`).join("")}
        </div>

        <p class="eyebrow">Infinitive zum Einsetzen (ans Ende anhängen)</p>
        <div class="breakdown-list" style="margin-bottom:20px;">
          ${ExerciseData.FIRST_STEPS_INFINITIVES.map((v) => `
            <div class="breakdown-row">
              <span style="font-weight:700;">${v.de}</span>
              <span dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(v, lang)}</span>
            </div>`).join("")}
        </div>

        <p class="eyebrow">So sieht die Kombination in echten Sätzen aus</p>
        <div class="breakdown-list" style="margin-bottom:20px;">
          ${ExerciseData.FIRST_STEPS_COMBOS.map((s) => `
            <div class="question-card" style="margin-bottom:8px;">
              <p style="font-weight:700; margin:0 0 4px;">${s.de}</p>
              <p class="empty-note" style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(s, lang)}</p>
            </div>`).join("")}
        </div>

        <p class="eyebrow" style="font-weight:400; font-size:0.85rem;">Erste Sätze aus Kapitel 1 zusammengesetzt:</p>
        <div class="breakdown-list" style="margin-bottom:20px;">
          ${ExerciseData.FIRST_STEPS_SENTENCES.map((s) => `
            <div class="question-card" style="margin-bottom:8px;">
              <p style="font-weight:700; margin:0 0 4px;">${s.de}</p>
              <p class="empty-note" style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(s, lang)}</p>
            </div>`).join("")}
        </div>

        ${ExerciseData.FIRST_STEPS_CHAPTERS.slice(1).map((chapter) => `
          <p class="eyebrow">Kapitel ${chapter.title}</p>
          <div class="breakdown-list" style="margin-bottom:20px;">
            ${chapter.vocabKeys.map((key) => {
              const v = firstStepsVocabByKey(key);
              if (!v) return "";
              const syl = ExerciseData.FIRST_STEPS_SYLLABLES[key];
              return `<div class="breakdown-row">
                <span style="font-weight:700;">${syl ? stressHtmlKeepCase(syl, v.de) : v.de}</span>
                <span dir="${rtl ? "rtl" : "ltr"}">${firstStepsTranslate(v, lang)}</span>
              </div>`;
            }).join("")}
          </div>
        `).join("")}

        <p class="eyebrow">Warum wirkt „du" manchmal seltsam?</p>
        <div class="question-card" style="margin-bottom:20px;">
          <p style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${ExerciseData.FIRST_STEPS_CULTURE_NOTES.du_forms[lang] || ExerciseData.FIRST_STEPS_CULTURE_NOTES.du_forms.en}</p>
        </div>
        <p class="eyebrow">Warum wird aus der/die/das im Plural immer „die"?</p>
        <div class="question-card" style="margin-bottom:20px;">
          <p style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${ExerciseData.FIRST_STEPS_CULTURE_NOTES.plural_article[lang] || ExerciseData.FIRST_STEPS_CULTURE_NOTES.plural_article.en}</p>
        </div>
        <p class="eyebrow">Warum "zerfällt" ein Verb manchmal (z. B. ankommen)?</p>
        <div class="question-card" style="margin-bottom:20px;">
          <p style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${ExerciseData.FIRST_STEPS_CULTURE_NOTES.separable_verbs[lang] || ExerciseData.FIRST_STEPS_CULTURE_NOTES.separable_verbs.en}</p>
        </div>
        <p class="eyebrow">Warum steht das Verb bei "weil/dass/ob" plötzlich ganz am Ende?</p>
        <div class="question-card" style="margin-bottom:20px;">
          <p style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${ExerciseData.FIRST_STEPS_CULTURE_NOTES.verb_at_end[lang] || ExerciseData.FIRST_STEPS_CULTURE_NOTES.verb_at_end.en}</p>
        </div>
        <p class="eyebrow">Warum werden so viele Wörter großgeschrieben?</p>
        <div class="question-card">
          <p style="margin:0;" dir="${rtl ? "rtl" : "ltr"}">${ExerciseData.FIRST_STEPS_CULTURE_NOTES.noun_capitalization[lang] || ExerciseData.FIRST_STEPS_CULTURE_NOTES.noun_capitalization.en}</p>
        </div>
      </details>
    `;
    document.getElementById("firstStepsLangSelect").addEventListener("change", (e) => {
      firstStepsLangOverride = e.target.value || null;
      renderFirstSteps();
    });
    // WICHTIG — der Satz-Baukasten: eine kleine, handkuratierte Liste an Verb+Infinitiv-Kombinationen,
    // die im Deutschen inhaltlich ungewöhnlich klingen (z. B. "ich brauche schlafen" statt "ich muss
    // schlafen") — nicht erschöpfend, sondern ein erster, pragmatischer Baustein dieser Idee, der bei
    // den offensichtlichsten Fällen einen Hinweis gibt, statt stillschweigend jede Kombination als
    // "richtig" durchgehen zu lassen.
    const SATZBAUKASTEN_UNGEWOEHNLICH = {
      need: ["schlafen", "sehen", "schauen", "denken"],
      like: ["bezahlen"],
      // "gehen + Infinitiv" funktioniert im Deutschen nur bei einer kleinen Gruppe von
      // "Tätigkeit aufsuchen"-Ausdrücken (schlafen gehen, arbeiten gehen) — bei den meisten
      // anderen Infinitiven aus der Liste klingt die Kombination unpassend.
      go: ["sehen", "schauen", "verstehen", "lernen", "wissen", "denken", "geben", "nehmen", "machen", "finden", "besuchen", "beginnen", "schreiben", "lesen", "bezahlen", "fragen", "helfen"],
      // "haben zu + Infinitiv" (die Bedeutung von "müssen", siehe Erklärtext beim Kernverb) klingt
      // im Alltag nur bei pflichtartigen Tätigkeiten natürlich — bei entspannten Freizeit-Verben
      // wirkt die formelle "haben zu"-Konstruktion unpassend.
      have: ["spielen", "essen", "trinken", "reisen"],
    };
    function updateSatzbaukastenPreview(playSound) {
      const verbSelect = document.getElementById("satzbaukastenVerb");
      const infSelect = document.getElementById("satzbaukastenInf");
      if (!verbSelect || !infSelect) return;
      const verbForm = verbSelect.value;
      const verbId = verbSelect.selectedOptions[0]?.dataset.verbid;
      const inf = infSelect.value;
      document.getElementById("satzbaukastenPreview").textContent = `${verbForm} ... ${inf}.`;
      // WICHTIG — Auto-Frage wie beschrieben: unter jeder Aussage steht automatisch die passende
      // Frageform (Verb-Erst-Stellung). Bei "ich" wird bewusst auf die "du"-Form umgeschaltet, da
      // man sich selbst normalerweise nicht fragt ("Möchte ich...?" klingt unbeholfen) — mit einem
      // kurzen Hinweis, warum die Person dabei automatisch gewechselt wurde.
      const spaceIdx = verbForm.indexOf(" ");
      let qPronoun = verbForm.slice(0, spaceIdx);
      let qVerb = verbForm.slice(spaceIdx + 1);
      const noteEl = document.getElementById("satzbaukastenQuestionNote");
      if (qPronoun === "ich") {
        const verbObj = ExerciseData.FIRST_STEPS_CORE_VERBS.find((v) => v.id === verbId);
        const duForm = verbObj?.forms.find((f) => f.de.startsWith("du "));
        if (duForm) {
          const duSpaceIdx = duForm.de.indexOf(" ");
          qPronoun = duForm.de.slice(0, duSpaceIdx);
          qVerb = duForm.de.slice(duSpaceIdx + 1);
          noteEl.textContent = "💡 Man fragt sich selbst normalerweise nicht — hier automatisch auf die du-Form umgestellt.";
        } else {
          noteEl.textContent = "";
        }
      } else {
        noteEl.textContent = "";
      }
      const qVerbCap = qVerb.charAt(0).toUpperCase() + qVerb.slice(1);
      document.getElementById("satzbaukastenQuestion").textContent = `❓ ${qVerbCap} ${qPronoun} ... ${inf}?`;
      const unusual = (SATZBAUKASTEN_UNGEWOEHNLICH[verbId] || []).includes(inf);
      const hintEl = document.getElementById("satzbaukastenHint");
      hintEl.textContent = unusual
        ? "🤔 Diese Kombination klingt im Deutschen eher ungewöhnlich."
        : "✅ Das klingt nach einer ganz normalen deutschen Kombination.";
      hintEl.style.color = unusual ? "var(--red-400, #c0392b)" : "var(--teal-400)";
      // WICHTIG — wie gewünscht: bei einer ungewöhnlichen Kombination werden BEIDE Auswahlfelder
      // rot umrandet (nicht nur der Hinweistext) und ein kurzer Fehler-Ton spielt — aber nur bei
      // einer echten Nutzer-Änderung, nicht schon beim ersten, automatischen Laden der Seite.
      const errorBorder = unusual ? "2px solid #c0392b" : "";
      verbSelect.style.border = errorBorder;
      infSelect.style.border = errorBorder;
      if (unusual && playSound) playErrorTone();
    }
    document.getElementById("satzbaukastenVerb")?.addEventListener("change", () => updateSatzbaukastenPreview(true));
    document.getElementById("satzbaukastenInf")?.addEventListener("change", () => updateSatzbaukastenPreview(true));
    updateSatzbaukastenPreview(false);

    // Nebensatz-Baukasten: Hauptsatz-Optionen und passende Nebensatz-Ergänzungen (das Verb steht
    // hier bewusst schon an letzter Stelle in jeder Ergänzung, wie es im deutschen Nebensatz nach
    // einem Verbindungswort sein muss — genau das soll farblich hervorgehoben sichtbar werden).
    const NEBENSATZ_HAUPTSAETZE = ["Ich bleibe zu Hause", "Wir gehen nicht raus", "Sie ist müde", "Ich rufe dich an"];
    const NEBENSATZ_ERGAENZUNGEN = [
      { text: "es regnet", verb: "regnet" },
      { text: "ich krank bin", verb: "bin" },
      { text: "das Wetter schlecht ist", verb: "ist" },
      { text: "sie arbeiten muss", verb: "muss" },
      { text: "wir Zeit haben", verb: "haben" },
    ];
    const hauptSelect = document.getElementById("nebensatzHaupt");
    const ergSelect = document.getElementById("nebensatzErgaenzung");
    if (hauptSelect) hauptSelect.innerHTML = NEBENSATZ_HAUPTSAETZE.map((h) => `<option value="${h}">${h}</option>`).join("");
    if (ergSelect) ergSelect.innerHTML = NEBENSATZ_ERGAENZUNGEN.map((e) => `<option value="${e.text}" data-verb="${e.verb}">${e.text}</option>`).join("");
    // Handkuratierte Liste an Hauptsatz+Ergänzung-Paaren, die zwar grammatikalisch fehlerfrei
    // sind, inhaltlich aber keinen rechten Sinn ergeben (z. B. "Sie ist müde, weil sie arbeiten
    // muss" — als konkretes Beispiel gemeldet).
    const NEBENSATZ_UNPASSEND = new Set([
      "Sie ist müde|es regnet", "Sie ist müde|sie arbeiten muss", "Sie ist müde|wir Zeit haben",
      "Ich bleibe zu Hause|wir Zeit haben", "Wir gehen nicht raus|wir Zeit haben",
    ]);
    function updateNebensatzPreview(playSound) {
      const haupt = document.getElementById("nebensatzHaupt")?.value;
      const verbinder = document.getElementById("nebensatzVerbinder")?.value;
      const ergOption = ergSelect?.selectedOptions[0];
      if (!haupt || !verbinder || !ergOption) return;
      const ergText = ergOption.value;
      const verb = ergOption.dataset.verb;
      // Das Ergänzungs-Verb farblich hervorheben, egal an welcher Stelle im Text es steht.
      const highlighted = ergText.replace(verb, `<span style="color:#c0392b; font-weight:700;">${verb}</span>`);
      document.getElementById("nebensatzPreview").innerHTML = `${haupt}, ${verbinder} ${highlighted}.`;
      const unpassend = NEBENSATZ_UNPASSEND.has(`${haupt}|${ergText}`);
      const errorBorder = unpassend ? "2px solid #c0392b" : "";
      document.getElementById("nebensatzHaupt").style.border = errorBorder;
      document.getElementById("nebensatzErgaenzung").style.border = errorBorder;
      if (unpassend && playSound) playErrorTone();
    }
    document.getElementById("nebensatzHaupt")?.addEventListener("change", () => updateNebensatzPreview(true));
    document.getElementById("nebensatzVerbinder")?.addEventListener("change", () => updateNebensatzPreview(true));
    document.getElementById("nebensatzErgaenzung")?.addEventListener("change", () => updateNebensatzPreview(true));
    updateNebensatzPreview(false);

    // Trennbare Verben: Grundform-Konjugation (ohne Präfix) je Person + das Präfix, das ans
    // Satzende wandert. Beide Teile bekommen dieselbe Farbe, damit ihre Zusammengehörigkeit auch
    // über die Distanz im Satz hinweg sichtbar bleibt.
    const TRENNBARE_VERBEN = [
      { name: "ankommen", prefix: "an", forms: { "ich": "komme", "du": "kommst", "er/sie/es": "kommt", "wir": "kommen" }, rest: "am Bahnhof" },
      { name: "abgeben", prefix: "ab", forms: { "ich": "gebe", "du": "gibst", "er/sie/es": "gibt", "wir": "geben" }, rest: "das Buch" },
      { name: "anrufen", prefix: "an", forms: { "ich": "rufe", "du": "rufst", "er/sie/es": "ruft", "wir": "rufen" }, rest: "meine Mutter" },
      { name: "aufwachen", prefix: "auf", forms: { "ich": "wache", "du": "wachst", "er/sie/es": "wacht", "wir": "wachen" }, rest: "früh" },
      { name: "einkaufen", prefix: "ein", forms: { "ich": "kaufe", "du": "kaufst", "er/sie/es": "kauft", "wir": "kaufen" }, rest: "am Wochenende" },
      { name: "anfangen", prefix: "an", forms: { "ich": "fange", "du": "fängst", "er/sie/es": "fängt", "wir": "fangen" }, rest: "jetzt" },
    ];
    const trennbarVerbSelect = document.getElementById("trennbarVerb");
    if (trennbarVerbSelect) trennbarVerbSelect.innerHTML = TRENNBARE_VERBEN.map((v) => `<option value="${v.name}">${v.name}</option>`).join("");
    function updateTrennbarPreview() {
      const person = document.getElementById("trennbarPerson")?.value;
      const verbName = trennbarVerbSelect?.value;
      const verb = TRENNBARE_VERBEN.find((v) => v.name === verbName);
      if (!person || !verb) return;
      const stamm = verb.forms[person];
      const highlight = (t) => `<span style="color:#2f6b3a; font-weight:700;">${t}</span>`;
      document.getElementById("trennbarPreview").innerHTML = `${person} ${highlight(stamm)} ${verb.rest} ${highlight(verb.prefix)}.`;
    }
    document.getElementById("trennbarPerson")?.addEventListener("change", updateTrennbarPreview);
    trennbarVerbSelect?.addEventListener("change", updateTrennbarPreview);
    updateTrennbarPreview();
  }
  /* Das Wörterbuch baute bisher ALLE 8606 Einträge auf einmal in die
     Seite — 1,3 Millionen Zeichen HTML und für jedes Wort ein eigener
     Klick-Handler. Auf einem Telefon reicht dafür der Speicher nicht,
     auf dem iPhone dauert es sehr lange. Jetzt kommen sie in Portionen,
     und ein einziger Handler bedient alle Vorlese-Knöpfe. */
  const DICT_SEITE = 60;
  let dictGezeigt = DICT_SEITE;

  /* ============================================================
     MEIN WORTSCHATZ
     ------------------------------------------------------------
     In anderen Apps übt man, was vorgelegt wird. Hier soll man selbst
     bestimmen können: im Wörterbuch die Wörter merken, die man gerade
     braucht, und dann genau mit diesen üben — Betonung, Aussprache,
     Bedeutung.

     Gespeichert wird im Profil (extraProfileData.meinWortschatz), nicht
     auf dem Gerät: Wer am Telefon markiert, findet es am Rechner wieder.
     Damit das Markieren trotzdem sofort reagiert, wird die Liste hier
     mitgeführt und im Hintergrund gespeichert.
     ============================================================ */
  let meinWortschatzZwischen = null;
  let meinWortschatzFuer = null;   // zu welchem Konto die Liste im Speicher gehört
  function meinWortschatz() {
    /* Wichtig: die Liste im Speicher gehört zu EINEM Konto. Ohne diese
       Prüfung sah die nächste Person, die sich am selben Gerät anmeldet,
       die Merkwörter der vorherigen. */
    const nutzer = Backend.currentUser();
    const id = (nutzer && nutzer.id) || null;
    if (meinWortschatzZwischen && meinWortschatzFuer === id) return meinWortschatzZwischen;
    const p = Backend.currentProfile();
    meinWortschatzZwischen = new Set(((p && p.extraProfileData && p.extraProfileData.meinWortschatz) || []));
    meinWortschatzFuer = id;
    return meinWortschatzZwischen;
  }
  function wortschatzStandVerwerfen() { meinWortschatzZwischen = null; meinWortschatzFuer = null; }

  /* Einmal an EINER Stelle speichern — mit echter Erfolgsprüfung.
     Supabase meldet einen an der Zugriffsregel gescheiterten Schreibvorgang
     nicht als Fehler, sondern liefert still {ok:false}; wer nur try/catch
     benutzt, hält das für gelungen. */
  async function wortschatzSichern(menge) {
    const antwort = await Backend.updateExtraProfileField("meinWortschatz", [...menge]);
    if (antwort && antwort.ok === false) throw new Error(antwort.message || "Konnte nicht gespeichert werden.");
    return true;
  }
  function imWortschatz(wort) { return meinWortschatz().has(wort); }
  async function wortschatzUmschalten(wort) {
    if (!Backend.currentUser()) { showToast("Zum Merken bitte zuerst anmelden."); return false; }
    const menge = meinWortschatz();
    const drin = menge.has(wort);
    if (drin) menge.delete(wort); else menge.add(wort);
    try { await wortschatzSichern(menge); }
    catch (e) {
      // Konnte nicht gespeichert werden: die Anzeige darf nicht lügen.
      if (drin) menge.add(wort); else menge.delete(wort);
      showToast("⚠️ Nicht gespeichert: " + (e.message || "Bitte Verbindung prüfen."));
      return drin;
    }
    return !drin;
  }

  /* ============================================================
     WORTQUELLE — womit ein Spiel übt
     ------------------------------------------------------------
     Bisher zog jedes Spiel seine Wörter aus dem ganzen Wörterbuch,
     höchstens nach Niveau gefiltert. Gewünscht — und das ist der
     eigentliche Unterschied zu einer Vokabel-App von der Stange:
     man soll mit SEINEN Wörtern spielen können.

     Es gibt drei Quellen, und jedes Spiel merkt sich seine eigene
     Wahl:

     1. Alles, was zum eingestellten Niveau passt (wie bisher).
     2. ★ Mein Wortschatz — die im Wörterbuch mit dem Stern
        markierten Wörter.
     3. 📋 Eine eigene Wortliste — ein Stapel Wörter, den man einmal
        einreicht (Kapitel aus dem Kursbuch, Prüfungsliste, was der
        Lehrer diktiert hat) und dann in jedem Spiel wiederfindet.

     Wichtig für die Ehrlichkeit: eine Quelle mit fünf Wörtern kann
     keine Runde über zehn tragen. Deshalb sagt wortQuelleHinweisHtml
     vorher, wie viele Wörter da sind, und die Spiele fallen auf den
     ganzen Wortschatz zurück, statt eine halbe Runde zu zeigen.
     ============================================================ */
  const WORTLISTEN_FELD = "wortlisten";
  let wortlistenZwischen = null;
  function meineWortlisten() {
    if (wortlistenZwischen) return wortlistenZwischen;
    const p = Backend.currentProfile();
    wortlistenZwischen = ((p && p.extraProfileData && p.extraProfileData[WORTLISTEN_FELD]) || []).slice();
    return wortlistenZwischen;
  }
  function wortlisteMitId(id) { return meineWortlisten().find((l) => l.id === id) || null; }
  async function wortlisteSichern(listen) {
    wortlistenZwischen = listen;
    try { await Backend.updateExtraProfileField(WORTLISTEN_FELD, listen); return true; }
    catch (e) { showToast("Konnte gerade nicht gespeichert werden — bitte Verbindung prüfen."); return false; }
  }
  async function wortlisteSpeichern(name, woerter) {
    const listen = meineWortlisten().slice();
    const id = "wl" + Date.now().toString(36);
    listen.unshift({ id, name: String(name || "Meine Liste").slice(0, 40), woerter, am: new Date().toISOString() });
    const ok = await wortlisteSichern(listen.slice(0, 20));
    return ok ? id : null;
  }
  async function wortlisteLoeschen(id) {
    await wortlisteSichern(meineWortlisten().filter((l) => l.id !== id));
  }
  /* Eine bestehende Liste ändern — umbenennen, Wörter ergänzen oder
     einzelne wieder herausnehmen. Vorher konnte man eine Liste nur
     anlegen und wegwerfen; wer ein Wort vergessen hatte, musste die
     ganze Liste noch einmal eintippen. */
  async function wortlisteAendern(id, aenderung) {
    const listen = meineWortlisten().map((l) => {
      if (l.id !== id) return l;
      const neuL = { ...l };
      if (aenderung.name !== undefined) neuL.name = String(aenderung.name || l.name).slice(0, 40);
      if (aenderung.woerter !== undefined) neuL.woerter = aenderung.woerter.slice(0, 400);
      neuL.geaendert = new Date().toISOString();
      return neuL;
    });
    return wortlisteSichern(listen);
  }

  /* Welche Spiele mit einer Wortliste üben können — als Reiter-Namen,
     damit die Spieleübersicht sie hervorheben kann. WORTQUELLE_SPIELE
     nennt dieselben Spiele unter ihrem internen Kürzel. */
  const WORTQUELLE_ZU_SUB = {
    stresstrainer: "sub-stresstrainer",
    silbenturm: "sub-silbenturm",
    flussfuchs: "sub-flussfuchs",
    setzerei: "sub-setzerei",
    wortkette: "sub-wortkette",
    augenblick: "sub-augenblick",
    wordbuild: "sub-wordbuild",
  };
  /* Solange gesetzt, hebt die Spieleübersicht genau diese Spiele
     hervor. Wird beim Verlassen der Übersicht wieder gelöscht —
     gewünscht war ausdrücklich „aber nur in dem Moment, wenn man sagt:
     mit Wortliste spielen". */
  let wortlisteImBlick = null;
  let wortlisteAnkunft = false;   // dieser eine Sprung kommt aus einer Wortliste

  /* ============================================================
     GELIEHENE WORTLISTE AUS EINEM DUELL
     ------------------------------------------------------------
     Fordert jemand mit seiner Wortliste heraus, übt die andere
     Seite mit GENAU denselben Wörtern. Sonst wäre der Vergleich
     der Prozentzahlen am Ende sinnlos: der eine mit zwanzig
     Wörtern aus Kapitel 7, der andere mit dem ganzen Wörterbuch.

     Solange eine geliehene Liste gilt, ist die eigene Wahl
     ausdrücklich NICHT markiert — man spielt ja gerade nicht mit
     seiner eigenen Liste. Nach der Runde ist der Zustand weg.
     ============================================================ */
  /* Von der Ergebniskategorie einer Herausforderung zum Kürzel, unter
     dem das Spiel seine Wortquelle führt. Die beiden Namen sind
     historisch verschieden — „betonungstrainer" zählt die Ergebnisse,
     „stresstrainer" wählt die Wörter. */
  const SPIEL_ZU_WORTQUELLE = {
    betonungstrainer: "stresstrainer",
    silbenturm: "silbenturm",
    flussfuchs: "flussfuchs",
    setzerei: "setzerei",
    wortkette: "wortkette",
    augenblick: "augenblick",
    wortbaustelle: "wordbuild",
    meinesaetze: "meinesaetze",
  };
  /* Die Liste, die eine bestimmte Herausforderung mitgebracht hat.
     Gefüllt beim Laden der Herausforderungen, damit das Annehmen nicht
     erst nachfragen muss. */
  const herausforderungListen = {};
  function herausforderungListe(id) { return herausforderungListen[id] || null; }
  function herausforderungenMerken(liste) {
    (liste || []).forEach((c) => {
      const w = c && c.extra && c.extra.wortliste;
      if (w && Array.isArray(w.woerter) && w.woerter.length >= 4) {
        herausforderungListen[c.id] = { name: w.name || "Wortliste", woerter: w.woerter, von: w.von || c.fromName || "" };
      }
    });
  }

  const geliehenListe = {};   // { spielKuerzel: { name, woerter, von } }
  function geliehenSetzen(spielKuerzel, liste) {
    if (liste) geliehenListe[spielKuerzel] = liste;
    else delete geliehenListe[spielKuerzel];
  }
  function geliehenAktiv(spielKuerzel) { return geliehenListe[spielKuerzel] || null; }
  function geliehenAlleWeg() { Object.keys(geliehenListe).forEach((k) => delete geliehenListe[k]); }
  /* Der Hinweisstreifen im Spiel — man soll wissen, warum hier
     fremde Wörter stehen. */
  function geliehenHinweisHtml(spielKuerzel) {
    const g = geliehenAktiv(spielKuerzel);
    if (!g) return "";
    return `<p class="wortliste-geliehen">🎮 Duell: Du übst mit <strong>${g.von || "der herausfordernden Person"}</strong>s Liste
      <strong>${g.name || "Wortliste"}</strong> — ${g.woerter.length} ${g.woerter.length === 1 ? "Wort" : "Wörter"}. Ihr habt damit dieselbe Aufgabe.</p>`;
  }

  /* Das Nachschlagewerk für eingereichte Wörter. Gebaut wird es aus
     denselben Einträgen, die auch das Wörterbuch zeigt — was man
     einreicht, kann also nur ankommen, wenn es die App auch kennt.
     Nachgeschlagen wird großzügig: mit und ohne Artikel, groß wie
     klein, und eine Pluralform findet ihren Singular. */
  let wortIndexZwischen = null;
  let wortIndexStand = -1;
  function wortIndex() {
    const stand = VocabData.WORDS.length;
    if (wortIndexZwischen && wortIndexStand === stand) return wortIndexZwischen;
    const karte = new Map();
    buildDictionaryEntries().forEach((e) => {
      if (!e || !e.word) return;
      if (!karte.has(dictKey(e.word))) karte.set(dictKey(e.word), e);
    });
    wortIndexZwischen = karte;
    wortIndexStand = stand;
    return karte;
  }
  function wortNachschlagen(eingabe) {
    const karte = wortIndex();
    const roh = String(eingabe || "").trim().replace(/[.,;:!?"„“»«]+$/g, "").trim();
    if (!roh) return null;
    // Erst so, wie es dasteht; dann als Nomen, dann als Kleinschreibung —
    // wer „tisch" einreicht, meint „der Tisch".
    const versuche = [roh, roh.charAt(0).toUpperCase() + roh.slice(1), roh.toLowerCase()];
    for (const v of versuche) {
      const treffer = karte.get(dictKey(v));
      if (treffer) return treffer;
    }
    for (const v of versuche) {
      for (const k of singularKandidaten(v)) {
        const treffer = karte.get(k);
        if (treffer) return treffer;
      }
    }
    /* Zuletzt: gebeugte Verben und Adjektive auf ihre Grundform
       zurückführen. Erst hier, damit ein direkter Treffer immer
       Vorrang hat — „das Essen" soll das Nomen finden, nicht das
       Verb „essen". */
    for (const kandidat of grundformKandidaten(roh)) {
      for (const v of [kandidat, kandidat.charAt(0).toUpperCase() + kandidat.slice(1)]) {
        const treffer = karte.get(dictKey(v));
        if (treffer) return treffer;
      }
    }
    return null;
  }
  /* Eine ganze eingereichte Liste einlesen. Getrennt wird an Zeilen,
     Kommas und Semikolons — man soll nicht erst umformatieren müssen,
     nur weil man aus einem Kursbuch abschreibt. Nummerierungen und
     Aufzählungszeichen am Zeilenanfang fallen weg, ebenso alles hinter
     einem Gedankenstrich oder Gleichheitszeichen (dort steht meist die
     Übersetzung: „der Tisch – table"). */
  function wortlisteEinlesen(text) {
    const roh = String(text || "")
      .split(/[\n;,]+/)
      .map((z) => z.replace(/^\s*(\d+[.)]|[-–—•*])\s*/, "").split(/\s+[–—=]\s+|\t/)[0].trim())
      .filter(Boolean);
    const gefunden = [], fehlend = [], gesehen = new Set();
    roh.forEach((eingabe) => {
      if (eingabe.length > 60) return;
      const treffer = wortNachschlagen(eingabe);
      if (!treffer) { if (!fehlend.includes(eingabe)) fehlend.push(eingabe); return; }
      if (gesehen.has(treffer.word)) return;
      gesehen.add(treffer.word);
      gefunden.push({ eingabe, wort: treffer.word, level: treffer.level, thema: treffer.category });
    });
    return { gefunden, fehlend, gesamt: roh.length };
  }

  /* Welche Quelle ein Spiel gerade benutzt. Die Wahl gilt je Spiel und
     hält die Sitzung über — beim Neuladen steht wieder „Alle", weil
     eine stillschweigend enge Auswahl schlimmer ist als eine, die man
     noch einmal antippt. */
  /* Die Spiele, die eine Wortquelle anbieten. Sie steht hier an einer
     Stelle, damit „Damit spielen" in den Wortlisten alle auf einmal
     umstellen kann. */
  const WORTQUELLE_SPIELE = ["stresstrainer", "silbenturm", "flussfuchs",
    "setzerei", "wortkette", "augenblick", "wordbuild", "meinesaetze"];
  const wortQuelleWahl = {};
  function wortQuelleAktiv(spiel) {
    const wahl = wortQuelleWahl[spiel] || "alle";
    if (wahl.startsWith("liste:") && !wortlisteMitId(wahl.slice(6))) return "alle";
    return wahl;
  }
  function wortQuelleName(wahl) {
    if (wahl === "wortschatz") return "★ Mein Wortschatz";
    if (wahl.startsWith("liste:")) {
      const l = wortlisteMitId(wahl.slice(6));
      return l ? "📋 " + l.name : "📋 Liste";
    }
    return "Alle Wörter";
  }
  /* Der Filter selbst. Er bekommt eine fertige Liste von
     Wörterbuch-Einträgen und gibt zurück, was die Quelle davon
     übriglässt. */
  function wortQuelleFilter(spiel, eintraege) {
    /* Eine geliehene Liste aus einem Duell schlägt jede eigene Wahl —
       beide Seiten müssen dieselben Wörter bekommen. */
    const geliehen = geliehenAktiv(spiel);
    if (geliehen) {
      const menge = new Set(geliehen.woerter);
      const treffer = eintraege.filter((e) => menge.has(e.word));
      // Reicht die fremde Liste für dieses Spiel nicht, lieber alles
      // nehmen als eine halbe Runde zu zeigen.
      return treffer.length >= 4 ? treffer : eintraege;
    }
    const wahl = wortQuelleAktiv(spiel);
    if (wahl === "wortschatz") {
      const menge = meinWortschatz();
      return eintraege.filter((e) => menge.has(e.word));
    }
    if (wahl.startsWith("liste:")) {
      const l = wortlisteMitId(wahl.slice(6));
      if (!l) return eintraege;
      const menge = new Set(l.woerter);
      return eintraege.filter((e) => menge.has(e.word));
    }
    return eintraege;
  }
  function wortQuelleChipsHtml(spiel) {
    /* Läuft ein Duell mit fremder Liste, wird die eigene Auswahl gar
       nicht erst angeboten: Es gibt gerade nichts zu wählen, und eine
       markierte eigene Liste wäre schlicht gelogen. */
    const geliehen = geliehenAktiv(spiel);
    if (geliehen) return geliehenHinweisHtml(spiel);
    const wahl = wortQuelleAktiv(spiel);
    const listen = meineWortlisten();
    const gemerkt = meinWortschatz().size;
    if (!Backend.currentUser()) return "";
    if (!gemerkt && !listen.length) return "";
    return `<div class="trophy-case wsm-chips wortquelle-chips">
      <button type="button" class="trophy-chip ${wahl === "alle" ? "selected" : ""}" data-wortquelle="alle">Alle Wörter</button>
      ${gemerkt ? `<button type="button" class="trophy-chip ${wahl === "wortschatz" ? "selected" : ""}" data-wortquelle="wortschatz">★ Mein Wortschatz (${gemerkt})</button>` : ""}
      ${listen.map((l) => `<button type="button" class="trophy-chip ${wahl === "liste:" + l.id ? "selected" : ""}" data-wortquelle="liste:${l.id}">📋 ${l.name} (${l.woerter.length})</button>`).join("")}
    </div>`;
  }
  function wortQuelleBinden(area, spiel, neuAnfangen) {
    area.querySelectorAll("[data-wortquelle]").forEach((b) => b.addEventListener("click", () => {
      wortQuelleWahl[spiel] = b.dataset.wortquelle;
      neuAnfangen();
    }));
  }
  /* Wenn die gewählte Quelle für dieses Spiel zu dünn ist, sagt das
     Spiel es und übt mit allem weiter — statt kommentarlos etwas
     anderes zu tun, als man angetippt hat. */
  function wortQuelleHinweisHtml(spiel, vorhanden, mindestens) {
    const wahl = wortQuelleAktiv(spiel);
    if (wahl === "alle") return "";
    if (vorhanden >= mindestens) return `<p class="empty-note wortquelle-stand">Geübt wird mit: ${wortQuelleName(wahl)} — ${vorhanden} passende Wörter.</p>`;
    return `<p class="empty-note wortquelle-stand">${wortQuelleName(wahl)} hat für dieses Spiel nur ${vorhanden} passende ${vorhanden === 1 ? "Wort" : "Wörter"} (nötig sind ${mindestens}) — deshalb kommen die übrigen aus dem ganzen Wortschatz.</p>`;
  }

  function dictKarte(e) {
    const gemerkt = imWortschatz(e.word);
    return `
          <div class="vocab-card">
            <div>
              <div class="vocab-word">${e.word}${e.level ? ` <span class="empty-note" style="font-size:0.7rem;">${e.level}</span>` : ""}</div>
              <div class="vocab-syl">${betonungAnzeigen(e.syl)}</div>
              <div class="vocab-en">${e.meaning || (e.verified ? "" : "aus dem Übungsinhalt — Bedeutung nicht hinterlegt")}</div>
              ${e.example ? `<div class="vocab-example">„${e.example}"</div>` : ""}
            </div>
            <div class="vocab-karte-knoepfe">
              <button type="button" class="speak-btn" data-word="${e.word.replace(/"/g, "&quot;")}" aria-label="Aussprache anhören">🔊</button>
              <button type="button" class="merk-btn ${gemerkt ? "gemerkt" : ""}" data-merken="${e.word.replace(/"/g, "&quot;")}"
                aria-pressed="${gemerkt}" title="${gemerkt ? "Aus meinem Wortschatz entfernen" : "In meinen Wortschatz aufnehmen"}">${gemerkt ? "★" : "☆"}</button>
            </div>
          </div>`;
  }
  /* ------------------------------------------------------------
     Die Treffersuche und das Zeichnen der Trefferliste stehen für
     sich, damit beim Tippen NUR die Liste neu entsteht. Vorher wurde
     der ganze Bereich neu gebaut — mitsamt dem Eingabefeld, in dem
     man gerade schrieb. Genau das war der gemeldete Abbruch nach
     jedem Buchstaben.
     ------------------------------------------------------------ */
  let dictFilterText = "";
  let dictTippUhr = null;
  function dictGefiltert(filter) {
    const suchtext = String(filter || "").toLowerCase().trim();
    let list = buildDictionaryEntries();
    if (suchtext) {
      /* Reihenfolge der Treffer, und das ist der eigentliche Punkt:
         wer „au" eintippt, will Auge, Augenblick, Auster, außen sehen
         — nicht „abarbeiten", nur weil in dessen ERKLÄRUNG das Wort
         „Aufgaben" steht. Deshalb wird nicht nur gefiltert, sondern
         auch sortiert: erst die Wörter, die so ANFANGEN, dann die, die
         die Buchstaben irgendwo enthalten, und ganz zuletzt die
         Treffer aus der Bedeutung. */
      const rang = (e) => {
        const wort = e.word.toLowerCase();
        const nackt = wort.replace(/^(der|die|das)\s+/, "");
        if (nackt.startsWith(suchtext) || wort.startsWith(suchtext)) return 0;
        if (nackt.includes(suchtext)) return 1;
        if ((e.meaning || "").toLowerCase().includes(suchtext)) return 2;
        return 3;
      };
      list = list.map((e) => ({ e, r: rang(e) })).filter((x) => x.r < 3)
        .sort((a, b) => a.r - b.r).map((x) => x.e);
    }
    if (dictLevelFilter !== "alle") {
      list = dictLevelFilter === "erweitert" ? list.filter((e) => !e.verified) : list.filter((e) => e.level === dictLevelFilter);
    }
    if (dictCategoryFilter !== "alle") list = list.filter((e) => e.category === dictCategoryFilter);
    if (dictNurGemerkte) list = list.filter((e) => imWortschatz(e.word));
    return list;
  }
  /* Nur das Gitter, den Nachladeknopf und den Leer-Hinweis erneuern. */
  /* AUSDRÜCKLICH GEWÜNSCHT: das Wörterbuch soll enthalten, was
     gebraucht wird — und wachsen können, ohne dass jemand eine Datei
     hochlädt. Findet die Suche nichts, steht hier der Vorschlagskasten.
     Er wird eigens gezeichnet, weil beim Tippen nur die Trefferliste
     erneuert wird und nicht die ganze Ansicht. */
  function dictVorschlagZeichnen(leer) {
    const host = document.getElementById("dictVorschlagHost");
    if (!host) return;
    const wort = dictFilterText.trim();
    if (!leer || wort.length < 2) { host.innerHTML = ""; return; }
    if (host.dataset.wort === wort) return;   // steht schon da
    host.dataset.wort = wort;
    host.innerHTML = `
      <div class="question-card wort-vorschlag" style="margin-top:10px;">
        <p class="eyebrow" style="margin-top:0;">➕ Fehlt „${escapeHtml(wort)}"?</p>
        <p class="empty-note" style="margin:0 0 10px;">Trag ein, was du weißt — schon eine Erklärung reicht. Der Eintrag geht zur Prüfung und steht danach für alle im Wörterbuch.</p>
        <div class="wort-vorschlag-felder">
          <input type="text" id="vorschlagArtikel" placeholder="der / die / das (wenn es ein Nomen ist)" maxlength="12">
          <input type="text" id="vorschlagBedeutung" placeholder="Was heißt es? *" maxlength="200">
          <input type="text" id="vorschlagBeispiel" placeholder="Ein Satz, in dem es vorkommt" maxlength="200">
          <input type="text" id="vorschlagSilben" placeholder="Silben mit Betonung, z. B. FEN-ster (wenn du sie kennst)" maxlength="60">
        </div>
        <button type="button" class="btn btn-coffee" id="vorschlagSenden" style="margin-top:8px;">Vorschlagen</button>
        <p class="empty-note" id="vorschlagMeldung" style="margin:8px 0 0;"></p>
      </div>`;
    host.querySelector("#vorschlagSenden").addEventListener("click", async () => {
      const meldung = host.querySelector("#vorschlagMeldung");
      const bedeutung = host.querySelector("#vorschlagBedeutung").value.trim();
      if (!Backend.currentUser()) { meldung.textContent = "Dafür musst du angemeldet sein."; return; }
      if (bedeutung.length < 3) { meldung.textContent = "Bitte schreib wenigstens kurz, was das Wort heißt."; return; }
      try {
        await Backend.wortVorschlagen(wort, {
          artikel: host.querySelector("#vorschlagArtikel").value.trim(),
          bedeutung,
          beispiel: host.querySelector("#vorschlagBeispiel").value.trim(),
          silben: host.querySelector("#vorschlagSilben").value.trim(),
        });
        meldung.textContent = "✅ Danke — der Vorschlag ist zur Prüfung eingegangen.";
        host.querySelector("#vorschlagSenden").disabled = true;
      } catch (e) { meldung.textContent = "⚠️ " + (e.message || "Hat nicht geklappt."); }
    });
  }

  function dictListeErneuern() {
    const gitter = document.getElementById("dictGrid");
    if (!gitter) return;
    const list = dictGefiltert(dictFilterText);
    gitter.innerHTML = list.slice(0, dictGezeigt).map(dictKarte).join("");
    const leer = document.getElementById("dictLeer");
    if (leer) leer.style.display = list.length ? "none" : "";
    dictVorschlagZeichnen(list.length === 0);
    const knopf = document.getElementById("dictMehr");
    const uebrig = list.length - dictGezeigt;
    if (knopf) {
      knopf.style.display = uebrig > 0 ? "" : "none";
      if (uebrig > 0) knopf.textContent = `Weitere ${Math.min(DICT_SEITE, uebrig)} anzeigen (${uebrig.toLocaleString("de-DE")} übrig)`;
    }
  }
  /* Muss die ganze Ansicht doch neu gebaut werden, kommt die
     Schreibmarke danach dorthin zurück, wo sie war. */
  function dictFokusRetten(neuZeichnen) {
    const vorher = document.getElementById("dictSearch");
    const hatteFokus = vorher && document.activeElement === vorher;
    const stelle = vorher ? vorher.selectionStart : 0;
    neuZeichnen();
    if (!hatteFokus) return;
    const nachher = document.getElementById("dictSearch");
    if (!nachher) return;
    nachher.focus();
    try { nachher.setSelectionRange(stelle, stelle); } catch (e) { /* egal */ }
  }
  function renderDictionary(filter = "") {
    dictFilterText = filter;
    wortschatzNachziehen(() => renderDictionary(dictFilterText));
    const area = document.getElementById("dictionaryArea");
    const all = buildDictionaryEntries();
    const verifiedCount = all.filter((e) => e.verified).length;
    const categories = ["alle", ...new Set(all.map((e) => e.category))].sort((a, b) => a === "alle" ? -1 : b === "alle" ? 1 : a.localeCompare(b, "de"));
    const list = dictGefiltert(filter);
    const gemerkteGesamt = meinWortschatz().size;
    area.innerHTML = `
      <p class="empty-note" style="margin-bottom:10px;">Alle Vokabeln der Seite an einem Ort (${all.length} Einträge, davon ${verifiedCount} mit handgeprüfter Betonung) — mit Betonung und Bedeutung.<br>Betonung wie im Duden: <strong>fett</strong> = betonte Silbe, <span class="stress-vokal stress-lang">Strich</span> darunter = langer Vokal, <span class="stress-vokal stress-kurz">Punkt</span> = kurzer Vokal, kleiner offener Kreis = betont, Länge aus der Schreibung nicht eindeutig.</p>
      <div class="vocab-toolbar"><input type="text" class="vocab-search" id="dictSearch" placeholder="Wort oder Bedeutung suchen…" value="${filter}" /></div>
      <div class="trophy-case" style="margin:10px 0;">
        ${["alle", "A1", "A2", "B1", "B2", "C1", "C2", "erweitert"].map((lvl) => `<button type="button" class="trophy-chip dict-level-btn ${dictLevelFilter === lvl ? "selected" : ""}" data-level="${lvl}">${lvl === "alle" ? "Alle" : lvl === "erweitert" ? "Erweitert (ungeprüft)" : lvl}</button>`).join("")}
      </div>
      <label class="empty-note" style="display:block; margin-bottom:4px;">Themenbereich</label>
      <select id="dictCategorySelect" class="challenge-select" style="margin-bottom:12px;">
        ${categories.map((c) => `<option value="${c}" ${dictCategoryFilter === c ? "selected" : ""}>${c === "alle" ? "Alle Themen" : c}</option>`).join("")}
      </select>
      <div class="wortschatz-leiste">
        <button type="button" class="trophy-chip ${dictNurGemerkte ? "selected" : ""}" id="dictNurGemerkt">★ Nur mein Wortschatz (${gemerkteGesamt})</button>
        ${gemerkteGesamt ? '<button type="button" class="trophy-chip" id="dictZurAussprache">🎤 Damit die Aussprache üben</button>' : ""}
        ${/* GEWÜNSCHT: „Es soll auch im Wörterbuch diese Schaltfläche sein,
              seine Wörter nicht nur mit dem Aussprache-Trainer zu
              trainieren, sondern auch mit dem Betonungs-Trainer." */ ""}
        ${gemerkteGesamt ? '<button type="button" class="trophy-chip" id="dictZurBetonung">🎯 Damit die Betonung üben</button>' : ""}
      </div>
      <p class="empty-note" style="margin-bottom:10px;">Mit dem Stern ☆ neben einem Wort nimmst du es in deinen Wortschatz auf. Daraus kannst du dir eigene Übungen bauen — im Aussprache-Trainer und im Betonungs-Trainer.</p>
      <div class="vocab-grid" id="dictGrid">
        ${list.slice(0, dictGezeigt).map(dictKarte).join("")}
      </div>
      <button type="button" class="btn btn-ghost" id="dictMehr" style="display:${list.length > dictGezeigt ? "block" : "none"}; width:100%; margin-top:10px;">Weitere ${Math.min(DICT_SEITE, Math.max(0, list.length - dictGezeigt))} anzeigen (${Math.max(0, list.length - dictGezeigt).toLocaleString("de-DE")} übrig)</button>
      <p class="empty-note" id="dictLeer" style="display:${list.length === 0 ? "block" : "none"};">Keine Treffer.</p>
      <div id="dictVorschlagHost"></div>
    `;
    dictVorschlagZeichnen(list.length === 0);
    const suche = document.getElementById("dictSearch");
    suche.addEventListener("input", (e) => {
      dictFilterText = e.target.value;
      dictGezeigt = DICT_SEITE;
      clearTimeout(dictTippUhr);
      dictTippUhr = setTimeout(dictListeErneuern, 160);
    });
    area.querySelectorAll(".dict-level-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        dictLevelFilter = btn.dataset.level; dictGezeigt = DICT_SEITE;
        dictFokusRetten(() => renderDictionary(dictFilterText));
      });
    });
    document.getElementById("dictCategorySelect").addEventListener("change", (e) => {
      dictCategoryFilter = e.target.value;
      dictGezeigt = DICT_SEITE;
      dictFokusRetten(() => renderDictionary(dictFilterText));
    });
    /* Nachladen hängt nur die neuen Karten an, statt die ganze Liste neu
       zu bauen — so bleibt die Bildlaufstelle stehen. */
    document.getElementById("dictMehr")?.addEventListener("click", () => {
      const gitter = document.getElementById("dictGrid");
      const aktuell = dictGefiltert(dictFilterText);
      const naechste = aktuell.slice(dictGezeigt, dictGezeigt + DICT_SEITE);
      dictGezeigt += DICT_SEITE;
      gitter.insertAdjacentHTML("beforeend", naechste.map(dictKarte).join(""));
      const knopf = document.getElementById("dictMehr");
      const uebrig = aktuell.length - dictGezeigt;
      if (uebrig <= 0) knopf.style.display = "none";
      else knopf.textContent = `Weitere ${Math.min(DICT_SEITE, uebrig)} anzeigen (${uebrig.toLocaleString("de-DE")} übrig)`;
    });
    /* EIN Klick-Handler für alle Vorlese-Knöpfe statt einer pro Wort.
       Bei 8606 Einträgen waren das bisher 8606 Handler. */
    if (!area.dataset.vorlesenVerdrahtet) {
      area.dataset.vorlesenVerdrahtet = "1";
      area.addEventListener("click", async (ev) => {
        const knopf = ev.target.closest(".speak-btn");
        if (knopf) { Core.speak(knopf.dataset.word, imItalienischraum() ? "it" : "de"); return; }
        const merken = ev.target.closest("[data-merken]");
        if (!merken) return;
        // Der Stern muss SOFORT reagieren; gespeichert wird nebenher.
        const jetztDrin = await wortschatzUmschalten(merken.dataset.merken);
        merken.textContent = jetztDrin ? "★" : "☆";
        merken.classList.toggle("gemerkt", jetztDrin);
        merken.setAttribute("aria-pressed", String(jetztDrin));
        const zaehler = document.getElementById("dictNurGemerkt");
        if (zaehler) zaehler.textContent = `★ Nur mein Wortschatz (${meinWortschatz().size})`;
      });
    }
    document.getElementById("dictNurGemerkt")?.addEventListener("click", () => {
      dictNurGemerkte = !dictNurGemerkte;
      dictGezeigt = DICT_SEITE;
      renderDictionary(filter);
    });
    document.getElementById("dictZurAussprache")?.addEventListener("click", () => {
      ausspracheQuelle = "wortschatz";
      document.querySelector('#learnSubnav [data-sub="sub-aussprache"]')?.click();
    });
    document.getElementById("dictZurBetonung")?.addEventListener("click", () => {
      // Dieselbe Quelle wie im Aussprache-Trainer: der eigene Wortschatz.
      wortQuelleWahl.stresstrainer = "wortschatz";
      stTrainerSession = null;
      stTrainerWord = null;
      const pille = document.querySelector('#learnSubnav [data-sub="sub-stresstrainer"]');
      if (pille) { pille.style.display = ""; pille.click(); }
    });
  }
  /* ============================================================
     AUSSPRACHE-TRAINER
     ------------------------------------------------------------
     Man wählt, WOMIT geübt wird — dem eigenen gemerkten Wortschatz,
     einem Themenbereich, einem Niveau oder allem —, hört das Wort,
     spricht es nach und bekommt eine Zahl zurück.

     Zur Ehrlichkeit dieser Zahl: gemessen wird, ob die Spracherkennung
     des Geräts das Wort erkennt. Das ist Verständlichkeit, nicht
     Lautgenauigkeit — und genau so steht es auch in der Oberfläche.
     Eine Anzeige, die mehr verspricht, als sie kann, wäre schlimmer als
     gar keine.

     Der Trainer ist absichtlich ein eigener Bereich UND ans Wörterbuch
     angebunden: aus dem Wörterbuch heraus kann man mit einem Knopf mit
     genau den gemerkten Wörtern weiterüben.
     ============================================================ */
  let ausspracheQuelle = "wortschatz";   // wortschatz | kategorie | niveau | alle
  let ausspracheKategorie = "alle";
  let ausspracheNiveau = "alle";
  let ausspracheSitzung = null;
  const AUSSPRACHE_RUNDEN = 10;

  function ausspracheWortliste() {
    const alle = buildDictionaryEntries().filter((e) => e.syl && e.word);
    if (ausspracheQuelle === "wortschatz") return alle.filter((e) => imWortschatz(e.word));
    if (ausspracheQuelle === "kategorie") return ausspracheKategorie === "alle" ? alle : alle.filter((e) => e.category === ausspracheKategorie);
    if (ausspracheQuelle === "niveau") return ausspracheNiveau === "alle" ? alle : alle.filter((e) => e.level === ausspracheNiveau);
    return alle;
  }
  function neueAusspracheSitzung() {
    const liste = ausspracheWortliste();
    ausspracheSitzung = {
      woerter: Core.shuffle(liste).slice(0, AUSSPRACHE_RUNDEN),
      index: 0, ergebnisse: [], laeuft: false, letztes: null,
    };
  }
  function ausspracheBalken(prozent) {
    const farbe = prozent >= 80 ? "#4FA88E" : prozent >= 55 ? "#E8A33D" : "#E85F6F";
    return `<div class="aussprache-balken"><div class="aussprache-balken-fuellung" style="width:${Math.max(3, prozent)}%; background:${farbe};"></div></div>`;
  }
  function ausspracheUrteil(prozent) {
    if (prozent >= 90) return "Sehr gut verstanden — so kann dich jeder verstehen.";
    if (prozent >= 75) return "Gut angekommen. Kleine Abweichungen, aber deutlich.";
    if (prozent >= 55) return "Erkannt, aber undeutlich. Hör dir das Wort noch einmal an und sprich langsamer.";
    if (prozent > 0) return "Kaum erkannt. Achte besonders auf die betonte Silbe.";
    return "Nichts verstanden — war das Mikrofon an, und war es ruhig genug?";
  }

  function renderAussprache() {
    const area = document.getElementById("ausspracheArea");
    if (!area) return;
    const kannHoeren = Core.spracherkennungDa();
    const alle = buildDictionaryEntries();
    const kategorien = ["alle", ...new Set(alle.map((e) => e.category).filter(Boolean))].sort((a, b) => a === "alle" ? -1 : b === "alle" ? 1 : a.localeCompare(b, "de"));
    const gemerkt = meinWortschatz().size;

    if (!ausspracheSitzung) {
      const liste = ausspracheWortliste();
      area.innerHTML = `
        <div class="question-card">
          <p class="eyebrow">🎤 AUSSPRACHE-TRAINER</p>
          <p class="empty-note" style="margin-bottom:12px;">Du hörst ein Wort, sprichst es nach, und bekommst zurück, wie gut es angekommen ist.</p>
          ${!kannHoeren ? `<div class="beta-hinweis" style="border-color:rgba(232,95,111,0.6); background:rgba(232,95,111,0.08);">
            <strong>Dieser Browser kann nicht zuhören.</strong> Die Spracherkennung ist hier nicht eingebaut.
            Am besten klappt es in Chrome auf Android oder am Rechner; auf dem iPhone braucht es Safari ab iOS 14.5.
            Vorlesen und Betonung kannst du trotzdem üben.
          </div>` : ""}
          <p class="eyebrow" style="margin-top:14px;">WOMIT MÖCHTEST DU ÜBEN?</p>
          <div class="trophy-case" style="margin-bottom:10px;">
            <button type="button" class="trophy-chip ${ausspracheQuelle === "wortschatz" ? "selected" : ""}" data-ausspr-quelle="wortschatz">★ Mein Wortschatz (${gemerkt})</button>
            <button type="button" class="trophy-chip ${ausspracheQuelle === "kategorie" ? "selected" : ""}" data-ausspr-quelle="kategorie">🗂️ Ein Themenbereich</button>
            <button type="button" class="trophy-chip ${ausspracheQuelle === "niveau" ? "selected" : ""}" data-ausspr-quelle="niveau">📶 Ein Niveau</button>
            <button type="button" class="trophy-chip ${ausspracheQuelle === "alle" ? "selected" : ""}" data-ausspr-quelle="alle">🎲 Zufällig aus allem</button>
          </div>
          ${ausspracheQuelle === "kategorie" ? `
            <label class="empty-note" style="display:block; margin-bottom:4px;">Themenbereich</label>
            <select id="ausspracheKatSelect" class="challenge-select" style="margin-bottom:12px;">
              ${kategorien.map((c) => `<option value="${c}" ${ausspracheKategorie === c ? "selected" : ""}>${c === "alle" ? "Alle Themen" : c}</option>`).join("")}
            </select>` : ""}
          ${ausspracheQuelle === "niveau" ? `
            <div class="trophy-case" style="margin-bottom:12px;">
              ${["alle", "A1", "A2", "B1", "B2", "C1", "C2"].map((l) => `<button type="button" class="trophy-chip ${ausspracheNiveau === l ? "selected" : ""}" data-ausspr-niveau="${l}">${l === "alle" ? "Alle" : l}</button>`).join("")}
            </div>` : ""}
          ${ausspracheQuelle === "wortschatz" && !gemerkt ? `
            <p class="empty-note">Du hast dir noch keine Wörter gemerkt. Geh ins Wörterbuch und tippe bei den Wörtern, die du gerade lernst, auf den Stern ☆ — dann kannst du hier genau mit diesen üben.</p>
            <button type="button" class="btn btn-ghost" id="ausspracheZumWoerterbuch" style="margin-top:8px;">📖 Zum Wörterbuch</button>`
          : `<p class="empty-note" style="margin-bottom:12px;">${liste.length.toLocaleString("de-DE")} Wörter stehen bereit — eine Runde geht über ${Math.min(AUSSPRACHE_RUNDEN, liste.length)}.</p>
             <button type="button" class="btn btn-coffee" id="ausspracheStart" ${liste.length ? "" : "disabled"}>🎤 Runde starten</button>`}
          <p class="empty-note" style="margin-top:16px; font-size:0.72rem;">
            Was hier gemessen wird: ob die Spracherkennung deines Geräts das Wort erkennt — also deine <strong>Verständlichkeit</strong>.
            Ob ein einzelner Laut ganz genau sitzt, kann diese Prüfung nicht sagen; das können nur eigene Aussprache-Dienste.
            Deine Aufnahme wird nicht gespeichert und verlässt dein Gerät nur zur Erkennung durch den Browser.
          </p>
        </div>`;
      area.querySelectorAll("[data-ausspr-quelle]").forEach((b) => b.addEventListener("click", () => { ausspracheQuelle = b.dataset.aussprQuelle; renderAussprache(); }));
      area.querySelectorAll("[data-ausspr-niveau]").forEach((b) => b.addEventListener("click", () => { ausspracheNiveau = b.dataset.aussprNiveau; renderAussprache(); }));
      document.getElementById("ausspracheKatSelect")?.addEventListener("change", (e) => { ausspracheKategorie = e.target.value; renderAussprache(); });
      document.getElementById("ausspracheZumWoerterbuch")?.addEventListener("click", () => {
        document.querySelector('#learnSubnav [data-sub="sub-dictionary"]')?.click();
      });
      document.getElementById("ausspracheStart")?.addEventListener("click", () => { neueAusspracheSitzung(); renderAussprache(); });
      return;
    }

    const s = ausspracheSitzung;
    if (s.index >= s.woerter.length) { renderAusspracheErgebnis(); return; }
    const w = s.woerter[s.index];
    area.innerHTML = `
      <div class="question-card">
        <p class="eyebrow">🎤 AUSSPRACHE · WORT ${s.index + 1} / ${s.woerter.length}</p>
        <div class="aussprache-wort">${w.word}</div>
        <div class="vocab-syl" style="text-align:center; font-size:1.1rem;">${betonungAnzeigen(w.syl)}</div>
        ${w.meaning ? `<p class="empty-note" style="text-align:center;">${w.meaning}</p>` : ""}
        <div class="quiz-actions" style="justify-content:center; margin:14px 0 6px;">
          <button type="button" class="btn btn-ghost" id="ausspracheHoeren">🔊 Vorsprechen lassen</button>
          <button type="button" class="btn btn-coffee" id="ausspracheAufnehmen" ${kannHoeren ? "" : "disabled"}>${s.laeuft ? "🎙️ Ich höre zu …" : "🎙️ Jetzt sprechen"}</button>
        </div>
        <div id="ausspracheRueckmeldung">
          ${s.letztes ? `
            ${ausspracheBalken(s.letztes.prozent)}
            <p class="aussprache-prozent">${s.letztes.prozent} % verständlich</p>
            <p class="empty-note" style="text-align:center;">${ausspracheUrteil(s.letztes.prozent)}</p>
            ${s.letztes.beste && s.letztes.prozent < 90 ? `<p class="empty-note" style="text-align:center;">Verstanden wurde: „${s.letztes.beste}“</p>` : ""}`
          : '<p class="empty-note" style="text-align:center;">Tippe auf „Jetzt sprechen“ und sag das Wort deutlich.</p>'}
        </div>
        <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
          <button type="button" class="btn btn-ghost" id="ausspracheWeiter">${s.letztes ? "Weiter ▸" : "Überspringen ▸"}</button>
          <button type="button" class="btn btn-ghost" id="ausspracheAbbrechen">Runde beenden</button>
        </div>
        ${miniBugReportBtnHtml(`Aussprache-Trainer, Wort „${w.word}“`)}
      </div>`;
    document.getElementById("ausspracheHoeren").addEventListener("click", () => Core.speak(w.word, imItalienischraum() ? "it" : "de"));
    document.getElementById("ausspracheAufnehmen").addEventListener("click", async () => {
      if (s.laeuft) return;
      s.laeuft = true;
      const knopf = document.getElementById("ausspracheAufnehmen");
      knopf.textContent = "🎙️ Ich höre zu …";
      knopf.disabled = true;
      /* Ohne Sprachangabe hört der Browser auf Deutsch zu — ein
         italienisches Wort käme dann immer als „nicht verstanden"
         zurück, ganz gleich wie gut es gesprochen war. */
      const gehoert = await Core.hoereZu({ hoechstdauer: 8000, sprache: imItalienischraum() ? "it-IT" : "de-DE" });
      s.laeuft = false;
      if (gehoert.fehler) {
        const texte = {
          "not-allowed": "Das Mikrofon ist nicht freigegeben. In den Browser-Einstellungen für diese Seite den Zugriff erlauben.",
          "nicht-verfuegbar": "Dieser Browser hat keine Spracherkennung.",
          "nichts-verstanden": "Ich habe nichts gehört. Näher ans Mikrofon und noch einmal.",
          "zeit-abgelaufen": "Die Aufnahme hat zu lange gedauert — noch einmal, kürzer.",
          "no-speech": "Ich habe nichts gehört. Näher ans Mikrofon und noch einmal.",
          "network": "Die Erkennung braucht gerade eine Internetverbindung.",
        };
        document.getElementById("ausspracheRueckmeldung").innerHTML =
          `<p class="empty-note" style="text-align:center;">${texte[gehoert.fehler] || "Das hat gerade nicht geklappt — bitte noch einmal."}</p>`;
        knopf.textContent = "🎙️ Noch einmal";
        knopf.disabled = false;
        return;
      }
      const bewertung = Core.bewerteAussprache(w.word, gehoert);
      s.letztes = bewertung;
      if (bewertung.prozent >= 75) Core.sound.correct(); else Core.sound.okay();
      renderAussprache();
      /* GEWÜNSCHT: „dass das automatisch alleine weitergeht und man nicht
         erst auf den Knopf drücken muss." Nach einem bewerteten Versuch
         geht es von selbst zum nächsten Wort — der Knopf bleibt für alle,
         die es schneller wollen. */
      autoWeiter(bewertung.prozent >= 75, () => {
        const knopf = document.getElementById("ausspracheWeiter");
        if (knopf) knopf.click();
      });
    });
    document.getElementById("ausspracheWeiter").addEventListener("click", () => {
      if (s.letztes) {
        s.ergebnisse.push({ wort: w.word, prozent: s.letztes.prozent, gehoert: s.letztes.beste });
        spielNotiz(s.letztes.prozent >= 75, `${w.word} — ${s.letztes.prozent} % verständlich${s.letztes.beste && s.letztes.prozent < 90 ? ` (verstanden: „${s.letztes.beste}“)` : ""}`);
      } else {
        s.ergebnisse.push({ wort: w.word, prozent: null, gehoert: "" });
        spielNotiz(null, `${w.word} — übersprungen`);
      }
      s.letztes = null;
      s.index += 1;
      renderAussprache();
    });
    document.getElementById("ausspracheAbbrechen").addEventListener("click", () => { s.index = s.woerter.length; renderAussprache(); });
  }

  function renderAusspracheErgebnis() {
    const area = document.getElementById("ausspracheArea");
    const s = ausspracheSitzung;
    const gewertet = s.ergebnisse.filter((e) => typeof e.prozent === "number");
    const schnitt = gewertet.length ? Math.round(gewertet.reduce((a, e) => a + e.prozent, 0) / gewertet.length) : 0;
    area.innerHTML = ergebnisSchirmHtml({
      punkte: gewertet.filter((e) => e.prozent >= 75).length, prozent: schnitt, tier: "Deutlichsprecher:in",
      charakter: "Aussprache-Trainer", zeilen: s.ergebnisse.map((e) => ({ name: e.wort, anteil: typeof e.prozent === "number" ? e.prozent : 0, wert: typeof e.prozent === "number" ? e.prozent + " %" : "—" })),
      knoepfe: `<button type="button" class="btn btn-coffee" id="ausspracheNochmal">🔄 Noch eine Runde</button><button type="button" class="btn btn-ghost" id="ausspracheZurueck">Andere Wörter wählen</button>`,
    });
    if (gewertet.length) {
      saveResultAndCheck({
        categories: ["aussprache"], titelText: "Aussprache-Trainer",
        points: gewertet.filter((e) => e.prozent >= 75).length, bonus: schnitt >= 90 ? 3 : 0,
        percent: schnitt, character: "Deutlichsprecher:in", badges: [], playedAt: new Date().toISOString(),
      });
    }
    document.getElementById("ausspracheNochmal").addEventListener("click", () => { neueAusspracheSitzung(); renderAussprache(); });
    document.getElementById("ausspracheZurueck").addEventListener("click", () => { ausspracheSitzung = null; renderAussprache(); });
  }
  document.querySelector('#learnSubnav [data-sub="sub-aussprache"]')?.addEventListener("click", () => renderAussprache());

  /* ============================================================
     LOGIK-TRAINER
     ------------------------------------------------------------
     Der Anlass war eine genaue Beobachtung: Leute antworten im
     Gespräch mit „ja, ja“ und „genau“ und haben nichts verstanden.
     Sie lesen Wörter als Ganzes und raten aus dem Zusammenhang.

     Hier wird das Gegenteil geübt — ein Wort auseinandernehmen:
       · Welches bekannte Wort steckt in „Verkäuferin“?
       · Welches Glied bestimmt bei „Krankenhaus“ Artikel und
         Grundbedeutung?
       · Was sagt die Vorsilbe von „abholen“ über die Richtung?

     Wer das einmal sieht, muss viel weniger auswendig lernen: aus
     einem Wortstamm und sechs Vorsilben werden Dutzende Wörter,
     deren Bedeutung man sich herleiten kann.
     ============================================================ */
  const LOGIK_RUNDEN = 10;
  let logikSitzung = null;
  let logikArt = "gemischt";   // gemischt | stamm | kompositum | richtung
  let logikGeladen = null;
  function logikLaden() {
    if (window.DMA_DATEN && window.DMA_DATEN.LOGIK_STAMM) return Promise.resolve(true);
    if (logikGeladen) return logikGeladen;
    logikGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-logik.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { logikGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return logikGeladen;
  }
  const LOGIK_ARTEN = {
    gemischt: "🎲 Gemischt", stamm: "🌱 Welches Wort steckt drin?",
    kompositum: "🧱 Zusammengesetzte Wörter", richtung: "🧭 Vorsilben & Richtung",
  };
  /* Aus den Rohdaten werden die Aufgaben hier gebaut — bei den
     Zusammensetzungen aus dem Muster, bei den anderen beiden direkt
     aus den kuratierten Zeilen. */
  function logikAufgaben() {
    const D = window.DMA_DATEN || {};
    const raus = [];
    (D.LOGIK_STAMM || []).forEach(([wort, stamm, falsch, erkl, level]) => {
      raus.push({ art: "stamm", frage: `Welches Wort steckt in „${wort}“?`, richtig: stamm, falsch, erkl, level });
    });
    (D.LOGIK_KOMPOSITA || []).forEach(([wort, bestimmung, grund, artikel, sagt, level]) => {
      const rein = wort.replace(/^(der|die|das)\s+/, "");
      raus.push({ art: "kompositum",
        frage: `Welches Glied bestimmt bei „${rein}“ den Artikel und die Grundbedeutung?`,
        richtig: grund,
        falsch: [bestimmung, rein, artikel + " " + bestimmung],
        erkl: `Bei zusammengesetzten Wörtern entscheidet IMMER das letzte Glied: „${rein}“ ist ${artikel === "der" ? "ein" : artikel === "die" ? "eine" : "ein"} ${grund}. Das erste Glied „${bestimmung}“ sagt nur, ${sagt}.`,
        level });
      raus.push({ art: "kompositum",
        frage: `Was sagt das erste Glied „${bestimmung}“ bei „${rein}“?`,
        richtig: sagt,
        falsch: ["Es bestimmt den Artikel des ganzen Wortes.",
          "Es hat keine eigene Bedeutung.",
          "Es macht das Wort zur Mehrzahl."],
        erkl: `Das erste Glied beschreibt genauer — es sagt ${sagt}. Den Artikel bestimmt dagegen das letzte Glied „${grund}“: ${artikel} ${rein}.`,
        level });
    });
    (D.LOGIK_RICHTUNG || []).forEach(([verb, richtig, falsch, erkl, level]) => {
      raus.push({ art: "richtung", frage: `Was bedeutet „${verb}“ genau — welche Richtung steckt darin?`, richtig, falsch, erkl, level });
    });
    return raus;
  }
  function neueLogikSitzung() {
    let pool = logikAufgaben();
    if (logikArt !== "gemischt") pool = pool.filter((a) => a.art === logikArt);
    /* Nach Niveau vorsortieren, aber nicht hart abschneiden: sonst
       bliebe für A1 fast nichts übrig. Passende zuerst, der Rest
       füllt auf. */
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const meins = stufen.indexOf(logikNiveau);
    const passend = pool.filter((a) => stufen.indexOf(a.level) <= meins);
    const quelle = passend.length >= LOGIK_RUNDEN ? passend : pool;
    logikSitzung = {
      aufgaben: Core.shuffle(quelle).slice(0, LOGIK_RUNDEN),
      index: 0, richtig: 0, beantwortet: null,
    };
  }
  let logikNiveau = null;
  async function renderLogik() {
    autoWeiterAbbrechen();
    const area = document.getElementById("logikArea");
    if (!area) return;
    if (!(window.DMA_DATEN && window.DMA_DATEN.LOGIK_STAMM)) {
      area.innerHTML = '<p class="empty-note">Der Logik-Trainer wird geladen …</p>';
      const ok = await logikLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Logik-Trainer konnte nicht geladen werden.</p>'; return; }
    }
    logikNiveau = applyDefaultCefrLevel(logikNiveau, (v) => { logikNiveau = v; }, "logik");
    if (!logikSitzung) {
      const anzahl = logikAufgaben().filter((a) => logikArt === "gemischt" || a.art === logikArt).length;
      area.innerHTML = `
        <div class="question-card">
          <p class="eyebrow">🧠 LOGIK-TRAINER</p>
          <p class="empty-note" style="margin-bottom:12px;">
            Nicht auswendig lernen, sondern sehen, wie ein Wort gebaut ist. Wer erkennt, dass in
            „Verkäuferin“ das Verb „verkaufen“ steckt, dass beim „Krankenhaus“ das <strong>Haus</strong>
            das Grundwort ist und dass „ab-“ in „abholen“ eine Richtung angibt, muss die Hälfte
            nicht mehr auswendig können — er kann sie sich herleiten.
          </p>
          <p class="eyebrow">WAS MÖCHTEST DU ÜBEN?</p>
          <div class="trophy-case" style="margin-bottom:12px;">
            ${Object.entries(LOGIK_ARTEN).map(([k, name]) => `<button type="button" class="trophy-chip logik-art-btn ${logikArt === k ? "selected" : ""}" data-logik-art="${k}">${name}</button>`).join("")}
          </div>
          <p class="eyebrow">SPRACHNIVEAU</p>
          <div class="trophy-case" style="margin-bottom:12px;">
            ${["A1", "A2", "B1", "B2", "C1", "C2"].map((l) => `<button type="button" class="trophy-chip logik-level-btn ${logikNiveau === l ? "selected" : ""}" data-logik-level="${l}">${l}</button>`).join("")}
          </div>
          <p class="empty-note" style="margin-bottom:12px;">${anzahl} Aufgaben stehen bereit — eine Runde geht über ${LOGIK_RUNDEN}.</p>
          <button type="button" class="btn btn-coffee" id="logikStart">▶ Runde starten</button>
        </div>`;
      area.querySelectorAll(".logik-art-btn").forEach((b) => b.addEventListener("click", () => { logikArt = b.dataset.logikArt; renderLogik(); }));
      area.querySelectorAll(".logik-level-btn").forEach((b) => b.addEventListener("click", () => { logikNiveau = b.dataset.logikLevel; autoCefrLevel.logik = null; renderLogik(); }));
      document.getElementById("logikStart").addEventListener("click", () => { neueLogikSitzung(); renderLogik(); });
      return;
    }
    const s = logikSitzung;
    if (s.index >= s.aufgaben.length) { renderLogikErgebnis(); return; }
    const a = s.aufgaben[s.index];
    const optionen = s.beantwortet ? s.beantwortet.optionen : Core.shuffle([a.richtig, ...a.falsch]);
    if (!s.beantwortet) s.optionen = optionen;
    area.innerHTML = `
      <div class="question-card">
        <p class="eyebrow">🧠 LOGIK-TRAINER · RUNDE ${s.index + 1} / ${s.aufgaben.length} · ${LOGIK_ARTEN[a.art] || ""}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${(s.optionen || optionen).map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn logik-opt${zustand}" data-logik-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="logikWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Logik-Trainer: " + a.frage)}
      </div>`;
    area.querySelectorAll(".logik-opt").forEach((b) => b.addEventListener("click", () => {
      const opt = (s.optionen || optionen)[Number(b.dataset.logikOpt)];
      const stimmt = opt === a.richtig;
      if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
      spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
      s.beantwortet = { gewaehlt: opt, optionen: s.optionen || optionen };
      renderLogik();
    }));
    const logikNaechste = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderLogik(); };
    document.getElementById("logikWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); logikNaechste(); });
    if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, logikNaechste);
  }
  function renderLogikErgebnis() {
    const area = document.getElementById("logikArea");
    const s = logikSitzung;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Wortdetektiv:in",
      charakter: "Logik-Trainer", zeilen: [{ name: "🧠 Richtig erkannt", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="logikNochmal">🔄 Noch eine Runde</button><button type="button" class="btn btn-ghost" id="logikZurueck">Andere Art wählen</button>`,
    });
    saveResultAndCheck({
      categories: ["logik"], titelText: "Logik-Trainer",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Wortdetektiv:in", badges: [], playedAt: new Date().toISOString(),
    });
    document.getElementById("logikNochmal").addEventListener("click", () => { neueLogikSitzung(); renderLogik(); });
    document.getElementById("logikZurueck").addEventListener("click", () => { logikSitzung = null; renderLogik(); });
  }
  document.querySelector('#learnSubnav [data-sub="sub-logik"]')?.addEventListener("click", () => renderLogik());

  /* ============================================================
     AUSSPRACHE-KURS
     ------------------------------------------------------------
     GEWÜNSCHT: „Das Alphabet wurde auch noch nicht behandelt …
     mit den Umlauten und den Regeln, das mit dem Dehnungs-h und
     dem E nach dem I … wenn ein Konsonant nach einem Vokal steht,
     dass der Vokal lang gesprochen wird … die Ausnahmen davon …
     dass sie nicht SETR sagen, sondern Straße … Tricks, wie man
     ein sauberes Ü nachfüllen kann, vom I, indem man einen
     Kussmund macht … das mit dem NG richtig erklärt, mit einer
     grafischen Darstellung."

     Sechs Teile, jeder für sich benutzbar:
       Alphabet      — jeder Buchstabe einzeln, antippen = hören
       Buchstabenpaare — ch, sch, ie, ng … zwei Zeichen, ein Laut
       Regeln        — Vokallänge, Dehnungs-h, ie, ß/ss, Betonung
       Bündel        — Konsonanten am Stück, ohne Zwischenvokal
       Tricks        — wie man einen Laut körperlich herstellt
       Test          — zählt auf das Punktekonto

     Alles gibt es auf Deutsch UND auf Italienisch, jeweils mit
     den Regeln, die für diese Sprache wirklich gelten.
     ============================================================ */
  let ausspracheKursGeladen = null;
  function ausspracheKursLaden() {
    if (window.DMA_AUSSPRACHE) return Promise.resolve(true);
    if (ausspracheKursGeladen) return ausspracheKursGeladen;
    ausspracheKursGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-aussprache.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { ausspracheKursGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return ausspracheKursGeladen;
  }

  const AK_TEILE = {
    alphabet: "🔤 Alphabet",
    verbindungen: "🔗 Zwei Zeichen, ein Laut",
    regeln: "📏 Regeln",
    buendel: "🧱 Konsonanten am Stück",
    tricks: "🎯 Tricks",
    test: "✅ Test",
  };
  let akTeil = "alphabet";
  let akSprache = null;        // null = die Sprache des Raums
  let akTest = null;

  function akAktuelleSprache() {
    if (akSprache) return akSprache;
    return imItalienischraum() ? "it" : "de";
  }
  function akDaten(feld) {
    const A = window.DMA_AUSSPRACHE || {};
    return (A[feld] && A[feld][akAktuelleSprache()]) || [];
  }
  /* Ein Wort anzeigen: mit Betonungsmarke, wenn eine Silbenangabe
     dabei ist, sonst schlicht. Die Marke folgt derselben Stelle wie
     überall sonst auf der Seite — im Italienisch-Raum also ohne
     Längsstrich, den es dort nicht gibt. */
  /* Den ersten echten Buchstaben (also nicht innerhalb eines Tags)
     wieder kleinschreiben. Die Betonungsanzeige schreibt die erste
     Silbe immer groß — im Wörterbuch stimmt das, weil dort Nomen
     stehen. Hier stehen auch Verben und Adjektive: „singen“, „lang“,
     „früh“ dürfen kein großes S, L oder F bekommen. */
  function akErsteKlein(html) {
    let imTag = false;
    for (let i = 0; i < html.length; i++) {
      const c = html[i];
      if (c === "<") { imTag = true; continue; }
      if (c === ">") { imTag = false; continue; }
      if (imTag) continue;
      if (/[A-Za-zÄÖÜäöüß]/.test(c)) {
        return html.slice(0, i) + c.toLowerCase() + html.slice(i + 1);
      }
    }
    return html;
  }
  function akWort(wort, syl) {
    const text = String(wort);
    if (!syl) return text;
    let gezeigt = akAktuelleSprache() === "it" ? Core.formatStressIt(syl) : Core.formatStress(syl);
    /* Der Artikel steht im Wort, nicht in der Silbenangabe — er kommt
       davor zurück. Das Leerzeichen ist Pflicht: sonst hätte „lang“
       als Artikel „la“ gegolten und wäre zu „la Lang“ geworden. */
    const artikel = text.match(/^(?:(?:der|die|das|il|lo|la|i|gli|le)\s|l['’])/i);
    const rest = artikel ? text.slice(artikel[0].length) : text;
    if (rest && rest[0] === rest[0].toLowerCase() && rest[0] !== rest[0].toUpperCase()) {
      gezeigt = akErsteKlein(gezeigt);
    }
    return (artikel ? artikel[0] : "") + gezeigt;
  }
  /* Ein Lautsprecher-Knopf. Die Sprache steht am Knopf selbst — sonst
     läse die deutsche Stimme die italienischen Sätze vor. */
  function sprichKnopfHtml(text, sprache, titel) {
    return `<button type="button" class="btn btn-ghost ak-hoer"
      data-ak-sprich="${String(text).replace(/"/g, "&quot;")}" data-ak-lang="${sprache || "de"}"
      aria-label="${titel || "anhören"}" title="${titel || "anhören"}">🔊</button>`;
  }
  function akHoerKnopf(text, titel) {
    return sprichKnopfHtml(text, akAktuelleSprache(), titel);
  }

  function akKopfHtml() {
    const spr = akAktuelleSprache();
    return `
      <div class="question-card ak-kopf">
        <p class="eyebrow">🗣️ AUSSPRACHE-KURS</p>
        <p class="empty-note" style="margin-bottom:10px;">
          Lesen kann man erst, wenn man weiß, wie die Buchstaben klingen. Hier steht das komplette
          Alphabet, dazu die Regeln, die einem sagen, ob ein Vokal lang oder kurz ist — und die
          Tricks für die Laute, die es in der eigenen Muttersprache nicht gibt.
          Jedes Wort lässt sich antippen und anhören.
        </p>
        <div class="trophy-case" style="margin-bottom:10px;">
          <button type="button" class="trophy-chip ak-spr-btn ${spr === "de" ? "selected" : ""}" data-ak-spr="de">🇩🇪 Deutsch</button>
          <button type="button" class="trophy-chip ak-spr-btn ${spr === "it" ? "selected" : ""}" data-ak-spr="it">🇮🇹 Italienisch</button>
        </div>
        <div class="trophy-case">
          ${Object.entries(AK_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip ak-teil-btn ${akTeil === k ? "selected" : ""}" data-ak-teil="${k}">${name}</button>`).join("")}
        </div>
      </div>`;
  }

  function akAlphabetHtml() {
    const spr = akAktuelleSprache();
    const zeilen = akDaten("ALPHABET");
    const einleitung = spr === "it"
      ? "Das italienische Alphabet hat nur 21 Buchstaben. j, k, w, x und y stehen nur in Fremdwörtern. Tippe einen Buchstaben an, dann hörst du seinen Namen und das Beispielwort."
      : "26 Buchstaben, dazu die drei Umlaute und das ß. Tippe einen Buchstaben an, dann hörst du seinen Namen und das Beispielwort.";
    return `
      <div class="question-card">
        <p class="eyebrow">${spr === "it" ? "L’ALFABETO" : "DAS ALPHABET"}</p>
        <p class="empty-note" style="margin-bottom:12px;">${einleitung}</p>
        <div class="ak-gitter">
          ${zeilen.map((z, i) => `
            <div class="ak-buchstabe" data-ak-buchstabe="${i}">
              <div class="ak-b-kopf">
                <span class="ak-b-zeichen">${z.b}</span>
                <span class="ak-b-name">${z.name}</span>
              </div>
              <p class="ak-b-ipa">[${z.ipa}]</p>
              <p class="ak-b-laut">${z.laut}</p>
              <p class="ak-b-bsp">${akWort(z.bsp, z.syl)} ${akHoerKnopf(z.bsp, "„" + z.bsp + "“ anhören")}</p>
              ${z.hinweis ? `<p class="ak-b-hinweis">${z.hinweis}</p>` : ""}
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akVerbindungenHtml() {
    const zeilen = akDaten("VERBINDUNGEN");
    return `
      <div class="question-card">
        <p class="eyebrow">ZWEI ZEICHEN, EIN LAUT</p>
        <p class="empty-note" style="margin-bottom:12px;">
          Manche Buchstaben stehen nie allein. Erst zusammen ergeben sie einen einzigen Laut —
          und der hat oft nichts mit den einzelnen Buchstaben zu tun.
        </p>
        <div class="ak-liste">
          ${zeilen.map((z) => `
            <div class="ak-verb">
              <div class="ak-verb-kopf">
                <span class="ak-verb-schrift">${z.schrift}</span>
                <span class="ak-verb-pfeil">→</span>
                <span class="ak-verb-laut">${z.gesprochen}</span>
              </div>
              <p class="ak-verb-wann">${z.wann}</p>
              <p class="ak-verb-bsp">${z.bsp.map((w) => `<span class="ak-chip">${w} ${akHoerKnopf(w)}</span>`).join("")}</p>
              ${z.hinweis ? `<p class="ak-b-hinweis">${z.hinweis}</p>` : ""}
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akRegelnHtml() {
    const zeilen = akDaten("REGELN");
    return zeilen.map((r) => `
      <div class="question-card ak-regel">
        <p class="eyebrow">${r.titel}</p>
        ${r.svg || ""}
        <p class="empty-note" style="margin:10px 0 12px;">${r.text}</p>
        <div class="ak-bsp-gitter">
          ${(r.beispiele || []).map((b) => `
            <div class="ak-bsp">
              <span class="ak-bsp-wort">${akWort(b.wort, b.syl)}</span>
              ${akHoerKnopf(b.wort)}
              ${b.hinweis ? `<span class="ak-bsp-hinweis">${b.hinweis}</span>` : ""}
            </div>`).join("")}
        </div>
        ${r.ausnahmen && (r.ausnahmen.text || (r.ausnahmen.woerter || []).length) ? `
          <div class="ak-ausnahme">
            <p class="ak-ausnahme-titel">⚠️ Ausnahmen</p>
            ${r.ausnahmen.text ? `<p>${r.ausnahmen.text}</p>` : ""}
            ${(r.ausnahmen.woerter || []).length ? `<p class="ak-ausnahme-woerter">${r.ausnahmen.woerter.map((w) => `<span class="ak-chip">${w}</span>`).join("")}</p>` : ""}
          </div>` : ""}
      </div>`).join("");
  }

  function akBuendelHtml() {
    const zeilen = akDaten("BUENDEL");
    const brecher = akDaten("ZUNGENBRECHER");
    const spr = akAktuelleSprache();
    const einleitung = spr === "it"
      ? "Auch im Italienischen stehen Konsonanten am Stück — und anders als im Deutschen bleibt das s dabei scharf: „la strada“, nicht „schtrada“."
      : "Im Arabischen, Türkischen, Persischen und Spanischen schiebt die Zunge von selbst einen kleinen Vokal zwischen zwei Konsonanten. Im Deutschen gibt es diesen Vokal nicht. Trick: von hinten aufbauen — „raße“, „traße“, „schtraße“.";
    return `
      <div class="question-card">
        <p class="eyebrow">KONSONANTEN AM STÜCK</p>
        <p class="empty-note" style="margin-bottom:12px;">${einleitung}</p>
        ${spr === "de" ? ((window.DMA_AUSSPRACHE.GRAFIK || {}).buendel || "") : ""}
        <div class="ak-liste">
          ${zeilen.map((z) => `
            <div class="ak-buendel">
              <div class="ak-verb-kopf">
                <span class="ak-verb-schrift">${z.schrift}</span>
                <span class="ak-verb-pfeil">→</span>
                <span class="ak-verb-laut">${z.gesprochen}</span>
              </div>
              <p class="ak-buendel-richtig">✅ ${akWort(z.bsp, z.syl)} ${akHoerKnopf(z.bsp)}</p>
              <p class="ak-buendel-falsch">❌ ${z.falsch}</p>
              <p class="ak-verb-bsp">${(z.weitere || []).map((w) => `<span class="ak-chip">${w} ${akHoerKnopf(w)}</span>`).join("")}</p>
            </div>`).join("")}
        </div>
      </div>
      <div class="question-card">
        <p class="eyebrow">ZUM LAUT SPRECHEN</p>
        <p class="empty-note" style="margin-bottom:12px;">Erst langsam, dann schneller. Jeder Satz übt genau eine Schwierigkeit.</p>
        <div class="ak-liste">
          ${brecher.map((b) => `
            <div class="ak-brecher">
              <p class="ak-brecher-satz">${b.satz} ${akHoerKnopf(b.satz)}</p>
              <p class="ak-b-hinweis">übt: ${b.uebt}</p>
            </div>`).join("")}
        </div>
      </div>`;
  }

  function akTricksHtml() {
    const zeilen = akDaten("TRICKS");
    return zeilen.map((t) => `
      <div class="question-card ak-trick">
        <p class="eyebrow">${t.titel}</p>
        <p class="empty-note" style="margin-bottom:12px;">${t.worum}</p>
        ${t.svg || ""}
        <ol class="ak-schritte">
          ${(t.schritte || []).map((s) => `<li>${s}</li>`).join("")}
        </ol>
        ${t.svg2 || ""}
        <div class="ak-bsp-gitter">
          ${(t.beispiele || []).map((b) => `
            <div class="ak-bsp">
              <span class="ak-bsp-wort">${akWort(b.wort, b.syl)}</span>
              ${akHoerKnopf(b.wort)}
              ${b.hinweis ? `<span class="ak-bsp-hinweis">${b.hinweis}</span>` : ""}
            </div>`).join("")}
        </div>
        ${t.probe ? `<div class="ak-probe"><p>🎧 ${t.probe}</p></div>` : ""}
      </div>`).join("");
  }

  const AK_TEST_RUNDEN = 10;
  function neuerAkTest() {
    const pool = akDaten("TEST");
    akTest = {
      aufgaben: Core.shuffle(pool).slice(0, Math.min(AK_TEST_RUNDEN, pool.length)),
      index: 0, richtig: 0, beantwortet: null, optionen: null,
      sprache: akAktuelleSprache(),
    };
  }
  function akTestHtml() {
    const pool = akDaten("TEST");
    if (!akTest || akTest.sprache !== akAktuelleSprache()) {
      const teile = [...new Set(pool.map((t) => t.teil))];
      return `
        <div class="question-card">
          <p class="eyebrow">TEST</p>
          <p class="empty-note" style="margin-bottom:12px;">
            ${AK_TEST_RUNDEN} Fragen aus allem, was auf dieser Seite steht — Alphabet, Vokallänge,
            Konsonantenbündel, Betonung. Jede richtige Antwort zählt auf dein Punktekonto.
          </p>
          <p class="empty-note" style="margin-bottom:12px;">Bereiche: ${teile.join(" · ")} · ${pool.length} Fragen stehen bereit.</p>
          <button type="button" class="btn btn-coffee" id="akTestStart">▶ Test starten</button>
        </div>`;
    }
    const s = akTest;
    if (s.index >= s.aufgaben.length) return "";
    const a = s.aufgaben[s.index];
    const optionen = s.optionen || Core.shuffle([a.richtig, ...a.falsch]);
    s.optionen = optionen;
    return `
      <div class="question-card">
        <p class="eyebrow">TEST · FRAGE ${s.index + 1} / ${s.aufgaben.length} · ${a.teil}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${optionen.map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn ak-opt${zustand}" data-ak-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="akWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Aussprache-Kurs: " + a.frage)}
      </div>`;
  }

  async function renderAusspracheKurs() {
    autoWeiterAbbrechen();
    const area = document.getElementById("ausspracheKursArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "aussprachekurs_neu", "Aussprache-Kurs", "🗣️", false, true)) return;
    if (!window.DMA_AUSSPRACHE) {
      area.innerHTML = '<p class="empty-note">Der Aussprache-Kurs wird geladen …</p>';
      const ok = await ausspracheKursLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Aussprache-Kurs konnte nicht geladen werden.</p>'; return; }
    }
    if (akTeil === "test" && akTest && akTest.sprache === akAktuelleSprache()
        && akTest.index >= akTest.aufgaben.length) { renderAkTestErgebnis(); return; }

    let inhalt = "";
    if (akTeil === "alphabet") inhalt = akAlphabetHtml();
    else if (akTeil === "verbindungen") inhalt = akVerbindungenHtml();
    else if (akTeil === "regeln") inhalt = akRegelnHtml();
    else if (akTeil === "buendel") inhalt = akBuendelHtml();
    else if (akTeil === "tricks") inhalt = akTricksHtml();
    else if (akTeil === "test") inhalt = akTestHtml();
    area.innerHTML = akKopfHtml() + inhalt;
    akBinden(area);
  }

  function akBinden(area) {
    area.querySelectorAll(".ak-spr-btn").forEach((b) => b.addEventListener("click", () => {
      akSprache = b.dataset.akSpr; akTest = null; renderAusspracheKurs();
    }));
    area.querySelectorAll(".ak-teil-btn").forEach((b) => b.addEventListener("click", () => {
      akTeil = b.dataset.akTeil; renderAusspracheKurs();
      setTimeout(() => { area.scrollIntoView({ behavior: "smooth", block: "start" }); }, 40);
    }));
    // Ein Buchstabe: Name und Beispielwort nacheinander.
    area.querySelectorAll("[data-ak-buchstabe]").forEach((k) => k.addEventListener("click", (ev) => {
      if (ev.target.closest("[data-ak-sprich]")) return;
      const z = akDaten("ALPHABET")[Number(k.dataset.akBuchstabe)];
      if (!z) return;
      Core.speak(z.name, akAktuelleSprache());
      setTimeout(() => Core.speak(z.bsp, akAktuelleSprache()), 1100);
    }));
    document.getElementById("akTestStart")?.addEventListener("click", () => { neuerAkTest(); renderAusspracheKurs(); });
    const s = akTest;
    if (akTeil === "test" && s && s.index < s.aufgaben.length) {
      const a = s.aufgaben[s.index];
      area.querySelectorAll(".ak-opt").forEach((b) => b.addEventListener("click", () => {
        const opt = s.optionen[Number(b.dataset.akOpt)];
        const stimmt = opt === a.richtig;
        if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
        spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
        s.beantwortet = { gewaehlt: opt };
        renderAusspracheKurs();
      }));
      const weiter = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderAusspracheKurs(); };
      document.getElementById("akWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); weiter(); });
      if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, weiter);
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderAkTestErgebnis() {
    const area = document.getElementById("ausspracheKursArea");
    const s = akTest;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    const kategorie = s.sprache === "it" ? "it-aussprachekurs" : "aussprachekurs";
    area.innerHTML = akKopfHtml() + ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Lautlotse",
      charakter: "Aussprache-Kurs",
      zeilen: [{ name: "🗣️ Richtig beantwortet", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="akNochmal">🔄 Noch ein Test</button><button type="button" class="btn btn-ghost" id="akZurueck">Zurück zum Kurs</button>`,
    });
    saveResultAndCheck({
      categories: [kategorie], titelText: "Aussprache-Kurs",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Lautlotse", badges: [], playedAt: new Date().toISOString(),
    });
    akBinden(area);
    document.getElementById("akNochmal")?.addEventListener("click", () => { neuerAkTest(); renderAusspracheKurs(); });
    document.getElementById("akZurueck")?.addEventListener("click", () => { akTest = null; akTeil = "alphabet"; renderAusspracheKurs(); });
  }

  /* Ein Klick auf ein Lautsprechersymbol — überall im Kurs derselbe Griff. */
  document.addEventListener("click", (ev) => {
    const knopf = ev.target.closest("[data-ak-sprich]");
    if (!knopf) return;
    ev.preventDefault();
    ev.stopPropagation();
    Core.speak(knopf.dataset.akSprich, knopf.dataset.akLang || akAktuelleSprache());
  });

  document.querySelector('#learnSubnav [data-sub="sub-alphabet"]')?.addEventListener("click", () => renderAusspracheKurs());

  /* ============================================================
     DIALOGE — formell und informell
     ------------------------------------------------------------
     GEWÜNSCHT: „Gibt es diese Formulare, wo man ausfüllt, wo man
     so eine Begrüßung durchspielt … dass man so einen Formular-
     Ablauf hat, wie man mit jemandem ins Gespräch kommt, locker,
     wie man das formell macht, wie man das informell macht."

     Drei Teile:
       Formular   — die Schritte eines Gesprächs, zu jedem Schritt
                    fertige Sätze in beiden Formen. Man tippt sich
                    sein eigenes Gespräch zusammen.
       Gespräche  — ausgespielte Situationen. Die andere Person
                    redet, man wählt selbst die Antwort. Falsche
                    Antworten sind nicht unverständlich, sondern
                    unpassend — und das wird erklärt.
       Du oder Sie — dieselbe Aussage in beiden Formen, dazu die
                    Regel, wann welche gilt.
     ============================================================ */
  let dialogeGeladen = null;
  function dialogeLaden() {
    if (window.DMA_DIALOGE) return Promise.resolve(true);
    if (dialogeGeladen) return dialogeGeladen;
    dialogeGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-dialoge.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { dialogeGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return dialogeGeladen;
  }

  const DLG_TEILE = { formular: "📋 Gesprächs-Formular", gespraeche: "💬 Gespräche", anrede: "🤝 Du oder Sie?" };
  let dlgTeil = "formular";
  let dlgRegister = "formell";
  let dlgMeins = [];          // die selbst zusammengestellten Sätze
  let dlgLauf = null;         // das gerade gespielte Gespräch

  function dlgSprache() { return imItalienischraum() ? "it" : "de"; }
  function dlgDaten(feld) {
    const D = window.DMA_DIALOGE || {};
    return (D[feld] && D[feld][dlgSprache()]) || [];
  }

  function dlgKopfHtml() {
    return `
      <div class="question-card">
        <p class="eyebrow">💬 GESPRÄCHE FÜHREN</p>
        <p class="empty-note" style="margin-bottom:10px;">
          Ein Gespräch hat immer dieselben Schritte: grüßen, sagen worum es geht, nachfragen,
          antworten, danken, sich verabschieden. Hier stehen die Sätze für jeden Schritt —
          einmal in der Sie-Form für Ämter, Ärzte und Fremde, einmal in der du-Form für
          Nachbarn, Kurs und Freunde. Und dann spielt man es durch.
        </p>
        <div class="trophy-case">
          ${Object.entries(DLG_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip dlg-teil-btn ${dlgTeil === k ? "selected" : ""}" data-dlg-teil="${k}">${name}</button>`).join("")}
        </div>
      </div>`;
  }

  function dlgFormularHtml() {
    const schritte = dlgDaten("SCHRITTE");
    const spr = dlgSprache();
    return `
      <div class="question-card">
        <p class="eyebrow">WELCHE FORM?</p>
        <div class="trophy-case" style="margin-bottom:10px;">
          <button type="button" class="trophy-chip dlg-reg-btn ${dlgRegister === "formell" ? "selected" : ""}" data-dlg-reg="formell">🎩 Sie — Amt, Arzt, Fremde</button>
          <button type="button" class="trophy-chip dlg-reg-btn ${dlgRegister === "informell" ? "selected" : ""}" data-dlg-reg="informell">👋 Du — Freunde, Kurs, Nachbarn</button>
        </div>
        <p class="empty-note" style="margin:0;">Tippe die Sätze an, die du brauchst. Unten entsteht daraus dein eigenes Gespräch, das du behalten kannst.</p>
      </div>
      ${schritte.map((s, si) => `
        <div class="question-card dlg-schritt">
          <p class="eyebrow">${s.name}</p>
          ${s.erklaerung ? `<p class="empty-note" style="margin-bottom:10px;">${s.erklaerung}</p>` : ""}
          <div class="dlg-satzliste">
            ${(s[dlgRegister] || []).map((satz, i) => `
              <div class="dlg-satz">
                <button type="button" class="dlg-satz-text" data-dlg-nimm="${si}:${i}">${satz}</button>
                ${sprichKnopfHtml(satz, spr)}
              </div>`).join("")}
          </div>
          ${s.hinweis ? `<p class="ak-b-hinweis">💡 ${s.hinweis}</p>` : ""}
        </div>`).join("")}
      <div class="question-card" id="dlgMeinsKarte">
        <p class="eyebrow">MEIN GESPRÄCH</p>
        ${dlgMeins.length ? `
          <ol class="dlg-meins sammel-text">
            ${dlgMeins.map((z, i) => `<li>${z} <button type="button" class="dlg-weg" data-dlg-weg="${i}" aria-label="entfernen">✕</button></li>`).join("")}
          </ol>
          <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
            <button type="button" class="btn btn-ghost" id="dlgVorlesen">🔊 Ganz vorlesen</button>
            ${textInListeKnopfHtml("Mein Gespräch")}
            <button type="button" class="btn btn-ghost" id="dlgLeeren">🗑️ Leeren</button>
          </div>` : `<p class="empty-note" style="margin:0;">Noch nichts ausgewählt. Tippe oben auf die Sätze, die du sagen würdest.</p>`}
      </div>`;
  }

  function dlgListeHtml() {
    const alle = dlgDaten("SITUATIONEN");
    return `
      <div class="question-card">
        <p class="eyebrow">GESPRÄCHE ZUM DURCHSPIELEN</p>
        <p class="empty-note" style="margin-bottom:12px;">
          Die andere Person fängt an, du wählst die Antwort. Was nicht passt, wird erklärt —
          nicht weil es falsch wäre, sondern weil es in dieser Situation anders klingt, als du es meinst.
        </p>
        <div class="dlg-kacheln">
          ${alle.map((s) => `
            <button type="button" class="dlg-kachel" data-dlg-start="${s.id}">
              <span class="dlg-kachel-titel">${s.titel}</span>
              <span class="dlg-kachel-ort">${s.ort}</span>
              <span class="dlg-kachel-zeile">
                <span class="dlg-reg-marke dlg-reg-${s.register}">${s.register === "formell" ? "🎩 Sie" : "👋 du"}</span>
                <span class="level-badge">${s.niveau}</span>
                <span class="dlg-kachel-anzahl">${s.zeilen.filter((z) => z.optionen).length} Entscheidungen</span>
              </span>
            </button>`).join("")}
        </div>
      </div>`;
  }

  function dlgSpielHtml() {
    const l = dlgLauf;
    const s = l.situation;
    const spr = dlgSprache();
    const bisher = l.verlauf.map((v) => `
      <div class="dlg-zeile ${v.ich ? "dlg-ich" : "dlg-andere"}">
        <span class="dlg-wer">${v.ich ? "Du" : s.gegenueber.split(",")[0]}</span>
        <span class="dlg-text">${v.text} ${sprichKnopfHtml(v.text, spr)}</span>
      </div>`).join("");
    if (l.index >= s.zeilen.length) return "";
    const z = s.zeilen[l.index];
    return `
      <div class="question-card">
        <p class="eyebrow">${s.titel}</p>
        <p class="empty-note" style="margin-bottom:6px;">📍 ${s.ort} · ${s.register === "formell" ? "🎩 Sie-Form" : "👋 du-Form"} · ${s.niveau}</p>
        <p class="empty-note" style="margin-bottom:12px;">${s.worum}</p>
        ${fortschrittHtml(l.gewaehlt, l.stellen)}
        <div class="dlg-verlauf">${bisher}</div>
        ${z.optionen ? `
          <p class="question-prompt" style="margin:12px 0 10px;">Was sagst du?</p>
          <div class="option-list">
            ${z.optionen.map((o, i) => {
              const g = l.versuche.indexOf(i) >= 0;
              const zustand = !g ? "" : o.ok ? " option-correct" : " option-wrong";
              return `<button type="button" class="option-btn dlg-opt${zustand}" data-dlg-opt="${i}" ${l.fertig || g ? "disabled" : ""}><span>${o.text}</span></button>`;
            }).join("")}
          </div>
          ${l.versuche.length ? `<div class="witz-erklaerung" style="margin-top:12px;">
            ${l.versuche.map((i) => `<p style="margin:0 0 6px;">${z.optionen[i].ok ? "✅ " : "❌ "}${z.optionen[i].warum}</p>`).join("")}
          </div>` : ""}
          ${l.fertig ? `<div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="dlgWeiter">Weiter ▸</button></div>` : ""}
        ` : `<div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="dlgWeiter">Weiter ▸</button></div>`}
        ${miniBugReportBtnHtml("Dialog: " + s.titel)}
      </div>
      <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
        <button type="button" class="btn btn-ghost" id="dlgAbbrechen">← Zurück zur Übersicht</button>
      </div>`;
  }

  function dlgAnredeHtml() {
    const D = window.DMA_DIALOGE || {};
    const paare = dlgDaten("REGISTER");
    const regeln = (D.ANREDE && D.ANREDE.de) || [];
    const anbieten = D.DU_ANBIETEN || {};
    const spr = dlgSprache();
    return `
      <div class="question-card">
        <p class="eyebrow">DIESELBE AUSSAGE, ZWEI FORMEN</p>
        <div class="dlg-paare">
          <div class="dlg-paar dlg-paar-kopf"><span>Wozu</span><span>🎩 Sie</span><span>👋 du</span></div>
          ${paare.map((p) => `
            <div class="dlg-paar">
              <span class="dlg-paar-was">${p.was}</span>
              <span class="dlg-paar-sie"><span class="dlg-paar-icon">🎩</span>${p.sie} ${sprichKnopfHtml(p.sie, spr)}</span>
              <span class="dlg-paar-du"><span class="dlg-paar-icon">👋</span>${p.du} ${sprichKnopfHtml(p.du, spr)}</span>
            </div>`).join("")}
        </div>
      </div>
      ${regeln.length ? `
      <div class="question-card">
        <p class="eyebrow">WANN DUZT MAN, WANN SIEZT MAN?</p>
        <div class="dlg-regeln">
          ${regeln.map((r) => `
            <div class="dlg-regel">
              <span class="dlg-reg-marke dlg-reg-${r.form === "Sie" ? "formell" : "informell"}">${r.form === "Sie" ? "🎩 Sie" : "👋 du"}</span>
              <span class="dlg-regel-wann">${r.wann}${r.warum ? `<span class="ak-b-hinweis">${r.warum}</span>` : ""}</span>
            </div>`).join("")}
        </div>
      </div>` : ""}
      ${anbieten.titel ? `
      <div class="question-card">
        <p class="eyebrow">${anbieten.titel}</p>
        <p class="empty-note" style="margin-bottom:10px;">${anbieten.text}</p>
        <div class="dlg-satzliste">
          ${(anbieten.saetze || []).map((s) => `
            <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, "de")}</div>`).join("")}
        </div>
        <p class="ak-b-hinweis">💡 ${anbieten.ablehnen}</p>
      </div>` : ""}`;
  }

  async function renderDialoge() {
    autoWeiterAbbrechen();
    const area = document.getElementById("dialogeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "dialoge_neu", "Dialoge", "💬", false, true)) return;
    if (!window.DMA_DIALOGE) {
      area.innerHTML = '<p class="empty-note">Die Gespräche werden geladen …</p>';
      const ok = await dialogeLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Die Gespräche konnten nicht geladen werden.</p>'; return; }
    }
    if (dlgLauf && dlgLauf.index >= dlgLauf.situation.zeilen.length) { renderDialogErgebnis(); return; }
    let inhalt = "";
    if (dlgLauf) inhalt = dlgSpielHtml();
    else if (dlgTeil === "formular") inhalt = dlgFormularHtml();
    else if (dlgTeil === "gespraeche") inhalt = dlgListeHtml();
    else if (dlgTeil === "anrede") inhalt = dlgAnredeHtml();
    area.innerHTML = (dlgLauf ? "" : dlgKopfHtml()) + inhalt;
    dlgBinden(area);
  }

  function dlgStarten(id) {
    const s = dlgDaten("SITUATIONEN").find((x) => x.id === id);
    if (!s) return;
    dlgLauf = {
      situation: s, index: 0, verlauf: [], versuche: [], fertig: false,
      punkte: 0, gewaehlt: 0, ohneFehler: 0,
      stellen: s.zeilen.filter((z) => z.optionen).length,
    };
    // Alles, was vor der ersten Wahlstelle steht, gehört schon in den Verlauf.
    dlgVorspulen();
    renderDialoge();
  }
  /* Die Sätze der anderen Person laufen von selbst — stehen bleibt es
     erst, wenn man selbst dran ist. */
  function dlgVorspulen() {
    const l = dlgLauf;
    while (l.index < l.situation.zeilen.length && !l.situation.zeilen[l.index].optionen) {
      const z = l.situation.zeilen[l.index];
      l.verlauf.push({ ich: false, text: z.text });
      l.index += 1;
    }
  }

  function dlgBinden(area) {
    area.querySelectorAll(".dlg-teil-btn").forEach((b) => b.addEventListener("click", () => {
      dlgTeil = b.dataset.dlgTeil; renderDialoge();
    }));
    area.querySelectorAll(".dlg-reg-btn").forEach((b) => b.addEventListener("click", () => {
      dlgRegister = b.dataset.dlgReg; renderDialoge();
    }));
    area.querySelectorAll("[data-dlg-nimm]").forEach((b) => b.addEventListener("click", () => {
      const [si, i] = b.dataset.dlgNimm.split(":").map(Number);
      const satz = (dlgDaten("SCHRITTE")[si] || {})[dlgRegister][i];
      if (satz) { dlgMeins.push(satz); renderDialoge();
        setTimeout(() => document.getElementById("dlgMeinsKarte")?.scrollIntoView({ behavior: "smooth", block: "end" }), 60); }
    }));
    area.querySelectorAll("[data-dlg-weg]").forEach((b) => b.addEventListener("click", () => {
      dlgMeins.splice(Number(b.dataset.dlgWeg), 1); renderDialoge();
    }));
    document.getElementById("dlgLeeren")?.addEventListener("click", () => { dlgMeins = []; renderDialoge(); });
    document.getElementById("dlgVorlesen")?.addEventListener("click", () => {
      Core.speak(dlgMeins.join(". "), dlgSprache());
    });
    area.querySelectorAll("[data-dlg-start]").forEach((b) => b.addEventListener("click", () => dlgStarten(b.dataset.dlgStart)));
    document.getElementById("dlgAbbrechen")?.addEventListener("click", () => { dlgLauf = null; dlgTeil = "gespraeche"; renderDialoge(); });

    const l = dlgLauf;
    if (l && l.index < l.situation.zeilen.length) {
      const z = l.situation.zeilen[l.index];
      area.querySelectorAll(".dlg-opt").forEach((b) => b.addEventListener("click", () => {
        const i = Number(b.dataset.dlgOpt);
        if (l.versuche.indexOf(i) >= 0) return;
        const o = z.optionen[i];
        l.versuche.push(i);
        if (o.ok) {
          /* Punkt gibt es nur, wenn die passende Antwort im ersten
             Anlauf kam — sonst hätte Durchprobieren denselben Wert. */
          if (l.versuche.length === 1) { l.punkte += 1; l.ohneFehler += 1; }
          l.fertig = true;
          l.verlauf.push({ ich: true, text: o.text });
          Core.sound.correct();
        } else Core.sound.wrong();
        spielNotiz(Boolean(o.ok), `${l.situation.titel}: ${o.text}`);
        renderDialoge();
      }));
      document.getElementById("dlgWeiter")?.addEventListener("click", () => {
        if (z.optionen) l.gewaehlt += 1;
        l.index += 1; l.versuche = []; l.fertig = false;
        dlgVorspulen();
        renderDialoge();
      });
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderDialogErgebnis() {
    const area = document.getElementById("dialogeArea");
    const l = dlgLauf;
    const s = l.situation;
    const spr = dlgSprache();
    const prozent = l.stellen ? Math.round((l.ohneFehler / l.stellen) * 100) : 100;
    area.innerHTML = ergebnisSchirmHtml({
      punkte: l.punkte, prozent: prozent, tier: "Gesprächspartner:in",
      charakter: "Dialoge",
      zeilen: [{ name: "💬 Auf Anhieb passend", anteil: prozent, wert: l.ohneFehler + "/" + l.stellen }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="dlgNochmal">🔄 Noch einmal</button><button type="button" class="btn btn-ghost" id="dlgAndere">Anderes Gespräch</button>`,
    }) + `
      <div class="question-card">
        <p class="eyebrow">DAS GANZE GESPRÄCH</p>
        <p class="empty-note" style="margin-bottom:10px;">So ist es gelaufen. Lies es einmal laut mit — beide Rollen.</p>
        <div class="dlg-verlauf">
          ${l.verlauf.map((v) => `
            <div class="dlg-zeile ${v.ich ? "dlg-ich" : "dlg-andere"}">
              <span class="dlg-wer">${v.ich ? "Du" : s.gegenueber.split(",")[0]}</span>
              <span class="dlg-text">${v.text} ${sprichKnopfHtml(v.text, spr)}</span>
            </div>`).join("")}
        </div>
        <div class="quiz-actions" style="justify-content:flex-start; margin-top:10px;">
          <button type="button" class="btn btn-ghost" id="dlgAllesHoeren">🔊 Ganzes Gespräch vorlesen</button>
        </div>
      </div>`;
    saveResultAndCheck({
      categories: [spr === "it" ? "it-dialoge" : "dialoge"], titelText: "Dialog: " + s.titel,
      points: l.punkte, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Gesprächspartner:in", badges: [], playedAt: new Date().toISOString(),
    });
    dlgBinden(area);
    document.getElementById("dlgNochmal")?.addEventListener("click", () => dlgStarten(s.id));
    document.getElementById("dlgAndere")?.addEventListener("click", () => { dlgLauf = null; dlgTeil = "gespraeche"; renderDialoge(); });
    document.getElementById("dlgAllesHoeren")?.addEventListener("click", () => {
      Core.speak(l.verlauf.map((v) => v.text).join(" … "), spr);
    });
  }

  document.querySelector('#learnSubnav [data-sub="sub-dialoge"]')?.addEventListener("click", () => renderDialoge());

  /* ============================================================
     FESTE, FEIERTAGE UND KULTUR
     ------------------------------------------------------------
     GEWÜNSCHT: „Zu Festen und Feiertagen möchte ich auch noch
     irgendwas haben — ja, Weihnachten, Ostern und die wichtigsten
     Sachen zur deutschen Kultur."

     Drei Teile:
       Jahreslauf — jedes Fest mit Datum, Ablauf, Wörtern und den
                    Sätzen, die man an dem Tag braucht.
       Alltag     — das Ungeschriebene: Pünktlichkeit, Ruhezeiten,
                    Mülltrennung, Pfand, Behörden, Vereine.
       Test       — zählt aufs Punktekonto.
     ============================================================ */
  let festeGeladen = null;
  function festeLaden() {
    if (window.DMA_FESTE) return Promise.resolve(true);
    if (festeGeladen) return festeGeladen;
    festeGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-feste.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { festeGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return festeGeladen;
  }

  const FST_TEILE = { jahr: "🗓️ Das Jahr", alltag: "🏠 Alltag & Regeln", test: "✅ Test" };
  const FST_ART = {
    gesetzlich: { marke: "🔴 gesetzlicher Feiertag", erklaerung: "arbeitsfrei, Läden zu" },
    regional: { marke: "🟡 nur in manchen Bundesländern", erklaerung: "je nach Wohnort frei oder nicht" },
    brauch: { marke: "🟢 Brauch", erklaerung: "normaler Arbeitstag — aber alle machen mit" },
  };
  const FST_MONATE = ["", "Januar", "Februar", "März", "April", "Mai", "Juni",
    "Juli", "August", "September", "Oktober", "November", "Dezember"];
  let fstTeil = "jahr";
  let fstOffen = null;
  let fstTest = null;

  function fstSprache() { return imItalienischraum() ? "it" : "de"; }
  function fstDaten(feld) {
    const D = window.DMA_FESTE || {};
    return (D[feld] && D[feld][fstSprache()]) || [];
  }

  function fstKopfHtml() {
    const it = fstSprache() === "it";
    return `
      <div class="question-card">
        <p class="eyebrow">🎄 ${it ? "FESTE UND KULTUR IN ITALIEN" : "FESTE, FEIERTAGE UND KULTUR"}</p>
        <p class="empty-note" style="margin-bottom:10px;">
          ${it
            ? "Der italienische Jahreslauf — und die Dinge, die man wissen muss, ohne dass sie jemand erklärt."
            : "Wann hat alles zu, und warum? Was tut man an Ostern, was an Silvester, und wann gratuliert man auf keinen Fall? Dazu das Ungeschriebene: Ruhezeiten, Mülltrennung, Pfand, Behörden, Vereine. Nichts davon steht in einem Gesetz, das man liest — und alles davon merkt man, wenn man es falsch macht."}
        </p>
        <div class="trophy-case">
          ${Object.entries(FST_TEILE).map(([k, name]) =>
            `<button type="button" class="trophy-chip fst-teil-btn ${fstTeil === k ? "selected" : ""}" data-fst-teil="${k}">${name}</button>`).join("")}
        </div>
      </div>`;
  }

  function fstFestHtml(f, offen) {
    const spr = fstSprache();
    const art = FST_ART[f.art] || FST_ART.brauch;
    return `
      <div class="question-card fst-fest ${offen ? "fst-offen" : ""}">
        <button type="button" class="fst-fest-kopf" data-fst-fest="${f.id}">
          <span class="fst-fest-name">${betonungAnzeigen(f.syl) || f.name}</span>
          <span class="fst-fest-wann">${f.wann}</span>
          <span class="fst-art fst-art-${f.art}" title="${art.erklaerung}">${art.marke}</span>
          <span class="fst-pfeil">${offen ? "▾" : "▸"}</span>
        </button>
        ${offen ? `
          <p class="empty-note" style="margin:10px 0 12px;">${f.worum}</p>
          <ul class="fst-ablauf">
            ${f.ablauf.map((z) => `<li>${z}</li>`).join("")}
          </ul>
          <p class="eyebrow" style="margin-top:14px;">WÖRTER DAZU</p>
          <div class="ak-bsp-gitter">
            ${f.woerter.map((x) => `
              <div class="ak-bsp">
                <span class="ak-bsp-wort">${akWortFrei(x.wort, x.syl, spr)}</span>
                ${sprichKnopfHtml(x.wort, spr)}
                ${x.was ? `<span class="ak-bsp-hinweis">${x.was}</span>` : ""}
              </div>`).join("")}
          </div>
          <p class="eyebrow" style="margin-top:14px;">DAS SAGT MAN</p>
          <div class="dlg-satzliste">
            ${f.saetze.map((s) => `
              <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, spr)}</div>`).join("")}
          </div>
          ${f.hinweis ? `<div class="ak-probe"><p>💡 ${f.hinweis}</p></div>` : ""}
        ` : ""}
      </div>`;
  }

  /* Wie akWort, aber mit frei wählbarer Sprache — der Kulturbereich
     benutzt sie unabhängig vom Aussprache-Kurs. */
  function akWortFrei(wort, syl, sprache) {
    const text = String(wort);
    if (!syl) return text;
    let gezeigt = sprache === "it" ? Core.formatStressIt(syl) : Core.formatStress(syl);
    const artikel = text.match(/^(?:(?:der|die|das|il|lo|la|i|gli|le)\s|l['’])/i);
    const rest = artikel ? text.slice(artikel[0].length) : text;
    if (rest && rest[0] === rest[0].toLowerCase() && rest[0] !== rest[0].toUpperCase()) {
      gezeigt = akErsteKlein(gezeigt);
    }
    return (artikel ? artikel[0] : "") + gezeigt;
  }

  function fstJahrHtml() {
    const feste = fstDaten("FESTE");
    /* Nach Monaten sortiert, damit man den Jahreslauf sieht. Was kein
       festes Datum hat (Geburtstag), steht am Ende. */
    const sortiert = [...feste].sort((a, b) => (a.monat || 13) - (b.monat || 13));
    const heute = new Date().getMonth() + 1;
    const naechstes = sortiert.find((f) => f.monat >= heute) || sortiert[0];
    let letzterMonat = -1;
    return `
      <div class="question-card">
        <p class="eyebrow">DIE DREI ARTEN</p>
        <div class="fst-legende">
          ${Object.entries(FST_ART).map(([k, v]) =>
            `<span class="fst-art fst-art-${k}">${v.marke}</span><span class="ak-b-hinweis" style="margin:0 0 6px;">${v.erklaerung}</span>`).join("")}
        </div>
        ${naechstes ? `<p class="empty-note" style="margin:10px 0 0;">Als Nächstes im Jahr: <strong>${naechstes.name}</strong> — ${naechstes.wann}.</p>` : ""}
      </div>
      ${sortiert.map((f) => {
        let kopf = "";
        if (f.monat !== letzterMonat) {
          letzterMonat = f.monat;
          kopf = `<p class="fst-monat">${f.monat ? FST_MONATE[f.monat] : "Das ganze Jahr"}</p>`;
        }
        return kopf + fstFestHtml(f, fstOffen === f.id);
      }).join("")}`;
  }

  function fstAlltagHtml() {
    const spr = fstSprache();
    return fstDaten("ALLTAG").map((a) => `
      <div class="question-card fst-fest ${fstOffen === a.id ? "fst-offen" : ""}">
        <button type="button" class="fst-fest-kopf" data-fst-fest="${a.id}">
          <span class="fst-fest-name">${a.titel}</span>
          <span class="fst-fest-wann">${a.kurz}</span>
          <span class="fst-pfeil">${fstOffen === a.id ? "▾" : "▸"}</span>
        </button>
        ${fstOffen === a.id ? `
          <ul class="fst-ablauf">${a.punkte.map((p) => `<li>${p}</li>`).join("")}</ul>
          <p class="eyebrow" style="margin-top:14px;">WÖRTER DAZU</p>
          <div class="ak-bsp-gitter">
            ${a.woerter.map((x) => `
              <div class="ak-bsp">
                <span class="ak-bsp-wort">${akWortFrei(x.wort, x.syl, spr)}</span>
                ${sprichKnopfHtml(x.wort, spr)}
                ${x.was ? `<span class="ak-bsp-hinweis">${x.was}</span>` : ""}
              </div>`).join("")}
          </div>
          <p class="eyebrow" style="margin-top:14px;">DAS SAGT MAN</p>
          <div class="dlg-satzliste">
            ${a.saetze.map((s) => `
              <div class="dlg-satz"><span class="dlg-satz-text dlg-satz-fest">${s}</span>${sprichKnopfHtml(s, spr)}</div>`).join("")}
          </div>
          ${a.warnung ? `<div class="ak-ausnahme"><p class="ak-ausnahme-titel">⚠️ Wichtig</p><p>${a.warnung}</p></div>` : ""}
        ` : ""}
      </div>`).join("");
  }

  const FST_RUNDEN = 10;
  function neuerFstTest() {
    const pool = fstDaten("QUIZ");
    fstTest = {
      aufgaben: Core.shuffle(pool).slice(0, Math.min(FST_RUNDEN, pool.length)),
      index: 0, richtig: 0, beantwortet: null, optionen: null, sprache: fstSprache(),
    };
  }
  function fstTestHtml() {
    const pool = fstDaten("QUIZ");
    if (!fstTest || fstTest.sprache !== fstSprache()) {
      return `
        <div class="question-card">
          <p class="eyebrow">TEST</p>
          <p class="empty-note" style="margin-bottom:12px;">
            Fragen aus allem, was hier steht — Feiertage, Bräuche und die Regeln des Alltags.
            ${pool.length} Fragen stehen bereit, eine Runde geht über ${Math.min(FST_RUNDEN, pool.length)}.
          </p>
          <button type="button" class="btn btn-coffee" id="fstTestStart">▶ Test starten</button>
        </div>`;
    }
    const s = fstTest;
    if (s.index >= s.aufgaben.length) return "";
    const a = s.aufgaben[s.index];
    const optionen = s.optionen || Core.shuffle([a.richtig, ...a.falsch]);
    s.optionen = optionen;
    return `
      <div class="question-card">
        <p class="eyebrow">TEST · FRAGE ${s.index + 1} / ${s.aufgaben.length}</p>
        ${fortschrittHtml(s.index, s.aufgaben.length)}
        <p class="question-prompt" style="margin:10px 0 14px;">${a.frage}</p>
        <div class="option-list">
          ${optionen.map((opt, i) => {
            const gewaehlt = s.beantwortet && s.beantwortet.gewaehlt === opt;
            const istRichtig = opt === a.richtig;
            const zustand = !s.beantwortet ? "" : istRichtig ? " option-correct" : gewaehlt ? " option-wrong" : "";
            return `<button type="button" class="option-btn fst-opt${zustand}" data-fst-opt="${i}" ${s.beantwortet ? "disabled" : ""}><span>${opt}</span></button>`;
          }).join("")}
        </div>
        ${s.beantwortet ? `
          <div class="witz-erklaerung" style="margin-top:12px;">
            <p style="margin:0;">${s.beantwortet.gewaehlt === a.richtig ? "✅ " : "❌ "}${a.erkl}</p>
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            <button type="button" class="btn btn-coffee" id="fstWeiter">Weiter ▸</button>
          </div>` : ""}
        ${miniBugReportBtnHtml("Feste & Kultur: " + a.frage)}
      </div>`;
  }

  async function renderFeste() {
    autoWeiterAbbrechen();
    const area = document.getElementById("festeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "feste_kultur_neu", "Feste & Kultur", "🎄", false, true)) return;
    if (!window.DMA_FESTE) {
      area.innerHTML = '<p class="empty-note">Feste und Kultur werden geladen …</p>';
      const ok = await festeLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Der Bereich konnte nicht geladen werden.</p>'; return; }
    }
    if (fstTeil === "test" && fstTest && fstTest.sprache === fstSprache()
        && fstTest.index >= fstTest.aufgaben.length) { renderFstErgebnis(); return; }
    let inhalt = "";
    if (fstTeil === "jahr") inhalt = fstJahrHtml();
    else if (fstTeil === "alltag") inhalt = fstAlltagHtml();
    else if (fstTeil === "test") inhalt = fstTestHtml();
    area.innerHTML = fstKopfHtml() + inhalt;
    fstBinden(area);
  }

  function fstBinden(area) {
    area.querySelectorAll(".fst-teil-btn").forEach((b) => b.addEventListener("click", () => {
      fstTeil = b.dataset.fstTeil; fstOffen = null; renderFeste();
    }));
    area.querySelectorAll("[data-fst-fest]").forEach((b) => b.addEventListener("click", () => {
      const id = b.dataset.fstFest;
      fstOffen = fstOffen === id ? null : id;
      renderFeste();
      if (fstOffen) setTimeout(() => {
        document.querySelector(`[data-fst-fest="${id}"]`)?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 60);
    }));
    document.getElementById("fstTestStart")?.addEventListener("click", () => { neuerFstTest(); renderFeste(); });
    const s = fstTest;
    if (fstTeil === "test" && s && s.index < s.aufgaben.length) {
      const a = s.aufgaben[s.index];
      area.querySelectorAll(".fst-opt").forEach((b) => b.addEventListener("click", () => {
        const opt = s.optionen[Number(b.dataset.fstOpt)];
        const stimmt = opt === a.richtig;
        if (stimmt) { s.richtig += 1; Core.sound.correct(); } else Core.sound.wrong();
        spielNotiz(stimmt, `${a.frage} → ${a.richtig}`);
        s.beantwortet = { gewaehlt: opt };
        renderFeste();
      }));
      const weiter = () => { s.index += 1; s.beantwortet = null; s.optionen = null; renderFeste(); };
      document.getElementById("fstWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); weiter(); });
      if (s.beantwortet) autoWeiter(s.beantwortet.gewaehlt === a.richtig, weiter);
    }
    betonungsSchalterEinhaengen(area.closest(".subview") || undefined);
  }

  function renderFstErgebnis() {
    const area = document.getElementById("festeArea");
    const s = fstTest;
    const prozent = Math.round((s.richtig / s.aufgaben.length) * 100);
    area.innerHTML = fstKopfHtml() + ergebnisSchirmHtml({
      punkte: s.richtig, prozent: prozent, tier: "Landeskundler:in",
      charakter: "Feste & Kultur",
      zeilen: [{ name: "🎄 Richtig beantwortet", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="fstNochmal">🔄 Noch ein Test</button><button type="button" class="btn btn-ghost" id="fstZurueck">Zurück zum Jahr</button>`,
    });
    saveResultAndCheck({
      categories: [s.sprache === "it" ? "it-kultur" : "kultur"], titelText: "Feste & Kultur",
      points: s.richtig, bonus: prozent === 100 ? 3 : 0, percent: prozent,
      character: "Landeskundler:in", badges: [], playedAt: new Date().toISOString(),
    });
    fstBinden(area);
    document.getElementById("fstNochmal")?.addEventListener("click", () => { neuerFstTest(); renderFeste(); });
    document.getElementById("fstZurueck")?.addEventListener("click", () => { fstTest = null; fstTeil = "jahr"; renderFeste(); });
  }

  document.querySelector('#knowledgeSubnav [data-sub="sub-feste"]')?.addEventListener("click", () => renderFeste());
  document.querySelector('#learnSubnav [data-sub="sub-feste"]')?.addEventListener("click", () => renderFeste());

  /* ============================================================
     WEGWEISER
     ------------------------------------------------------------
     GEWÜNSCHT: „Wegweiser: Orientierung auf der Seite und in
     Deutschland."

     Zwei Teile, die beide „Wo muss ich hin?" beantworten:

     Auf der Seite — was es gibt, wo es steht und wofür es gut
     ist. Jeder Eintrag ist ein Knopf, der direkt dorthin
     springt. Wer neu ist, sieht sonst zwanzig Reiter und weiß
     nicht, womit er anfangen soll.

     In Deutschland — die ersten Wochen in der richtigen
     Reihenfolge. Vieles hängt voneinander ab: ohne Anmeldung
     keine Meldebescheinigung, ohne die kein Konto, ohne Konto
     kein Gehalt. Jeder Schritt lässt sich abhaken; der Stand
     hängt am Konto und ist auf jedem Gerät derselbe.
     ============================================================ */
