  let kompassBeitragOpenId = null;
  let beitragLevel = "";
  function renderEigeneBeitraege() {
    const area = document.getElementById("beitraegeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "eigene_beitraege", "Menschen, Dinge, Geschichten", "🗂️")) return;
    const eintraege = eigeneBeitraege();
    if (!eintraege.length) {
      area.innerHTML = '<p class="empty-note">Die Beiträge werden geladen …</p>';
      beitraegeLaden().then(() => { if (document.getElementById("beitraegeArea")) renderEigeneBeitraege(); });
      return;
    }
    beitragLevel = applyDefaultCefrLevel(beitragLevel, (v) => { beitragLevel = v; }, "beitraege");
    // Beim ersten Mal die hochgeladenen Bilder nachziehen und neu zeichnen.
    if (!beitragBilderGeholt) {
      beitragBilderGeholt = true;
      beitragBilderLaden().then(() => { if (document.getElementById("beitraegeArea")) renderEigeneBeitraege(); });
    }
    renderTileGallery(area, eintraege, () => kompassBeitragOpenId, (v) => { kompassBeitragOpenId = v; },
      () => beitragLevel, (v) => { beitragLevel = v; }, "🗂️",
      "Menschen, Geräte und Geschichten, über die man auf Deutsch reden kann — jeder Beitrag in sechs Niveaustufen und zehn Sprachen. Zu jedem steht die Quelle dabei.");
    area.insertAdjacentHTML("afterbegin", leseBetonungKnopfHtml() + textInListeKnopfHtml("Lesetext"));
    leseBetonungAnwenden(area);
  }
  document.querySelector('#knowledgeSubnav [data-sub="sub-dichter"]')?.addEventListener("click", renderDichterUndDenker);
  document.querySelector('#knowledgeSubnav [data-sub="sub-schnee"]')?.addEventListener("click", renderSchneeVonGestern);
  /* ============================================================
     WITZE — mit der Erklärung als eigentlichem Inhalt
     ------------------------------------------------------------
     Wer Deutsch lernt, lacht in Gesprächen oft mit, ohne den Witz
     verstanden zu haben. Genau darum steht die Pointe hier nicht
     allein da: zu jedem Witz gibt es das Wort, an dem er hängt,
     und seine beiden Bedeutungen — aber erst auf Antippen. Wer es
     selbst herausbekommt, soll die Freude daran haben.
     ============================================================ */
  let witzeArt = "alle";
  let witzeOffen = new Set();
  let witzeGeladen = null;
  function witzeLaden() {
    if (window.DMA_DATEN && window.DMA_DATEN.WITZE) return Promise.resolve(true);
    if (witzeGeladen) return witzeGeladen;
    witzeGeladen = new Promise((fertig) => {
      const s = document.createElement("script");
      s.src = "data-witze.js?v=" + (window.DMA_VERSION || "1");
      s.onload = () => fertig(true);
      s.onerror = () => { witzeGeladen = null; fertig(false); };
      document.head.appendChild(s);
    });
    return witzeGeladen;
  }
  const WITZ_ARTEN = {
    alle: "Alle", beruf: "😎 Berufe", wortspiel: "🔤 Wortspiele",
    logik: "🧠 Denkfehler", alltag: "🇩🇪 Alltag & Deutschlernen",
  };
  async function renderWitze() {
    const area = document.getElementById("witzeArea");
    if (!area) return;
    if (!(window.DMA_DATEN && window.DMA_DATEN.WITZE)) {
      area.innerHTML = '<p class="empty-note">Die Witze werden geladen …</p>';
      const ok = await witzeLaden();
      if (!ok) { area.innerHTML = '<p class="empty-note">Die Witze konnten nicht geladen werden.</p>'; return; }
    }
    const alle = window.DMA_DATEN.WITZE;
    const liste = witzeArt === "alle" ? alle : alle.filter((w) => w.art === witzeArt);
    area.innerHTML = `
      <h3 class="kompass-heading">😄 Witze — und warum sie funktionieren</h3>
      <p class="empty-note" style="margin-bottom:12px;">
        Humor ist das Letzte, was man in einer fremden Sprache versteht. Die meisten deutschen Witze
        hängen an einem einzigen Wort, das zwei Bedeutungen hat — „auflegen“, „abschalten“, „aufgehen“.
        Lies erst den Witz. Wenn du die Pointe hast, tipp auf <strong>Warum ist das lustig?</strong> und
        vergleiche. Wenn nicht, findest du dort das Wort und beide Bedeutungen.
      </p>
      <div class="trophy-case" style="margin-bottom:12px;">
        ${/* Nur die Arten anbieten, zu denen es auch Witze gibt — sonst
              führt ein Reiter auf eine leere Seite. Die Berufs-Witze
              sind herausgenommen worden; ihr Reiter hätte sonst noch
              dagestanden. */ ""}
        ${Object.entries(WITZ_ARTEN)
          .filter(([k]) => k === "alle" || alle.some((w) => w.art === k))
          .map(([k, name]) => `<button type="button" class="trophy-chip witz-art-btn ${witzeArt === k ? "selected" : ""}" data-witz-art="${k}">${name}</button>`).join("")}
      </div>
      ${liste.map((w, i) => {
        const offen = witzeOffen.has(w.text);
        return `
        <div class="question-card witz-karte" style="margin-bottom:10px;">
          <p class="witz-text">${w.text}</p>
          <div class="witz-fuss">
            <span class="empty-note" style="font-size:0.68rem;">ab ${w.level}</span>
            <button type="button" class="btn btn-ghost witz-aufloesen" data-witz-idx="${i}" style="padding:4px 12px; font-size:0.76rem;">${offen ? "▾ Erklärung" : "▸ Warum ist das lustig?"}</button>
          </div>
          ${offen ? `
            <div class="witz-erklaerung">
              ${w.wort ? `
                <p style="margin:0 0 6px;"><strong>Das Wort:</strong> „${w.wort}“</p>
                <div class="breakdown-list" style="margin-bottom:8px;">
                  <div class="breakdown-row" style="justify-content:flex-start; gap:8px;"><span>1️⃣</span><span>${w.eins}</span></div>
                  <div class="breakdown-row" style="justify-content:flex-start; gap:8px;"><span>2️⃣</span><span>${w.zwei}</span></div>
                </div>` : ""}
              <p style="margin:0;">${w.erklaerung}</p>
            </div>` : ""}
        </div>`;
      }).join("")}
      <p class="empty-note" style="margin-top:14px;">${liste.length} ${liste.length === 1 ? "Witz" : "Witze"} in dieser Auswahl.</p>`;
    area.querySelectorAll(".witz-art-btn").forEach((b) => b.addEventListener("click", () => { witzeArt = b.dataset.witzArt; renderWitze(); }));
    area.querySelectorAll(".witz-aufloesen").forEach((b) => b.addEventListener("click", () => {
      const w = liste[Number(b.dataset.witzIdx)];
      if (witzeOffen.has(w.text)) witzeOffen.delete(w.text); else witzeOffen.add(w.text);
      renderWitze();
    }));
    leseBetonungAnwenden(area);
  }
  document.querySelector('#knowledgeSubnav [data-sub="sub-witze"]')?.addEventListener("click", renderWitze);

  function renderHowItWorks() {
    const area = document.getElementById("howItWorksArea");
    if (!area) return;
    area.innerHTML = `
      <p class="empty-note" style="margin-bottom:14px;">Eine kurze Erklärung, wie die Seite unter der Haube funktioniert — was passiert eigentlich, wenn du Kategorien auswählst und spielst?</p>

      <div class="material-card">
        <h3>🎯 Was passiert, wenn ich Kategorien auswähle?</h3>
        <p>Jede Übungskategorie gehört zu einer von vier Gruppen: <strong>Grammatik</strong> (z. B. Artikel, Zeitformen, Nebensatz-Konjunktionen), <strong>Wortschatz</strong> (z. B. Synonyme, Redewendungen, Themenwortschatz), <strong>Logik</strong> (z. B. wenn/ob/falls, als/wie) und <strong>Quiz</strong> (Deutschland-Wissen). Je mehr du innerhalb einer Gruppe spielst, desto mehr "fällst du in dieses Profil" — die Seite erkennt automatisch, worauf du gerade deinen Schwerpunkt legst.</p>
      </div>

      <div class="material-card">
        <h3>💪 Wie erkennt die Seite meine Schwächen?</h3>
        <p>Auf zwei Wegen: Erstens automatisch — wenn deine Trefferquote in einer Kategorie niedriger ist als in anderen, merkt sich die Seite das. Zweitens selbst eingeschätzt — in den Einstellungen kannst du pro Kategorie angeben, ob du dich "stark", "mittel" oder "schwach" fühlst. Diese Selbsteinschätzung hat Vorrang vor der automatischen Erkennung, weil du dich selbst am besten kennst.</p>
      </div>

      <div class="material-card">
        <h3>🎯 Was bringt mir das für die Tagesaufgabe?</h3>
        <p>Deine tägliche Kalenderblatt-Aufgabe wird nicht komplett zufällig gewählt — sie orientiert sich, wo möglich, an genau der Kategorie, die als deine aktuelle Schwäche erkannt wurde (ob selbst eingeschätzt oder automatisch). So übst du automatisch öfter genau das, was dir am meisten bringt, ohne dass du selbst daran denken musst.</p>
      </div>

      <div class="material-card">
        <h3>⭐ Wie funktionieren Punkte und Schwierigkeitsgrade?</h3>
        <p>Für jede richtig gelöste Frage gibt es Punkte, bei manchen Spielen zusätzlich einen kleinen Tempo-Bonus für schnelles, sicheres Antworten. Bei Spielen mit Schwierigkeitsgraden (🟢 Leicht/🟡 Mittel/🔴 Schwer) kannst du frei wählen — es gibt keine Einschränkung, wer welchen Grad spielen darf. Ein höherer Schwierigkeitsgrad bedeutet meist etwas anspruchsvollere Fragen, nicht automatisch mehr Punkte pro Frage.</p>
      </div>

      <div class="material-card">
        <h3>🦊 Was hat es mit den Sammelfiguren auf sich?</h3>
        <p>Beim Spielen sammelst du nach und nach Punkte und Erfolge — damit schaltest du automatisch neue Fuchs-Sammelfiguren frei, die du in deinem Profil sammeln und dir sogar als Profilbild einstellen kannst. Mehr dazu findest du direkt bei den Sammelfiguren in deinem Profil.</p>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-account" style="margin-top:8px;">🦊 Zu den Sammelfiguren springen</button>
      </div>

      <div class="material-card">
        <h3>🏆 Orden und Pokale</h3>
        <p>Nach jeder Runde bekommst du einen Titel, zusammengesetzt aus deinem "Charakter" (welche Kategorien du gespielt hast) und deiner "Stufe" (wie gut du warst) — z. B. "Grammatik-Profi – Superheld". Die zwei höchsten Stufen zählen als 🏆 Pokal, alles darunter als 🎖️ Orden. Antippen zeigt dir genau, wie du sie verdient hast.</p>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-missions" style="margin-top:8px;">🏆 Zu den Missionen springen</button>
      </div>

      <div class="material-card">
        <h3>👤 Wie ist mein Profil aufgebaut?</h3>
        <ul style="margin:0; padding-left:18px;">
          <li><strong>Profil</strong> — dein Steckbrief, Punkte, Vitrine, Sammelfiguren-Vorschau, Interview-Vorschau</li>
          <li><strong>Freunde</strong> — wen du kennst, Duelle, Online-Status</li>
          <li><strong>Ranking</strong> — wer heute/insgesamt vorn liegt, plus "Fuchs des Tages" (siehe unten)</li>
          <li><strong>Postfach</strong> — private Nachrichten, auch von Alex/dem Team</li>
          <li><strong>Gästebuch</strong> — öffentliche Grüße und Bewertungen</li>
          <li><strong>Interview</strong> — persönliche Fragen, ab 150 Punkten freigeschaltet</li>
          <li><strong>Sticker-Album</strong> — die vollständige Fuchs-Sammlung im Überblick</li>
          <li><strong>Design</strong> — das Aussehen der ganzen Seite ändern</li>
          <li><strong>Einstellungen</strong> — Benachrichtigungen, Sprachniveau, Seite teilen</li>
        </ul>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-account" style="margin-top:8px;">👤 Zum Profil springen</button>
      </div>

      <div class="material-card">
        <h3>🎖️ Was bedeuten die kleinen Namens-Abzeichen?</h3>
        <p class="empty-note" style="margin-bottom:10px;">Falls du bei jemandem so ein Abzeichen neben dem Namen siehst — hier die Erklärung, damit du dich nicht wundern musst:</p>
        <div class="breakdown-list">
          <div class="breakdown-row"><span>${adminBadge(false, true, false)}</span><span class="empty-note">Betreibt die Seite</span></div>
          <div class="breakdown-row"><span>${adminBadge(true, false, false)}</span><span class="empty-note">Verwaltet die Seite</span></div>
          <div class="breakdown-row"><span>${adminBadge(false, false, true)}</span><span class="empty-note">Moderiert Inhalte</span></div>
          <div class="breakdown-row"><span>${adminBadge(false, false, false, false, true)}</span><span class="empty-note">Baut die Seite aktiv mit auf</span></div>
          <div class="breakdown-row"><span>${adminBadge(false, false, false, true)}</span><span class="empty-note">Testet neue Funktionen vorab</span></div>
          <div class="breakdown-row"><span>${adminBadge(false, false, false, false, false, true)}</span><span class="empty-note">Hat die Seite unterstützt</span></div>
        </div>
      </div>

      <div class="material-card">
        <h3>🦊 Was ist "Fuchs des Tages"?</h3>
        <p>Jeden Tag wird automatisch berechnet, wer am aktivsten war — nicht nur nach Punkten, sondern auch nach eingereichten Beiträgen, Platz 1 im Ranking und ob die Seite geteilt wurde. Wer gewinnt, bekommt Bonuspunkte UND eine kleine Zeugnis-artige Vorstellung mit Begründung. Vergangene Gewinner:innen stehen in der Hall of Fame.</p>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-ranking" style="margin-top:8px;">🦊 Zu "Fuchs des Tages" springen</button>
      </div>

      <div class="material-card">
        <h3>✍️ Wie kann ich selbst etwas beitragen?</h3>
        <p>Du kannst eigene Lesetexte einreichen und Links vorschlagen — alles wird von Alex geprüft, bevor es öffentlich sichtbar wird. Für bestätigte Beiträge gibt's teilweise sogar Bonuspunkte.</p>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-community" style="margin-top:8px;">✍️ Eigene Beiträge findest du hier</button>
      </div>

      <div class="material-card">
        <h3>💡 Was ist das Schwarmwissen?</h3>
        <p>Hier trägt die ganze Community wertvolle Tipps zusammen — von Lernenden für Lernende: was beim Deutschlernen bei anderen funktioniert hat, hilfreiche Links, kleine Tricks für schwierige Themen. Teil gerne selbst etwas, das dir geholfen hat, oder stöber durch das, was andere schon gesammelt haben.</p>
        <button type="button" class="btn btn-ghost" data-help-jump="sub-tips" style="margin-top:8px;">💡 Zum Schwarmwissen springen</button>
      </div>
    `;
    // Zuordnung: welcher Unterreiter gehört zu welchem Hauptreiter — nötig, damit der Sprung-Link
    // zuerst den richtigen Hauptreiter aktiviert, bevor der Unterreiter selbst angeklickt wird.
    const SUB_TO_MAIN_TAB = {
      "sub-account": "view-profile", "sub-friends": "view-profile", "sub-ranking": "view-profile",
      "sub-inbox": "view-profile", "sub-guestbook": "view-profile", "sub-interview": "view-profile",
      "sub-album": "view-profile", "sub-design": "view-profile", "sub-settings": "view-profile",
      "sub-community": "view-knowledge", "sub-links": "view-knowledge", "sub-tips": "view-knowledge",
      "sub-music": "view-knowledge", "sub-news": "view-knowledge", "sub-kompass": "view-knowledge",
      "sub-missions": "view-learn", "sub-exercises": "view-learn",
    };
    area.querySelectorAll("[data-help-jump]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const target = btn.dataset.helpJump;
        const mainTab = SUB_TO_MAIN_TAB[target] || "view-profile";
        document.querySelector(`[data-target="${mainTab}"]`)?.click();
        setTimeout(() => {
          const subnavId = mainTab === "view-profile" ? "profileSubnav" : mainTab === "view-learn" ? "learnSubnav" : "knowledgeSubnav";
          document.querySelector(`#${subnavId} [data-sub="${target}"]`)?.click();
        }, 150);
      });
    });
  }
  document.querySelector('#knowledgeSubnav [data-sub="sub-howitworks"]')?.addEventListener("click", renderHowItWorks);
  document.querySelector('#knowledgeSubnav [data-sub="sub-kompass"]')?.addEventListener("click", renderKompass);

  const LOGIN_PLACEHOLDER_SVG = `<svg class="site-banner-svg" viewBox="0 0 400 120" preserveAspectRatio="xMidYMid slice">
    <defs><linearGradient id="loginGrad" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#f2b84b"/><stop offset="100%" stop-color="#e8825f"/>
    </linearGradient></defs>
    <rect width="400" height="120" fill="url(#loginGrad)"/>
    <circle cx="60" cy="90" r="26" fill="rgba(255,255,255,0.1)"/>
    <circle cx="340" cy="20" r="22" fill="rgba(255,255,255,0.1)"/>
    <text x="200" y="55" text-anchor="middle" font-size="30" font-family="sans-serif">🦊👋</text>
    <text x="200" y="90" text-anchor="middle" font-size="16" font-weight="700" fill="#fff" font-family="sans-serif">Willkommen!</text>
  </svg>`;
  const WISSEN_PLACEHOLDER_SVG = `<svg class="site-banner-svg" viewBox="0 0 400 120" preserveAspectRatio="xMidYMid slice">
    <defs><linearGradient id="wissenGrad" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#4fa88e"/><stop offset="100%" stop-color="#3ec6c6"/>
    </linearGradient></defs>
    <rect width="400" height="120" fill="url(#wissenGrad)"/>
    <circle cx="350" cy="25" r="30" fill="rgba(255,255,255,0.1)"/>
    <circle cx="40" cy="90" r="18" fill="rgba(255,255,255,0.1)"/>
    <text x="200" y="55" text-anchor="middle" font-size="30" font-family="sans-serif">🧭</text>
    <text x="200" y="90" text-anchor="middle" font-size="16" font-weight="700" fill="#fff" font-family="sans-serif">Wissen &amp; Kompass</text>
  </svg>`;
  // Kachel-Übersicht aller Spiele — ersetzt die frühere lange Liste einzelner Knöpfe direkt im
  // Hauptmenü. Jede Kachel simuliert beim Antippen einen Klick auf den zugehörigen, jetzt
  // unsichtbaren Original-Knopf (siehe index.html) — das behält alle dort schon registrierten
  // Klick-Listener bei, ohne dass jeder einzeln umgebaut werden musste.
  // Alphabetisch nach Name sortiert (vorher zufällig/nach Bauzeit geordnet — wirkte durcheinander,
  // z. B. stand der Betonungs-Trainer ganz unten statt einsortiert).
  // WICHTIG — behebt einen echten Bug: die Kacheln für noch nicht freigegebene, neue Spiele
  // (flagKey gesetzt) erschienen hier bisher UNBEDINGT für alle — auch wenn das Spiel selbst beim
  // Antippen nur "kommt bald" zeigte, verriet schon der sichtbare Name in der Liste, dass es
  // existiert. Ältere, längst etablierte Spiele (kein flagKey) bleiben immer sichtbar; neue,
  // ausdrücklich noch nicht freigegebene Spiele werden weiter unten in renderGamesOverview()
  // komplett aus der Liste gefiltert, bis der Flag aktiv angeschaltet ist (oder man
  // Beta-Tester:in/Admin ist).
  /* ============================================================
     WORTSCHMIEDE — zusammengesetzte Wörter schmieden
     ------------------------------------------------------------
     Eigene, handgezeichnete SVG-Szene: Amboss, Esse, Hammer und Funken.
     Das erste Wortteil liegt glühend auf dem Amboss, unten liegen vier
     Rohlinge — nur einer ergibt ein echtes deutsches Wort. Bei einem
     Treffer schlägt der Hammer zu, Funken sprühen, und das fertige Wort
     erscheint mit seinem Artikel.

     Niveau kommt aus dem Profil (wie überall), der Schwierigkeitsgrad
     bestimmt allein die Anzahl der Runden.
     ============================================================ */
  const WSM_RUNDEN = { leicht: 10, mittel: 20, schwer: 30 };
  let wsmSession = null;
  let wsmLevel = null;
  let wsmSchwierigkeit = "leicht";
  let wsmAktuell = null;
  let wsmZustand = "warten"; // warten | richtig | falsch

  function wsmPool() {
    const alle = ExerciseData.WORTSCHMIEDE || [];
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const grenze = stufen.indexOf(wsmLevel);
    // Alles bis einschließlich des gewählten Niveaus — bleibt zu wenig übrig,
    // wird schrittweise geöffnet, damit nie eine leere Runde entsteht.
    for (let spielraum = 0; spielraum < stufen.length; spielraum++) {
      const treffer = alle.filter((w) => stufen.indexOf(w[5]) <= grenze + spielraum);
      if (treffer.length >= 6) return treffer;
    }
    return alle;
  }
  function neueWsmSession() {
    wsmLevel = applyDefaultCefrLevel(wsmLevel, (v) => { wsmLevel = v; }, "wortschmiede");
    const gesamt = Math.min(WSM_RUNDEN[wsmSchwierigkeit] || 10, wsmPool().length);
    wsmSession = { runde: 0, gesamt, richtig: 0, gespielt: [] };
    wsmAktuell = null;
  }
  function neueWsmRunde() {
    const pool = wsmPool().filter((w) => !wsmSession.gespielt.includes(w[2]));
    const auswahl = (pool.length ? pool : wsmPool())[Math.floor(Math.random() * (pool.length || wsmPool().length))];
    wsmSession.gespielt.push(auswahl[2]);
    const optionen = Core.shuffle([auswahl[1], ...auswahl[4]]);
    wsmAktuell = { teil1: auswahl[0], teil2: auswahl[1], wort: auswahl[2], bedeutung: auswahl[3], optionen, level: auswahl[5] };
    wsmZustand = "warten";
  }
  // Die Schmiede-Szene. Bewusst aus einfachen Formen gebaut statt als Bilddatei —
  // dadurch passt sie sich jedem Design-Theme an (currentColor) und bleibt scharf.
  function wsmSchmiedeSvg(zustand) {
    const funken = zustand === "richtig";
    return `
    <svg viewBox="0 0 200 130" width="100%" style="max-width:320px; display:block; margin:0 auto;" aria-hidden="true">
      <defs>
        <linearGradient id="wsmGlut" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#FFD79A"/><stop offset="55%" stop-color="#F2913B"/><stop offset="100%" stop-color="#D2431E"/>
        </linearGradient>
        <linearGradient id="wsmEisen" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#6E7278"/><stop offset="100%" stop-color="#3A3D42"/>
        </linearGradient>
      </defs>
      <!-- Esse im Hintergrund -->
      <path d="M8 96 L8 52 Q8 44 16 44 L44 44 Q52 44 52 52 L52 96 Z" fill="#59453A"/>
      <path d="M14 96 L14 60 L46 60 L46 96 Z" fill="#2E2320"/>
      <path d="M20 92 Q24 78 30 88 Q34 74 40 92 Z" fill="url(#wsmGlut)"/>
      <rect x="4" y="40" width="52" height="7" rx="3" fill="#3E2F27"/>
      <path d="M26 40 Q24 30 30 26 Q28 34 34 32 Q32 38 30 40 Z" fill="#F2913B" opacity="0.75"/>
      <!-- Amboss -->
      <path d="M96 74 L164 74 L158 84 L102 84 Z" fill="url(#wsmEisen)"/>
      <path d="M164 74 Q180 76 176 82 L158 84 Z" fill="url(#wsmEisen)"/>
      <rect x="118" y="84" width="22" height="16" fill="#4A4E54"/>
      <path d="M104 100 L154 100 L160 114 L98 114 Z" fill="#5A4034"/>
      <!-- Werkstück auf dem Amboss -->
      <rect x="112" y="66" width="36" height="8" rx="3" fill="url(#wsmGlut)"/>
      <!-- Hammer, schlägt bei einem Treffer zu -->
      <g class="wsm-hammer ${funken ? "wsm-hammer-schlag" : ""}" style="transform-origin:150px 40px;">
        <rect x="146" y="34" width="42" height="10" rx="3" fill="#8A6A4F"/>
        <rect x="132" y="26" width="22" height="26" rx="4" fill="#4A4E54"/>
        <rect x="136" y="30" width="6" height="18" rx="2" fill="#6E7278"/>
      </g>
      ${funken ? `
        <g class="wsm-funken">
          ${[0, 1, 2, 3, 4, 5, 6].map((i) => {
            const x = 118 + i * 6, y = 66 - (i % 3) * 5;
            return `<circle cx="${x}" cy="${y}" r="${1.6 + (i % 3) * 0.5}" fill="#FFD79A" style="animation-delay:${i * 60}ms"/>`;
          }).join("")}
        </g>` : ""}
      <!-- Boden -->
      <rect x="0" y="114" width="200" height="16" fill="#C9B79A" opacity="0.5"/>
    </svg>`;
  }
  function renderWortschmiede() {
    const area = document.getElementById("wortschmiedeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "wortschmiede_neu", "Wortschmiede", "🔨")) return;
    if (!wsmSession) neueWsmSession();
    if (wsmSession.runde >= wsmSession.gesamt) { renderWortschmiedeErgebnis(); return; }
    if (!wsmAktuell) neueWsmRunde();
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Wortschmiede: " + wsmAktuell.wort)}
        <p class="eyebrow">🔨 WORTSCHMIEDE · RUNDE ${wsmSession.runde + 1} / ${wsmSession.gesamt} <span class="subnav-info-icon" data-info="Deutsch baut aus zwei Wörtern ein neues. Das letzte Wort bestimmt Artikel und Bedeutung, das erste beschreibt genauer. Alle vier Rohlinge ergeben ein echtes deutsches Wort — gesucht ist aber genau das eine, das zur angegebenen Bedeutung passt.">ⓘ</span></p>
        ${fortschrittHtml(wsmSession.runde, wsmSession.gesamt)}
        <div class="wsm-level-zeile">
          <div class="trophy-case wsm-chips">
            ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip wsm-level-btn ${wsmLevel === lvl ? "selected" : ""}" data-wsm-level="${lvl}">${lvl}</button>`).join("")}
          </div>
        </div>
        ${wsmSchmiedeSvg(wsmZustand)}
        <p class="wsm-bedeutung">Gesucht: ${wsmAktuell.bedeutung}</p>
        <p class="wsm-teil1">${wsmAktuell.teil1}<span class="wsm-plus">+</span><span class="wsm-luecke">?</span></p>
        <div class="wsm-rohlinge">
          ${wsmAktuell.optionen.map((o) => `<button type="button" class="wsm-rohling" data-wsm-opt="${o}">${o}</button>`).join("")}
        </div>
        <p class="empty-note wsm-feedback" id="wsmFeedback">${wsmZustand === "warten" ? "Alle vier ergeben ein echtes Wort — welches passt zur Bedeutung?" : ""}</p>
        <p class="empty-note" style="margin-top:10px; font-size:0.7rem;">Runden: ${Object.entries(WSM_RUNDEN).map(([k, v]) => `<button type="button" class="wsm-diff-btn ${wsmSchwierigkeit === k ? "aktiv" : ""}" data-wsm-diff="${k}">${k} (${v})</button>`).join(" ")}</p>
      </div>`;
    area.querySelectorAll(".wsm-level-btn").forEach((b) => b.addEventListener("click", () => {
      wsmLevel = b.dataset.wsmLevel; neueWsmSession(); neueWsmRunde(); renderWortschmiede();
    }));
    area.querySelectorAll(".wsm-diff-btn").forEach((b) => b.addEventListener("click", () => {
      wsmSchwierigkeit = b.dataset.wsmDiff; neueWsmSession(); neueWsmRunde(); renderWortschmiede();
    }));
    area.querySelectorAll(".wsm-rohling").forEach((b) => b.addEventListener("click", () => pruefeWortschmiede(b)));
  }
  function pruefeWortschmiede(btn) {
    if (wsmZustand !== "warten") return;
    const gewaehlt = btn.dataset.wsmOpt;
    const richtig = gewaehlt === wsmAktuell.teil2;
    wsmSession.runde += 1;
    spielNotiz(richtig, `${wsmAktuell.wort} — ${wsmAktuell.bedeutung}`);
    document.querySelectorAll(".wsm-rohling").forEach((b) => { b.disabled = true; });
    const fb = document.getElementById("wsmFeedback");
    if (richtig) {
      wsmSession.richtig += 1;
      wsmZustand = "richtig";
      Core.sound.correct();
      btn.classList.add("wsm-treffer");
      fb.innerHTML = `✅ <strong>${wsmAktuell.wort}</strong> — ${wsmAktuell.bedeutung}`;
    } else {
      wsmZustand = "falsch";
      Core.sound.wrong();
      btn.classList.add("wsm-daneben");
      document.querySelectorAll(".wsm-rohling").forEach((b) => { if (b.dataset.wsmOpt === wsmAktuell.teil2) b.classList.add("wsm-treffer"); });
      fb.innerHTML = `❌ Richtig wäre <strong>${wsmAktuell.wort}</strong> — ${wsmAktuell.bedeutung}`;
    }
    setTimeout(() => { neueWsmRunde(); renderWortschmiede(); }, richtig ? 1600 : 2400);
  }
  function renderWortschmiedeErgebnis() {
    const area = document.getElementById("wortschmiedeArea");
    const prozent = Math.round((wsmSession.richtig / wsmSession.gesamt) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: wsmSession.richtig, prozent: prozent, tier: "Wortschmied:in",
      charakter: "Wortschmiede", zeilen: [{ name: "🔨 Geschmiedet", anteil: prozent, wert: wsmSession.richtig + "/" + wsmSession.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="wsmNochmalBtn">🔄 Neue Runden</button>`,
    });
    document.getElementById("wsmNochmalBtn").addEventListener("click", () => { neueWsmSession(); neueWsmRunde(); renderWortschmiede(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["wortschmiede"], points: wsmSession.richtig, bonus: 0, percent: prozent, character: "Wortschmied:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-wortschmiede"]')?.addEventListener("click", () => {
    if (!wsmSession) neueWsmSession();
    if (!wsmAktuell) neueWsmRunde();
    renderWortschmiede();
  });

  /* ============================================================
     SATZBRÜCKE — den tragenden Verbinder finden
     ------------------------------------------------------------
     Zwei Satzhälften stehen auf zwei Felsen über einer Schlucht. Nur das
     passende Verbindungswort trägt. Jede richtige Antwort legt eine
     Planke; am Ende läuft der Fuchs hinüber.

     Auch hier: Niveau aus dem Profil, Schwierigkeitsgrad = Rundenzahl.
     ============================================================ */
  const SB_RUNDEN = { leicht: 10, mittel: 20, schwer: 30 };
  let sbSession = null;
  let sbLevel = null;
  let sbSchwierigkeit = "leicht";
  let sbAktuell = null;
  let sbZustand = "warten";

  function sbPool() {
    const alle = ExerciseData.SATZBRUECKE || [];
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const grenze = stufen.indexOf(sbLevel);
    for (let spielraum = 0; spielraum < stufen.length; spielraum++) {
      const treffer = alle.filter((z) => stufen.indexOf(z[5]) <= grenze + spielraum);
      if (treffer.length >= 5) return treffer;
    }
    return alle;
  }
  function neueSbSession() {
    sbLevel = applyDefaultCefrLevel(sbLevel, (v) => { sbLevel = v; }, "satzbruecke");
    const gesamt = Math.min(SB_RUNDEN[sbSchwierigkeit] || 10, sbPool().length);
    sbSession = { runde: 0, gesamt, richtig: 0, gespielt: [], planken: 0 };
    sbAktuell = null;
  }
  function neueSbRunde() {
    const pool = sbPool().filter((z) => !sbSession.gespielt.includes(z[0]));
    const wahl = (pool.length ? pool : sbPool())[Math.floor(Math.random() * (pool.length || sbPool().length))];
    sbSession.gespielt.push(wahl[0]);
    sbAktuell = { a: wahl[0], b: wahl[1], loesung: wahl[2], optionen: Core.shuffle([wahl[2], ...wahl[3]]), erklaerung: wahl[4] };
    sbZustand = "warten";
  }
  // Schlucht mit zwei Felsen. Die Planken wachsen mit jeder richtigen Antwort —
  // sichtbarer Fortschritt statt nur einer Zahl.
  // ueberquerung = true: die Brücke wird erst fertig gebaut, DANN läuft der Fuchs
  // wirklich von einem Felsen zum anderen (statt nur am Brückenende zu stehen).
  function sbBrueckeSvg(planken, gesamt, geschafft, ueberquerung) {
    const anteil = Math.max(0, Math.min(1, planken / Math.max(1, gesamt)));
    const brueckeBreite = 96 * anteil;
    return `
    <svg viewBox="0 0 200 120" width="100%" style="max-width:340px; display:block; margin:0 auto;" aria-hidden="true">
      <defs>
        <linearGradient id="sbHimmel" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#BFE3E0"/><stop offset="100%" stop-color="#F3E7D2"/>
        </linearGradient>
        <linearGradient id="sbFels" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#9C8163"/><stop offset="100%" stop-color="#5E4A38"/>
        </linearGradient>
      </defs>
      <rect x="0" y="0" width="200" height="120" fill="url(#sbHimmel)"/>
      <!-- ferne Berge -->
      <path d="M0 66 L28 40 L48 60 L70 34 L96 66 Z" fill="#A9C4BE" opacity="0.55"/>
      <path d="M104 66 L130 42 L150 62 L172 38 L200 66 Z" fill="#A9C4BE" opacity="0.4"/>
      <!-- linker Felsen -->
      <path d="M0 62 L50 62 L54 74 L48 118 L0 118 Z" fill="url(#sbFels)"/>
      <path d="M0 62 L50 62 L46 68 L0 68 Z" fill="#7FA88C"/>
      <!-- rechter Felsen -->
      <path d="M150 62 L200 62 L200 118 L152 118 L146 74 Z" fill="url(#sbFels)"/>
      <path d="M150 62 L200 62 L200 68 L154 68 Z" fill="#7FA88C"/>
      <!-- Seile -->
      <path d="M50 62 Q100 ${74 - 8 * anteil} 150 62" stroke="#6B5136" stroke-width="1.6" fill="none" opacity="${0.3 + 0.5 * anteil}"/>
      <path d="M50 68 Q100 ${82 - 8 * anteil} 150 68" stroke="#6B5136" stroke-width="1.2" fill="none" opacity="${0.25 + 0.4 * anteil}"/>
      <!-- Planken: wachsen von links -->
      <g>
        ${Array.from({ length: Math.round(brueckeBreite / 8) }).map((_, i) => {
          const x = 52 + i * 8;
          const y = 64 + Math.sin((x - 50) / 96 * Math.PI) * (8 - 6 * anteil);
          return `<rect x="${x}" y="${y}" width="6.5" height="3.4" rx="1.2" fill="#8A6A4F" class="sb-planke" style="animation-delay:${i * 40}ms"/>`;
        }).join("")}
      </g>
      ${geschafft || anteil > 0 ? (() => {
        /* Der Fuchs geht NUR los, wenn die Brücke wirklich durchgehend ist.
           Vorher lief er auch bei Lücken bis zum Abbruch — das sah aus, als
           würde er ins Leere marschieren. Fehlt auch nur eine Planke, bleibt
           er auf dem linken Felsen stehen und schaut hinüber. */
        const vollstaendig = planken >= gesamt;
        const darfLaufen = ueberquerung && vollstaendig;
        // Ziel ist nicht das Brückenende, sondern der rechte Felsen: er soll
        // wirklich drüben ankommen und sich dort hinsetzen.
        const zielX = darfLaufen ? 168 : (vollstaendig ? 168 : 42);
        const zielY = darfLaufen ? 55 : (vollstaendig ? 55 : 55);
        const startX = 42 - 100;
        const startY = 55 - 51;
        const plankenDauer = Math.round(brueckeBreite / 8) * 40 + 320;
        const laufDauer = 2400;
        const laufStil = darfLaufen
          ? `--sb-start-x:${startX}px; --sb-start-y:${startY}px; --sb-ziel-x:${zielX - 100}px; --sb-ziel-y:${zielY - 51}px; --sb-verzoegerung:${plankenDauer}ms;`
          : `transform: translate(${(vollstaendig ? zielX : 42) - 100}px, ${zielY - 51}px);`;
        const klasse = darfLaufen ? "sb-fuchs-ueberquert" : (vollstaendig ? "sb-fuchs-laeuft" : "sb-fuchs-wartet");
        return `
        <g class="sb-fuchs ${klasse}" style="${laufStil}">
          <!-- Schwanz mit heller Spitze -->
          <path d="M92 54 q-11 -1 -12 -8 q-1 -6 5 -7 q-2 6 3 8 q4 2 6 4 Z" fill="#D9714E"/>
          <path d="M80 46 q-1 -6 5 -7 q-2 4 0 6 Z" fill="#F7DCC9"/>
          <!-- Hinterlauf -->
          <path d="M95 56 l-1 6 q0 2 2 2 l3 0 q1 -2 -1 -3 l0 -5 Z" fill="#C9603F"/>
          <!-- Körper -->
          <ellipse cx="100" cy="52" rx="10" ry="6.4" fill="#E8825F"/>
          <path d="M92 54 q8 4 17 0 q-3 4 -9 4 q-5 0 -8 -4 Z" fill="#F7DCC9"/>
          <!-- Vorderlauf -->
          <path d="M105 56 l0 6 q0 2 2 2 l3 0 q1 -2 -1 -3 l0 -5 Z" fill="#C9603F"/>
          <!-- Kopf -->
          <circle cx="109" cy="46" r="5.2" fill="#F09A72"/>
          <path d="M104.6 42.4 l0.8 -4.6 l3.4 2.8 Z" fill="#E8825F"/>
          <path d="M110 41.6 l3 -3.8 l1 4.4 Z" fill="#E8825F"/>
          <path d="M105.6 42.8 l0.5 -2.6 l1.9 1.6 Z" fill="#F7C6B0"/>
          <path d="M110.4 42.2 l1.7 -2.2 l0.6 2.5 Z" fill="#F7C6B0"/>
          <!-- Gesicht -->
          <path d="M107 47.5 q3 2.6 6 0.4 q-1 3 -3.4 3 q-2.2 0 -2.6 -3.4 Z" fill="#FAE7DA"/>
          <circle cx="108" cy="45.4" r="0.85" fill="#3A2A20"/>
          <circle cx="111.4" cy="45.2" r="0.85" fill="#3A2A20"/>
          <circle cx="112.6" cy="47.6" r="0.9" fill="#3A2A20"/>
          ${vollstaendig ? "" : `<path d="M108.4 49.6 q1.6 -1 3 0" stroke="#3A2A20" stroke-width="0.7" fill="none" stroke-linecap="round"/>`}
        </g>
        ${darfLaufen ? `
        <!-- Der sitzende, zufriedene Fuchs auf dem rechten Felsen. Er erscheint
             erst, wenn der Lauf zu Ende ist — der laufende blendet dann aus. -->
        <g class="sb-fuchs-sitzt" style="animation-delay:${plankenDauer + laufDauer}ms;">
          <path d="M162 58 q-9 0 -10 -6 q-1 -5 4 -6 q-2 5 3 7 q3 2 5 3 Z" fill="#D9714E"/>
          <path d="M152 46 q-1 -5 4 -6 q-2 4 0 5 Z" fill="#F7DCC9"/>
          <path d="M164 60 q3 -12 8 -12 q5 0 6 8 q1 5 -1 6 Z" fill="#E8825F"/>
          <ellipse cx="171" cy="60" rx="7" ry="4" fill="#C9603F"/>
          <path d="M166 56 q6 3 11 0 q-2 3 -6 3 q-3 0 -5 -3 Z" fill="#F7DCC9"/>
          <circle cx="173" cy="48" r="5" fill="#F09A72"/>
          <path d="M168.8 44.6 l0.7 -4.4 l3.2 2.7 Z" fill="#E8825F"/>
          <path d="M174 43.8 l2.9 -3.6 l0.9 4.2 Z" fill="#E8825F"/>
          <path d="M171 49.4 q3 2.5 5.8 0.4 q-1 2.9 -3.3 2.9 q-2.1 0 -2.5 -3.3 Z" fill="#FAE7DA"/>
          <!-- zufriedene, zusammengekniffene Augen -->
          <path d="M170.6 47 q1.2 -1.2 2.4 0" stroke="#3A2A20" stroke-width="0.8" fill="none" stroke-linecap="round"/>
          <path d="M174.4 46.8 q1.2 -1.2 2.4 0" stroke="#3A2A20" stroke-width="0.8" fill="none" stroke-linecap="round"/>
          <circle cx="176.4" cy="49.4" r="0.85" fill="#3A2A20"/>
          <path d="M172 51.4 q1.8 1.4 3.4 0" stroke="#3A2A20" stroke-width="0.7" fill="none" stroke-linecap="round"/>
          <!-- erhobene Pfote, winkt kurz -->
          <g class="sb-fuchs-pfote">
            <path d="M166 54 q-3 -4 -1 -7 q2 -2 3 1 q1 3 0 6 Z" fill="#F09A72"/>
          </g>
        </g>` : ""}`;
      })() : ""}
      <!-- Nebel in der Schlucht -->
      <ellipse cx="100" cy="112" rx="52" ry="8" fill="#ffffff" opacity="0.5"/>
    </svg>`;
  }
  function renderSatzbruecke() {
    const area = document.getElementById("satzbrueckeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "satzbruecke_neu", "Satzbrücke", "🌉")) return;
    if (!sbSession) neueSbSession();
    if (sbSession.runde >= sbSession.gesamt) { renderSatzbrueckeErgebnis(); return; }
    if (!sbAktuell) neueSbRunde();
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Satzbrücke: " + sbAktuell.a)}
        <p class="eyebrow">🌉 SATZBRÜCKE · RUNDE ${sbSession.runde + 1} / ${sbSession.gesamt} <span class="subnav-info-icon" data-info="Zwei Satzhälften, eine Schlucht dazwischen. Nur das passende Verbindungswort trägt die Brücke. Jede richtige Antwort legt eine Planke.">ⓘ</span></p>
        ${fortschrittHtml(sbSession.runde, sbSession.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip sb-level-btn ${sbLevel === lvl ? "selected" : ""}" data-sb-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${sbBrueckeSvg(sbSession.planken, sbSession.gesamt, false)}
        <div class="sb-satz">
          <p class="sb-haelfte">${sbAktuell.a}<span class="sb-luecke">?</span></p>
          <p class="sb-haelfte sb-haelfte-b">${sbAktuell.b}.</p>
        </div>
        <div class="sb-optionen">
          ${sbAktuell.optionen.map((o) => `<button type="button" class="sb-option" data-sb-opt="${o}">${o}</button>`).join("")}
        </div>
        <p class="empty-note sb-feedback" id="sbFeedback">Welches Wort verbindet die beiden Hälften?</p>
        <p class="empty-note" style="margin-top:10px; font-size:0.7rem;">Runden: ${Object.entries(SB_RUNDEN).map(([k, v]) => `<button type="button" class="wsm-diff-btn ${sbSchwierigkeit === k ? "aktiv" : ""}" data-sb-diff="${k}">${k} (${v})</button>`).join(" ")}</p>
      </div>`;
    area.querySelectorAll(".sb-level-btn").forEach((b) => b.addEventListener("click", () => {
      sbLevel = b.dataset.sbLevel; neueSbSession(); neueSbRunde(); renderSatzbruecke();
    }));
    area.querySelectorAll("[data-sb-diff]").forEach((b) => b.addEventListener("click", () => {
      sbSchwierigkeit = b.dataset.sbDiff; neueSbSession(); neueSbRunde(); renderSatzbruecke();
    }));
    area.querySelectorAll(".sb-option").forEach((b) => b.addEventListener("click", () => pruefeSatzbruecke(b)));
  }
  function pruefeSatzbruecke(btn) {
    if (sbZustand !== "warten") return;
    const gewaehlt = btn.dataset.sbOpt;
    const richtig = gewaehlt === sbAktuell.loesung;
    sbSession.runde += 1;
    spielNotiz(richtig, `Lösung „${sbAktuell.loesung}“ — ${sbAktuell.erklaerung}`);
    sbZustand = richtig ? "richtig" : "falsch";
    document.querySelectorAll(".sb-option").forEach((b) => { b.disabled = true; });
    const fb = document.getElementById("sbFeedback");
    if (richtig) {
      sbSession.richtig += 1;
      sbSession.planken += 1;
      Core.sound.correct();
      btn.classList.add("sb-treffer");
      fb.innerHTML = `✅ ${sbAktuell.erklaerung}`;
    } else {
      Core.sound.wrong();
      btn.classList.add("sb-daneben");
      document.querySelectorAll(".sb-option").forEach((b) => { if (b.dataset.sbOpt === sbAktuell.loesung) b.classList.add("sb-treffer"); });
      fb.innerHTML = `❌ Es trägt nur „${sbAktuell.loesung}“ — ${sbAktuell.erklaerung}`;
    }
    // Die Lücke im Satz sichtbar füllen, damit man den fertigen Satz einmal ganz liest.
    const luecke = document.querySelector(".sb-luecke");
    if (luecke) { luecke.textContent = ` ${sbAktuell.loesung} `; luecke.classList.add("sb-luecke-gefuellt"); }
    setTimeout(() => { neueSbRunde(); renderSatzbruecke(); }, richtig ? 1900 : 2700);
  }
  function renderSatzbrueckeErgebnis() {
    const area = document.getElementById("satzbrueckeArea");
    const prozent = Math.round((sbSession.richtig / sbSession.gesamt) * 100);
    const geschafft = prozent >= 60;
    area.innerHTML = ergebnisSchirmHtml({
      punkte: sbSession.richtig, prozent: prozent, tier: "Brückenbauer:in",
      charakter: "Satzbrücke", zeilen: [{ name: "🌉 Planken gelegt", anteil: prozent, wert: sbSession.richtig + "/" + sbSession.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="sbNochmalBtn">🔄 Neue Runden</button>`,
    });
    document.getElementById("sbNochmalBtn").addEventListener("click", () => { neueSbSession(); neueSbRunde(); renderSatzbruecke(); });
    // Ton erst, wenn der Fuchs wirklich angekommen (oder an der Lücke stehen geblieben) ist —
    // vorher lief der Ton, während die Brücke noch gebaut wurde.
    const vollstaendig = sbSession.richtig >= sbSession.gesamt;
    const anteilFertig = Math.max(0, Math.min(1, sbSession.richtig / Math.max(1, sbSession.gesamt)));
    const laufDauer = Math.round(96 * anteilFertig / 8) * 40 + 320 + (vollstaendig ? 2400 : 0);
    setTimeout(() => {
      if (!document.getElementById("satzbrueckeArea")) return;
      if (vollstaendig) {
        Core.sound.fanfare();                       // Triumph beim Ankommen
        if (Core.sound.miau) setTimeout(() => Core.sound.miau(), 700);
      } else {
        Core.sound.fail();                          // gedämpftes „knapp nicht"
      }
    }, laufDauer);
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["satzbruecke"], points: sbSession.richtig, bonus: 0, percent: prozent, character: "Brückenbauer:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-satzbruecke"]')?.addEventListener("click", () => {
    if (!sbSession) neueSbSession();
    if (!sbAktuell) neueSbRunde();
    renderSatzbruecke();
  });

  /* ============================================================
     ARTIKEL-GARTEN — der, die, das als drei Beete
     ------------------------------------------------------------
     Drei Beete, ein Samenkorn mit einem Wort darauf. Wer richtig
     einpflanzt, sieht die Blume wachsen — und am Ende, welches Beet am
     vollsten ist. Die Wörter kommen aus derselben geprüften Artikel-Bank
     wie die normale Übung, es gibt also keinen zweiten Datenbestand, der
     auseinanderlaufen könnte.
     ============================================================ */
  const AG_RUNDEN = { leicht: 10, mittel: 20, schwer: 30 };
  // Im Italienisch-Raum wird derselbe Garten mit den italienischen Artikeln bepflanzt.
  // Das Spiel bleibt dasselbe, nur die Beete und die Fragenquelle wechseln mit.
  function agImItalienischraum() { return ExerciseData.getLernraum && ExerciseData.getLernraum() === "it"; }
  const AG_BEETE_IT = [
    { key: "il", label: "il", farbe: "#5B8DEF", blume: "#7BA7F5" },
    { key: "lo", label: "lo", farbe: "#E8608A", blume: "#F58CAE" },
    { key: "la", label: "la", farbe: "#4FA88E", blume: "#7FC9B3" },
  ];
  function agBeete() { return agImItalienischraum() ? AG_BEETE_IT : AG_BEETE_DE; }
  const AG_BEETE_DE = [
    { key: "der", label: "der", farbe: "#5B8DEF", blume: "#7BA7F5" },
    { key: "die", label: "die", farbe: "#E8608A", blume: "#F58CAE" },
    { key: "das", label: "das", farbe: "#4FA88E", blume: "#7FC9B3" },
  ];
  let agSession = null;
  let agLevel = null;
  let agSchwierigkeit = "leicht";
  let agAktuell = null;
  let agZustand = "warten";

  function agPool() {
    const katId = agImItalienischraum() ? "it-artikel" : "artikel";
    const kat = ExerciseData.activeGetCategory(katId);
    const bank = (kat && kat.getBank()) || [];
    // Nur Aufgaben, deren Lösung wirklich einer der drei Artikel dieses Raums ist —
    // im italienischen Bestand kommen auch „l'“, „un“ oder „gli“ als Lösung vor,
    // und die passen zu keinem der drei Beete.
    const erlaubt = agBeete().map((b) => b.key);
    const passend = bank.filter((q) => erlaubt.includes(q.options[q.correct[0]]));
    // Auf das gewählte Niveau eingrenzen — Artikel-Fragen tragen ihr Niveau
    // entweder selbst oder erben es aus der Kategorie (siehe Quiz.questionLevel).
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const grenze = stufen.indexOf(agLevel);
    for (let spielraum = 0; spielraum < stufen.length; spielraum++) {
      const treffer = passend.filter((q) => stufen.indexOf(Quiz.questionLevel(q, katId)) <= grenze + spielraum);
      if (treffer.length >= 12) return treffer;
    }
    return passend.length ? passend : bank;
  }
  function neueAgSession() {
    agLevel = applyDefaultCefrLevel(agLevel, (v) => { agLevel = v; }, "artikelgarten");
    const leereBeete = {}; agBeete().forEach((b) => { leereBeete[b.key] = 0; });
    agSession = { runde: 0, gesamt: AG_RUNDEN[agSchwierigkeit] || 10, richtig: 0, beete: leereBeete, gespielt: [] };
    agAktuell = null;
  }
  function neueAgRunde() {
    const pool = agPool().filter((q) => !agSession.gespielt.includes(q.prompt));
    const quelle = pool.length ? pool : agPool();
    const q = quelle[Math.floor(Math.random() * quelle.length)];
    agSession.gespielt.push(q.prompt);
    agAktuell = {
      wort: q.prompt.replace(/^_+\s*/, ""),
      loesung: q.options[q.correct[0]],
      erklaerung: q.explain || "",
    };
    agZustand = "warten";
  }
  // Der Garten. Jedes Beet zeigt so viele Blumen, wie dort richtig gepflanzt
  // wurde — der Fortschritt ist damit auf einen Blick sichtbar.
  function agGartenSvg() {
    const beetBreite = 60;
    return `
    <svg viewBox="0 0 200 118" width="100%" style="max-width:340px; display:block; margin:0 auto;" aria-hidden="true">
      <defs>
        <linearGradient id="agHimmel" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#CDE7F0"/><stop offset="100%" stop-color="#F5EEDC"/>
        </linearGradient>
        <linearGradient id="agErde" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#7A5A3C"/><stop offset="100%" stop-color="#4E3826"/>
        </linearGradient>
      </defs>
      <rect x="0" y="0" width="200" height="118" fill="url(#agHimmel)"/>
      <circle cx="176" cy="20" r="12" fill="#F6CC78"/>
      <path d="M0 72 Q40 64 80 70 Q130 77 200 68 L200 118 L0 118 Z" fill="#8FBF86" opacity="0.55"/>
      ${agBeete().map((beet, i) => {
        const x = 8 + i * 64;
        const anzahl = agSession ? agSession.beete[beet.key] : 0;
        const blumen = Math.min(anzahl, 6);
        return `
          <g>
            <rect x="${x}" y="80" width="${beetBreite}" height="26" rx="5" fill="url(#agErde)"/>
            <rect x="${x}" y="78" width="${beetBreite}" height="5" rx="2.5" fill="${beet.farbe}"/>
            ${/* Ab der vierten Blume kam bisher eine zweite Reihe dazu, deren
                  Stängel zwölf Bildpunkte ÜBER der Erde begann — die Blumen
                  schwebten sichtbar in der Luft. Jetzt wurzelt jede Blume in
                  der Erde; die hintere Reihe steht nur weiter hinten (höher
                  im Bild), ist etwas kleiner und wird zuerst gezeichnet,
                  damit sie hinter der vorderen liegt. */""}
            ${[...Array.from({ length: blumen }).keys()].sort((a, b) => (b < 3 ? 1 : 0) - (a < 3 ? 1 : 0)).map((k) => {
              const hinten = k >= 3;
              const bx = hinten ? x + 15 + (k - 3) * 17 : x + 9 + k * 20;
              const wurzel = hinten ? 84 : 88;            // beides innerhalb des Erdstreifens (80–106)
              const stiel = hinten ? 13 : 16;
              const r = hinten ? 3.4 : 4.2;
              const kopf = wurzel - stiel - 3;
              return `
                <g class="ag-blume" style="animation-delay:${k * 70}ms">
                  <path d="M${bx} ${wurzel} L${bx} ${wurzel - stiel}" stroke="#3F7D4E" stroke-width="1.8" stroke-linecap="round"/>
                  <path d="M${bx} ${wurzel - stiel * 0.5} q-5 -3 -6 -7 q5 0 6 4" fill="#4E9660"/>
                  <circle cx="${bx}" cy="${kopf}" r="${r}" fill="${beet.blume}"/>
                  <circle cx="${bx}" cy="${kopf}" r="${r * 0.43}" fill="#F6CC78"/>
                </g>`;
            }).join("")}
            <text x="${x + beetBreite / 2}" y="97" text-anchor="middle" font-size="11" font-weight="800" fill="#FFF7E9">${beet.label}</text>
            <text x="${x + beetBreite / 2}" y="104.5" text-anchor="middle" font-size="6.5" fill="#E4D6BE">${anzahl}</text>
          </g>`;
      }).join("")}
    </svg>`;
  }
  function renderArtikelgarten() {
    const area = document.getElementById("artikelgartenArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "artikelgarten_neu", "Artikel-Garten", "🌷")) return;
    if (!agSession) neueAgSession();
    if (agSession.runde >= agSession.gesamt) { renderArtikelgartenErgebnis(); return; }
    if (!agAktuell) neueAgRunde();
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Artikel-Garten: " + agAktuell.wort)}
        <p class="eyebrow">🌷 ARTIKEL-GARTEN · RUNDE ${agSession.runde + 1} / ${agSession.gesamt} <span class="subnav-info-icon" data-info="Jedes deutsche Substantiv gehört zu genau einem der drei Beete. Pflanze das Wort ins richtige — bei jedem Treffer wächst dort eine Blume.">ⓘ</span></p>
        ${fortschrittHtml(agSession.runde, agSession.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip ag-level-btn ${agLevel === lvl ? "selected" : ""}" data-ag-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${agGartenSvg()}
        <p class="ag-samen">${agAktuell.wort}</p>
        <div class="ag-beet-knoepfe">
          ${agBeete().map((b) => `<button type="button" class="ag-beet-btn" data-ag-beet="${b.key}" style="--beet:${b.farbe};">${b.label}</button>`).join("")}
        </div>
        <p class="empty-note ag-feedback" id="agFeedback">In welches Beet gehört dieses Wort?</p>
        <p class="empty-note" style="margin-top:10px; font-size:0.7rem;">Runden: ${Object.entries(AG_RUNDEN).map(([k, v]) => `<button type="button" class="wsm-diff-btn ${agSchwierigkeit === k ? "aktiv" : ""}" data-ag-diff="${k}">${k} (${v})</button>`).join(" ")}</p>
      </div>`;
    area.querySelectorAll(".ag-level-btn").forEach((b) => b.addEventListener("click", () => {
      agLevel = b.dataset.agLevel; neueAgSession(); neueAgRunde(); renderArtikelgarten();
    }));
    area.querySelectorAll("[data-ag-diff]").forEach((b) => b.addEventListener("click", () => {
      agSchwierigkeit = b.dataset.agDiff; neueAgSession(); neueAgRunde(); renderArtikelgarten();
    }));
    area.querySelectorAll(".ag-beet-btn").forEach((b) => b.addEventListener("click", () => pruefeArtikelgarten(b)));
  }
  function pruefeArtikelgarten(btn) {
    if (agZustand !== "warten") return;
    const gewaehlt = btn.dataset.agBeet;
    const richtig = gewaehlt === agAktuell.loesung;
    agSession.runde += 1;
    spielNotiz(richtig, `${agAktuell.loesung} ${agAktuell.wort}`);
    agZustand = richtig ? "richtig" : "falsch";
    document.querySelectorAll(".ag-beet-btn").forEach((b) => { b.disabled = true; });
    const fb = document.getElementById("agFeedback");
    if (richtig) {
      agSession.richtig += 1;
      agSession.beete[gewaehlt] += 1;
      Core.sound.correct();
      btn.classList.add("ag-treffer");
      fb.innerHTML = `✅ <strong>${agAktuell.loesung} ${agAktuell.wort}</strong> — eingepflanzt.`;
    } else {
      Core.sound.wrong();
      btn.classList.add("ag-daneben");
      document.querySelectorAll(".ag-beet-btn").forEach((b) => { if (b.dataset.agBeet === agAktuell.loesung) b.classList.add("ag-treffer"); });
      fb.innerHTML = `❌ ${agAktuell.erklaerung || `Richtig ist <strong>${agAktuell.loesung} ${agAktuell.wort}</strong>.`}`;
    }
    setTimeout(() => { neueAgRunde(); renderArtikelgarten(); }, richtig ? 1400 : 2300);
  }
  function renderArtikelgartenErgebnis() {
    const area = document.getElementById("artikelgartenArea");
    const prozent = Math.round((agSession.richtig / agSession.gesamt) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: agSession.richtig, prozent: prozent, tier: "Gärtner:in",
      charakter: "Artikel-Garten", zeilen: [{ name: "🌷 Blumen gepflanzt", anteil: prozent, wert: agSession.richtig + "/" + agSession.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="agNochmalBtn">🔄 Neue Runde</button>`,
    });
    document.getElementById("agNochmalBtn").addEventListener("click", () => { neueAgSession(); neueAgRunde(); renderArtikelgarten(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["artikel"], points: agSession.richtig, bonus: 0, percent: prozent, character: "Gärtner:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-artikelgarten"]')?.addEventListener("click", () => {
    if (!agSession) neueAgSession();
    if (!agAktuell) neueAgRunde();
    renderArtikelgarten();
  });

  /* ============================================================
     WO IST DIE KATZE? — Präpositionen sehen statt übersetzen
     ------------------------------------------------------------
     Ein gezeichnetes Zimmer mit Tisch, Stuhl, Korb und Regal. Die Katze
     sitzt jede Runde woanders — das BILD ist die Aufgabe. Dadurch wird
     die Präposition direkt mit der räumlichen Vorstellung verknüpft,
     statt über eine Übersetzung zu laufen. Ab B1 kommt zusätzlich der
     Unterschied wo/wohin (Dativ/Akkusativ) dazu.
     ============================================================ */
  const KZ_RUNDEN = { leicht: 10, mittel: 20, schwer: 30 };
  /* Die Szenen des Katzenzimmers. Jede Szene hat eine eigene Kennung, damit innerhalb
     einer Runde nie dieselbe Szene zweimal drankommt — vorher gab es pro Präposition
     nur EIN Bild, und bei vier erlaubten Präpositionen auf A1 wiederholte sich die
     Frage ständig. Jetzt gibt es zu jeder Präposition mehrere Möbel.
     haltung bestimmt, WIE die Katze gezeichnet wird: eine liegende Katze liegt wirklich
     (Beine untergeschlagen), eine sitzende sitzt auf ihrem Hinterteil, eine stehende
     steht auf allen vieren.
     Bodenlinie im Bild ist y = 120. Daraus ergeben sich die y-Werte:
     sitzen = Boden − 18, stehen = Boden − 17, liegen = Boden − 16. */
  const KZ_ORTE = [
    { id: "auf-tisch", key: "auf", x: 146, y: 48, haltung: "sitzen", satz: "Die Katze sitzt ___ dem Tisch.", erkl: "„auf“ — sie berührt die Tischplatte von oben. Ort → Dativ: auf dem Tisch." },
    { id: "auf-stuhl", key: "auf", x: 84, y: 60, haltung: "sitzen", skala: 0.85, satz: "Die Katze sitzt ___ dem Stuhl.", erkl: "„auf“ — sie sitzt oben auf der Sitzfläche. Ort → Dativ: auf dem Stuhl." },
    { id: "auf-fernseher", key: "auf", x: 34, y: 50, haltung: "liegen", skala: 0.8, satz: "Die Katze liegt ___ dem Fernseher.", erkl: "„auf“ — sie liegt oben auf dem Gerät, weil es dort warm ist." },
    { id: "unter-tisch", key: "unter", x: 146, y: 104, haltung: "liegen", satz: "Die Katze liegt ___ dem Tisch.", erkl: "„unter“ — sie ist tiefer als der Tisch. Ort → Dativ: unter dem Tisch." },
    { id: "unter-stuhl", key: "unter", x: 84, y: 104, haltung: "liegen", skala: 0.8, satz: "Die Katze liegt ___ dem Stuhl.", erkl: "„unter“ — sie hat sich unter die Sitzfläche gelegt." },
    { id: "neben-korb", key: "neben", x: 258, y: 103, haltung: "stehen", skala: 0.8, satz: "Die Katze steht ___ dem Korb.", erkl: "„neben“ — sie steht direkt daneben, aber nicht darin." },
    { id: "neben-fernseher", key: "neben", x: 66, y: 103, haltung: "stehen", skala: 0.62, satz: "Die Katze steht ___ dem Fernseher.", erkl: "„neben“ — sie ist seitlich davon, nicht davor und nicht dahinter." },
    { id: "hinter-stuhl", key: "hinter", x: 86, y: 101, haltung: "stehen", hinten: true, satz: "Die Katze versteckt sich ___ dem Stuhl.", erkl: "„hinter“ — der Stuhl steht zwischen dir und der Katze." },
    { id: "hinter-fernseher", key: "hinter", x: 16, y: 101, haltung: "stehen", hinten: true, skala: 0.85, satz: "Die Katze versteckt sich ___ dem Fernseher.", erkl: "„hinter“ — man sieht nur noch einen Teil von ihr, das Gerät steht davor." },
    { id: "vor-tisch", key: "vor", x: 142, y: 112, haltung: "sitzen", satz: "Die Katze sitzt ___ dem Tisch.", erkl: "„vor“ — sie ist näher bei dir als der Tisch." },
    { id: "vor-fernseher", key: "vor", x: 34, y: 112, haltung: "sitzen", skala: 0.9, satz: "Die Katze sitzt ___ dem Fernseher.", erkl: "„vor“ — sie sitzt zwischen dir und dem Gerät und schaut zu." },
    { id: "in-korb", key: "in", x: 214, y: 90, haltung: "liegen", imKorb: true, skala: 0.65, satz: "Die Katze schläft ___ dem Korb.", erkl: "„in“ — sie ist von etwas umschlossen." },
    { id: "zwischen-fernseher-stuhl", key: "zwischen", x: 62, y: 102, haltung: "sitzen", skala: 0.6, satz: "Die Katze sitzt ___ dem Fernseher und dem Stuhl.", erkl: "„zwischen“ — links und rechts von ihr steht je ein Ding." },
    { id: "zwischen-tisch-korb", key: "zwischen", x: 190, y: 102, haltung: "sitzen", skala: 0.6, satz: "Die Katze sitzt ___ dem Tisch und dem Korb.", erkl: "„zwischen“ — sie hat auf beiden Seiten ein Möbelstück." },
  ];
  // Dasselbe Zimmer auf Italienisch: gleiche Bilder, gleiche Orte — nur die
  // Präposition und der Satz wechseln. So übt man im Italienisch-Raum genau
  // dieselbe räumliche Vorstellung mit den italienischen Wörtern.
  const KZ_ORTE_IT = {
    auf: { key: "sul", satz: "Il gatto è ___ tavolo.", erkl: "„su“ + „il“ verschmelzen zu „sul“ — die Katze berührt die Tischplatte von oben." },
    unter: { key: "sotto", satz: "Il gatto sta ___ il tavolo.", erkl: "„sotto“ heißt unter — die Katze liegt tiefer als der Tisch." },
    neben: { key: "accanto", satz: "Il gatto è ___ alla sedia.", erkl: "„accanto a“ heißt neben; mit „la sedia“ wird daraus „accanto alla sedia“." },
    hinter: { key: "dietro", satz: "Il gatto si nasconde ___ la sedia.", erkl: "„dietro“ heißt hinter — der Stuhl steht zwischen dir und der Katze." },
    vor: { key: "davanti", satz: "Il gatto è ___ al tavolo.", erkl: "„davanti a“ heißt vor; mit „il tavolo“ wird daraus „davanti al tavolo“." },
    in: { key: "nel", satz: "Il gatto dorme ___ cesto.", erkl: "„in“ + „il“ verschmelzen zu „nel“ — die Katze ist vom Korb umschlossen." },
    zwischen: { key: "tra", satz: "Il gatto è ___ il tavolo e il cesto.", erkl: "„tra“ (oder „fra“) heißt zwischen — links und rechts steht je ein Ding." },
  };
  function kzImItalienischraum() { return ExerciseData.getLernraum && ExerciseData.getLernraum() === "it"; }
  // Liefert einen Ort in der Fassung des aktuellen Raums: Bildposition und Haltung
  // bleiben gleich, Satz und Lösungswort wechseln mit der Sprache.
  function kzOrtFuerRaum(ort) {
    if (!kzImItalienischraum()) return ort;
    const it = KZ_ORTE_IT[ort.key];
    return it ? { ...ort, key: it.key, satz: it.satz, erkl: it.erkl } : ort;
  }
  let kzSession = null;
  let kzLevel = null;
  let kzSchwierigkeit = "leicht";
  let kzAktuell = null;
  let kzZustand = "warten";

  function neueKzSession() {
    kzLevel = applyDefaultCefrLevel(kzLevel, (v) => { kzLevel = v; }, "kettenzauber");
    kzSession = { runde: 0, gesamt: KZ_RUNDEN[kzSchwierigkeit] || 10, richtig: 0 };
    kzAktuell = null;
  }
  function neueKzRunde() {
    // Auf A1/A2 nur die vier anschaulichsten Präpositionen — „zwischen“ und
    // „hinter“ setzen räumliches Vokabular voraus, das dort noch fehlt.
    const einfach = ["auf", "unter", "neben", "in"];
    const erlaubt = (kzLevel === "A1" || kzLevel === "A2") ? KZ_ORTE.filter((o) => einfach.includes(o.key)) : KZ_ORTE;
    // Innerhalb einer Runde kommt keine Szene zweimal dran. Erst wenn wirklich alle
    // Szenen einmal da waren, fängt die Liste von vorn an — vorher stand dieselbe
    // Frage regelmäßig mehrmals hintereinander da.
    if (kzSession && !kzSession.gespielt) kzSession.gespielt = [];
    const gespielt = (kzSession && kzSession.gespielt) || [];
    let uebrig = erlaubt.filter((o) => !gespielt.includes(o.id));
    if (!uebrig.length) { if (kzSession) kzSession.gespielt = []; uebrig = erlaubt; }
    const roh = uebrig[Math.floor(Math.random() * uebrig.length)];
    if (kzSession) kzSession.gespielt.push(roh.id);
    const ort = kzOrtFuerRaum(roh);
    // Ablenker: andere Präpositionen, jede nur einmal.
    const andere = [...new Set(erlaubt.map(kzOrtFuerRaum).map((o) => o.key))].filter((k) => k !== ort.key);
    kzAktuell = { ort, optionen: Core.shuffle([ort.key, ...Core.shuffle(andere).slice(0, 3)]) };
    kzZustand = "warten";
  }
  function kzZimmerSvg(ort, zeigen) {
    const k = ort;
    // Die Katze wird je nach Ort an einer anderen Stelle in die Zeichnung eingesetzt:
    // hinter einem Möbel liegt sie WIRKLICH dahinter (also davor gezeichnet), im Korb
    // steckt sie hinter der Korbwand — sonst sähe „hinter" aus wie „neben".
    const katze = `<g class="kz-katze" style="transform: translate(${k.x - 100}px, ${k.y - 90}px);"><g transform="translate(100 98) scale(${k.skala || 1}) translate(-100 -98)">${kzKatzeSvg(k.haltung || "sitzen")}</g></g>`;
    return `
    <svg viewBox="0 0 280 138" width="100%" style="max-width:380px; display:block; margin:0 auto;" aria-hidden="true">
      <defs>
        <linearGradient id="kzWand" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#F3E4CE"/><stop offset="100%" stop-color="#E4D2B6"/>
        </linearGradient>
        <linearGradient id="kzBoden" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#C09468"/><stop offset="100%" stop-color="#9A7247"/>
        </linearGradient>
      </defs>
      <rect x="0" y="0" width="280" height="112" fill="url(#kzWand)"/>
      <!-- Der Boden beginnt deutlich HÖHER als die Möbelfüße enden. Dadurch stehen Stuhl,
           Tisch, Fernseher und Korb sichtbar AUF dem Boden, statt an der Wandkante zu
           schweben, wie es vorher aussah. -->
      <rect x="0" y="112" width="280" height="26" fill="url(#kzBoden)"/>
      <path d="M0 112 L280 112" stroke="#7E5C38" stroke-width="1.5"/>
      <path d="M0 121 H280" stroke="#8A6A45" stroke-width="0.7" opacity="0.5"/>
      <!-- Fenster -->
      <rect x="106" y="14" width="34" height="28" rx="3" fill="#BFE0EA" stroke="#9A7B54" stroke-width="2.5"/>
      <path d="M123 14 L123 42 M106 28 L140 28" stroke="#9A7B54" stroke-width="1.6"/>
      <!-- Bild an der Wand -->
      <rect x="200" y="14" width="28" height="21" rx="2" fill="#DCC6A0" stroke="#9A7B54" stroke-width="2"/>
      <path d="M203 31 L210 22 L216 28 L221 20 L225 31 Z" fill="#8FBF86"/>
      ${k.hinten ? katze : ""}
      <!-- Fernseher LINKS auf einem niedrigen Sideboard -->
      <rect x="12" y="96" width="44" height="22" rx="2" fill="#B98A5C"/>
      <rect x="12" y="96" width="44" height="3" fill="#C79A67"/>
      <rect x="15" y="118" width="4" height="4" rx="1" fill="#7E552F"/>
      <rect x="49" y="118" width="4" height="4" rx="1" fill="#7E552F"/>
      <rect x="16" y="64" width="36" height="26" rx="2.5" fill="#3B3A38"/>
      <rect x="19" y="67" width="30" height="20" rx="1.5" fill="#79A8C4"/>
      <path d="M22 84 L30 74 L36 80 L42 71 L47 84 Z" fill="#BBD7E6" opacity="0.8"/>
      <rect x="30" y="90" width="8" height="4" rx="1" fill="#3B3A38"/>
      <rect x="24" y="94" width="20" height="2.5" rx="1.2" fill="#2E2D2B"/>
      <ellipse cx="34" cy="122" rx="26" ry="3" fill="#6B5136" opacity="0.25"/>
      <!-- Stuhl in der Mitte links -->
      <rect x="66" y="76" width="36" height="5" rx="2" fill="#C79A67"/>
      <rect x="66" y="81" width="36" height="2.5" fill="#9A6E43"/>
      <rect x="67" y="42" width="4.5" height="35" rx="2" fill="#A8794F"/>
      <rect x="96" y="42" width="4.5" height="35" rx="2" fill="#A8794F"/>
      <rect x="67" y="46" width="33.5" height="4" rx="2" fill="#B98A5C"/>
      <rect x="67" y="58" width="33.5" height="4" rx="2" fill="#B98A5C"/>
      <rect x="73" y="83" width="3.2" height="37" rx="1.4" fill="#8A6238"/>
      <rect x="93" y="83" width="3.2" height="37" rx="1.4" fill="#8A6238"/>
      <rect x="68" y="83" width="2.8" height="31" rx="1.4" fill="#75522F"/>
      <rect x="98" y="83" width="2.8" height="31" rx="1.4" fill="#75522F"/>
      <ellipse cx="84" cy="120" rx="22" ry="3" fill="#6B5136" opacity="0.28"/>
      <!-- Tisch rechts daneben -->
      <rect x="110" y="66" width="72" height="6" rx="2.5" fill="#C79A67"/>
      <rect x="110" y="72" width="72" height="3" fill="#9A6E43"/>
      <rect x="116" y="75" width="60" height="4" rx="1.5" fill="#AE7F52"/>
      <rect x="118" y="79" width="5" height="43" rx="2" fill="#96683F"/>
      <rect x="169" y="79" width="5" height="43" rx="2" fill="#96683F"/>
      <rect x="126" y="79" width="4" height="36" rx="2" fill="#7E552F"/>
      <rect x="162" y="79" width="4" height="36" rx="2" fill="#7E552F"/>
      <ellipse cx="146" cy="122" rx="38" ry="3.5" fill="#6B5136" opacity="0.28"/>
      ${k.imKorb ? katze : ""}
      <!-- Korb mit Flechtmuster -->
      <path d="M200 96 L238 96 L233 118 L205 118 Z" fill="#C9A15F"/>
      <path d="M201.5 102 H236 M203 109 H234.5" stroke="#A07F45" stroke-width="1.1"/>
      <path d="M199 94 L239 94 L238 97 L200 97 Z" fill="#B08D4E"/>
      <ellipse cx="219" cy="120" rx="20" ry="2.6" fill="#6B5136" opacity="0.25"/>
      ${!k.hinten && !k.imKorb ? katze : ""}
      ${zeigen ? `<text x="140" y="12" text-anchor="middle" font-size="10" font-weight="800" fill="#8A5A3B">${k.key}</text>` : ""}
    </svg>`;
  }
  // Die Katze in drei getrennten Haltungen. Sie werden bewusst NICHT ineinander
  // gerechnet: wer liegt, liegt wirklich (Beine untergeschlagen, Körper flach am
  // Boden), wer sitzt, sitzt auf dem Hinterteil und stützt sich vorn ab, und wer
  // steht, steht auf allen vieren. Anker ist in allen drei Fällen derselbe Punkt
  // (100 / 90), damit die Platzierung im Zimmer unverändert bleibt.
  function kzKatzeSvg(haltung) {
    const FELL = "#8C837B", FELL_HELL = "#A79D94", BAUCH = "#E7DFD6";
    const OHR = "#E2A6AE", AUGE = "#2C2A28", NASE = "#E08B96";
    // Kopf ist für alle Haltungen gleich aufgebaut — nur an anderer Stelle.
    const kopf = (cx, cy, neigung) => `
      <g transform="translate(${cx} ${cy}) rotate(${neigung})">
        <path d="M-6.6 -4 l-1 -6.4 l5.4 3.6 Z" fill="${FELL}"/>
        <path d="M6.6 -4 l1 -6.4 l-5.4 3.6 Z" fill="${FELL}"/>
        <path d="M-5.4 -4.4 l-0.6 -3.8 l3.4 2.2 Z" fill="${OHR}"/>
        <path d="M5.4 -4.4 l0.6 -3.8 l-3.4 2.2 Z" fill="${OHR}"/>
        <ellipse cx="0" cy="0" rx="7.4" ry="6.6" fill="${FELL_HELL}"/>
        <ellipse cx="0" cy="2.4" rx="4.4" ry="3.4" fill="${BAUCH}"/>
        <circle cx="-2.7" cy="-0.6" r="1.7" fill="${AUGE}"/>
        <circle cx="2.7" cy="-0.6" r="1.7" fill="${AUGE}"/>
        <circle cx="-2.2" cy="-1.2" r="0.6" fill="#ffffff"/>
        <circle cx="3.2" cy="-1.2" r="0.6" fill="#ffffff"/>
        <path d="M0 1.6 l-1.3 1.5 h2.6 Z" fill="${NASE}"/>
        <path d="M0 3.1 q-1.6 1.7 -2.9 0.5 M0 3.1 q1.6 1.7 2.9 0.5" stroke="#5C5854" stroke-width="0.6" fill="none" stroke-linecap="round"/>
        <path d="M-4.6 1.4 H-9.4 M-4.6 3 H-9 M4.6 1.4 H9.4 M4.6 3 H9" stroke="#6B6560" stroke-width="0.55" stroke-linecap="round" opacity="0.85"/>
      </g>`;
    if (haltung === "liegen") {
      // Flach am Boden, Beine untergeschlagen (nur die Pfoten schauen vorn heraus),
      // Schwanz lang ausgestreckt, Augen zu Schlitzen — sie ruht.
      return `
        <path d="M84 99 q-11 3 -13 -2 q-1 -3 3 -3 q4 2 10 2 Z" fill="${FELL}"/>
        <ellipse cx="100" cy="99" rx="15" ry="5.6" fill="${FELL}"/>
        <ellipse cx="100" cy="101" rx="13" ry="3.4" fill="${FELL_HELL}"/>
        <ellipse cx="107" cy="103.4" rx="3.4" ry="1.6" fill="${BAUCH}"/>
        <ellipse cx="112" cy="103.4" rx="3.2" ry="1.5" fill="${BAUCH}"/>
        ${kopf(112, 95.5, 6)}
        <path d="M108.6 94.6 q1.6 1 3.2 0 M114.6 94.6 q1.6 1 3.2 0" stroke="${AUGE}" stroke-width="0.9" fill="none" stroke-linecap="round"/>
        <ellipse cx="100" cy="105" rx="17" ry="2.2" fill="#6B5136" opacity="0.22"/>`;
    }
    if (haltung === "stehen") {
      // Auf allen vieren, Rücken waagerecht, Schwanz aufgestellt.
      return `
        <path d="M87 92 q-10 -2 -10 -9 q0 -4 3.6 -3.6 q-1 5 3 6.6 q2.4 1 3.4 2.4 Z" fill="${FELL}"/>
        <ellipse cx="98" cy="92" rx="12.4" ry="6.2" fill="${FELL}"/>
        <path d="M87 94 q11 4.6 22 0 q-4 4.6 -11 4.6 q-7 0 -11 -4.6 Z" fill="${BAUCH}"/>
        <rect x="89.4" y="97" width="3" height="8.4" rx="1.5" fill="${FELL}"/>
        <rect x="94.4" y="97.6" width="2.8" height="7.8" rx="1.4" fill="#7A726B"/>
        <rect x="103" y="97" width="3" height="8.4" rx="1.5" fill="${FELL}"/>
        <rect x="107.6" y="97.6" width="2.8" height="7.8" rx="1.4" fill="#7A726B"/>
        <ellipse cx="90.9" cy="105.6" rx="2.1" ry="1.1" fill="${BAUCH}"/>
        <ellipse cx="104.5" cy="105.6" rx="2.1" ry="1.1" fill="${BAUCH}"/>
        ${kopf(111, 86, 0)}
        <ellipse cx="99" cy="107" rx="15" ry="2" fill="#6B5136" opacity="0.2"/>`;
    }
    // sitzen: Hinterteil breit am Boden, Brust aufgerichtet, Vorderbeine gerade,
    // Schwanz vorn um die Pfoten gelegt.
    return `
      <path d="M92 104 q-11 2 -12 -3 q-1 -4 3 -3.4 q3 3 9 3 Z" fill="${FELL}"/>
      <ellipse cx="98" cy="99" rx="10.6" ry="7.4" fill="${FELL}"/>
      <path d="M100 88 q7 3 7.6 11 q0.4 5 -3.6 6 l-6 0 q-3 -1 -2.6 -6 q0.6 -8 4.6 -11 Z" fill="${FELL_HELL}"/>
      <path d="M101 92 q4.4 3.4 4.6 9.4 q0.2 3 -2.2 3.6 l-3.4 0 q-2 -0.6 -1.8 -3.6 q0.4 -6 2.8 -9.4 Z" fill="${BAUCH}"/>
      <rect x="99" y="99" width="3" height="7" rx="1.5" fill="${FELL_HELL}"/>
      <rect x="103.6" y="99" width="3" height="7" rx="1.5" fill="${FELL_HELL}"/>
      <ellipse cx="100.5" cy="106.2" rx="2.1" ry="1.2" fill="${BAUCH}"/>
      <ellipse cx="105.1" cy="106.2" rx="2.1" ry="1.2" fill="${BAUCH}"/>
      <path d="M96 106.6 q7 -3.6 14 0.4 q-7 2.2 -14 -0.4 Z" fill="${FELL}"/>
      ${kopf(104, 86, 0)}
      <ellipse cx="101" cy="108" rx="13" ry="2" fill="#6B5136" opacity="0.2"/>`;
  }
  function renderKatzenzimmer() {
    const area = document.getElementById("katzenzimmerArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "katzenzimmer_neu", "Wo ist die Katze?", "🐈")) return;
    if (!kzSession) neueKzSession();
    if (kzSession.runde >= kzSession.gesamt) { renderKatzenzimmerErgebnis(); return; }
    if (!kzAktuell) neueKzRunde();
    const satzOffen = kzAktuell.ort.satz.replace("___", `<span class="kz-luecke">${kzZustand === "warten" ? "?" : kzAktuell.ort.key}</span>`);
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Wo ist die Katze?: " + kzAktuell.ort.key)}
        <p class="eyebrow">🐈 WO IST DIE KATZE? · RUNDE ${kzSession.runde + 1} / ${kzSession.gesamt} <span class="subnav-info-icon" data-info="Schau, WO die Katze sitzt, und wähle die Präposition, die genau das beschreibt. Das Bild ist die Aufgabe — nicht die Übersetzung.">ⓘ</span></p>
        ${fortschrittHtml(kzSession.runde, kzSession.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip kz-level-btn ${kzLevel === lvl ? "selected" : ""}" data-kz-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${kzZimmerSvg(kzAktuell.ort, kzZustand !== "warten")}
        <p class="kz-satz">${satzOffen}</p>
        <div class="kz-optionen">
          ${kzAktuell.optionen.map((o) => `<button type="button" class="kz-option" data-kz-opt="${o}">${o}</button>`).join("")}
        </div>
        <p class="empty-note kz-feedback" id="kzFeedback">Wo sitzt die Katze?</p>
        <p class="empty-note" style="margin-top:10px; font-size:0.7rem;">Runden: ${Object.entries(KZ_RUNDEN).map(([k, v]) => `<button type="button" class="wsm-diff-btn ${kzSchwierigkeit === k ? "aktiv" : ""}" data-kz-diff="${k}">${k} (${v})</button>`).join(" ")}</p>
      </div>`;
    area.querySelectorAll(".kz-level-btn").forEach((b) => b.addEventListener("click", () => {
      kzLevel = b.dataset.kzLevel; neueKzSession(); neueKzRunde(); renderKatzenzimmer();
    }));
    area.querySelectorAll("[data-kz-diff]").forEach((b) => b.addEventListener("click", () => {
      kzSchwierigkeit = b.dataset.kzDiff; neueKzSession(); neueKzRunde(); renderKatzenzimmer();
    }));
    area.querySelectorAll(".kz-option").forEach((b) => b.addEventListener("click", () => pruefeKatzenzimmer(b)));
  }
  function pruefeKatzenzimmer(btn) {
    if (kzZustand !== "warten") return;
    const richtig = btn.dataset.kzOpt === kzAktuell.ort.key;
    kzSession.runde += 1;
    spielNotiz(richtig, kzAktuell.ort.erkl || kzAktuell.ort.key);
    kzZustand = richtig ? "richtig" : "falsch";
    document.querySelectorAll(".kz-option").forEach((b) => { b.disabled = true; });
    const fb = document.getElementById("kzFeedback");
    if (richtig) {
      kzSession.richtig += 1;
      Core.sound.correct();
      btn.classList.add("kz-treffer");
      fb.innerHTML = `✅ ${kzAktuell.ort.erkl}`;
    } else {
      Core.sound.wrong();
      btn.classList.add("kz-daneben");
      document.querySelectorAll(".kz-option").forEach((b) => { if (b.dataset.kzOpt === kzAktuell.ort.key) b.classList.add("kz-treffer"); });
      fb.innerHTML = `❌ ${kzAktuell.ort.erkl}`;
    }
    const luecke = document.querySelector(".kz-luecke");
    if (luecke) { luecke.textContent = kzAktuell.ort.key; luecke.classList.add("kz-luecke-gefuellt"); }
    setTimeout(() => { neueKzRunde(); renderKatzenzimmer(); }, richtig ? 1800 : 2600);
  }
  function renderKatzenzimmerErgebnis() {
    const area = document.getElementById("katzenzimmerArea");
    const prozent = Math.round((kzSession.richtig / kzSession.gesamt) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: kzSession.richtig, prozent: prozent, tier: "Raumkenner:in",
      charakter: "Wo ist die Katze?", zeilen: [{ name: "🐈 Gefunden", anteil: prozent, wert: kzSession.richtig + "/" + kzSession.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="kzNochmalBtn">🔄 Neue Runde</button>`,
    });
    document.getElementById("kzNochmalBtn").addEventListener("click", () => { neueKzSession(); neueKzRunde(); renderKatzenzimmer(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["katzenzimmer"], points: kzSession.richtig, bonus: 0, percent: prozent, character: "Raumkenner:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-katzenzimmer"]')?.addEventListener("click", () => {
    if (!kzSession) neueKzSession();
    if (!kzAktuell) neueKzRunde();
    renderKatzenzimmer();
  });


  /* ============================================================
     VIER NEUE SPIELE
     ------------------------------------------------------------
     Alle vier schöpfen aus Beständen, die es schon gibt — dem
     Aufgabenspeicher der Übungen und dem Wörterbuch mit Niveau,
     Thema, Artikel und Betonung. Dadurch wachsen sie automatisch
     mit, sobald dort etwas dazukommt.
     ============================================================ */

  // Fragen des aktuellen Lernraums auf einem Niveau — gemeinsame Quelle für die neuen Spiele.
  function fragenFuerNiveau(level, mindestens) {
    const alle = [];
    ExerciseData.activeCategories().forEach((c) => {
      let bank = [];
      try { bank = c.getBank(); } catch (e) { return; }
      bank.forEach((q) => { if (q && q.options && q.options.length >= 2) alle.push({ ...q, categoryId: c.id, catTitle: c.title }); });
    });
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const genau = alle.filter((q) => Quiz.questionLevel(q, q.categoryId) === level);
    if (genau.length >= (mindestens || 1)) return genau;
    const grenze = stufen.indexOf(level);
    for (let d = 1; d < stufen.length; d++) {
      const erweitert = alle.filter((q) => Math.abs(stufen.indexOf(Quiz.questionLevel(q, q.categoryId)) - grenze) <= d);
      if (erweitert.length >= (mindestens || 1)) return erweitert;
    }
    return alle;
  }

  /* ===== 1. BLITZRUNDE — 90 Sekunden, so viele richtige Antworten wie möglich.
     Jede richtige Antwort in Folge erhöht den Multiplikator, ein Fehler setzt ihn
     zurück. Belohnt Sicherheit statt Raten, weil Tempo allein nichts bringt. ===== */
  let blitzLevel = null;
  let blitzSession = null;
  let blitzFrage = null;
  let blitzTimer = null;
  const BLITZ_DAUER = 90;
  function neueBlitzSession() {
    blitzLevel = applyDefaultCefrLevel(blitzLevel, (v) => { blitzLevel = v; }, "blitzrunde");
    blitzSession = { zeit: BLITZ_DAUER, richtig: 0, falsch: 0, serie: 0, besteSerie: 0, punkte: 0, laeuft: false, fertig: false, gestellt: [] };
    blitzFrage = null;
    if (blitzTimer) { clearInterval(blitzTimer); blitzTimer = null; }
  }
  function neueBlitzFrage() {
    const pool = fragenFuerNiveau(blitzLevel, 30);
    const uebrig = pool.filter((q) => !blitzSession.gestellt.includes(q.prompt));
    const quelle = uebrig.length ? uebrig : pool;
    const q = quelle[Math.floor(Math.random() * quelle.length)];
    blitzSession.gestellt.push(q.prompt);
    blitzFrage = q;
  }
  function starteBlitz() {
    blitzSession.laeuft = true;
    neueBlitzFrage();
    if (blitzTimer) clearInterval(blitzTimer);
    blitzTimer = setInterval(() => {
      blitzSession.zeit -= 1;
      const anzeige = document.getElementById("blitzZeit");
      if (anzeige) anzeige.textContent = blitzSession.zeit + " s";
      if (blitzSession.zeit <= 0) {
        clearInterval(blitzTimer); blitzTimer = null;
        blitzSession.laeuft = false; blitzSession.fertig = true;
        Core.sound.fanfare();
        if (Backend.currentUser()) {
          saveResultAndCheck({ categories: ["blitzrunde"], points: blitzSession.punkte, bonus: 0, percent: Math.round((blitzSession.richtig / Math.max(1, blitzSession.richtig + blitzSession.falsch)) * 100), character: "Blitzdenker:in", badges: [], playedAt: new Date().toISOString() });
        }
        renderBlitzrunde();
      }
    }, 1000);
    renderBlitzrunde();
  }
  function renderBlitzrunde() {
    const area = document.getElementById("blitzrundeArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "blitzrunde_neu", "Blitzrunde", "⚡")) return;
    if (!blitzSession) neueBlitzSession();
    if (blitzSession.fertig) {
      const genauigkeit = Math.round((blitzSession.richtig / Math.max(1, blitzSession.richtig + blitzSession.falsch)) * 100);
      area.innerHTML = `
        <div class="question-card" style="text-align:center;">
          <p class="eyebrow">⚡ BLITZRUNDE — ZEIT UM</p>
          <h2 style="margin:10px 0;">${blitzSession.punkte} Punkte</h2>
          <p>${blitzSession.richtig} richtig · ${blitzSession.falsch} falsch · ${genauigkeit}% Trefferquote</p>
          <p class="empty-note">Längste Serie ohne Fehler: <strong>${blitzSession.besteSerie}</strong></p>
          <p class="empty-note" style="margin-top:8px;">${blitzSession.besteSerie >= 10 ? "Das war sicher gespielt — nicht geraten." : "Tipp: Der Multiplikator wächst nur, solange du keinen Fehler machst. Ruhig lesen lohnt sich mehr als schnell tippen."}</p>
          <button type="button" class="btn btn-ghost" data-zur-auswertung="1" style="margin-top:14px;">✉️ Ergebnis im Postfach</button>
          <button type="button" class="btn btn-coffee" id="blitzNochmal" style="margin-top:14px;">🔄 Neue Runde</button>
        </div>`;
      document.getElementById("blitzNochmal").addEventListener("click", () => { neueBlitzSession(); renderBlitzrunde(); });
      return;
    }
    if (!blitzSession.laeuft) {
      area.innerHTML = `
        <div class="question-card" style="text-align:center;">
          <p class="eyebrow">⚡ BLITZRUNDE</p>
          <p class="empty-note" style="margin:8px 0 12px;">${BLITZ_DAUER} Sekunden, so viele richtige Antworten wie möglich. Jede richtige Antwort in Folge erhöht den Multiplikator (×1, ×2, ×3 …), ein Fehler setzt ihn auf ×1 zurück. Raten lohnt sich also nicht.</p>
          <div class="trophy-case wsm-chips" style="justify-content:center;">
            ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip blitz-level-btn ${blitzLevel === lvl ? "selected" : ""}" data-blitz-level="${lvl}">${lvl}</button>`).join("")}
          </div>
          <button type="button" class="btn btn-coffee" id="blitzStart" style="margin-top:14px;">▶ Los geht's</button>
        </div>`;
      area.querySelectorAll(".blitz-level-btn").forEach((b) => b.addEventListener("click", () => { blitzLevel = b.dataset.blitzLevel; renderBlitzrunde(); }));
      document.getElementById("blitzStart").addEventListener("click", starteBlitz);
      return;
    }
    const q = blitzFrage;
    const multi = 1 + Math.floor(blitzSession.serie / 3);
    area.innerHTML = `
      <div class="question-card">
        <div class="question-meta"><span class="cat-tag">${q.catTitle}</span> · ⏱️ <strong id="blitzZeit">${blitzSession.zeit} s</strong> · ${blitzSession.punkte} Punkte · Multiplikator ×${multi}</div>
        ${fortschrittHtml(blitzSession.zeit, BLITZ_DAUER)}
        <div class="question-prompt" style="margin-top:10px;">${q.prompt.replace("___", '<span class="blank-slot">___</span>')}</div>
        <div class="option-list">
          ${q.options.map((opt, i) => `<button type="button" class="option-btn blitz-opt" data-idx="${i}"><span>${opt}</span></button>`).join("")}
        </div>
        <p class="empty-note" style="margin-top:8px;">Serie: ${blitzSession.serie} richtig in Folge${blitzSession.serie >= 3 ? " — Multiplikator aktiv!" : ""}</p>
      </div>`;
    area.querySelectorAll(".blitz-opt").forEach((b) => b.addEventListener("click", () => {
      const richtig = q.correct.includes(Number(b.dataset.idx));
      spielNotiz(richtig, `${q.prompt} → ${q.options[q.correct[0]]}`);
      if (richtig) {
        blitzSession.richtig += 1;
        blitzSession.serie += 1;
        blitzSession.besteSerie = Math.max(blitzSession.besteSerie, blitzSession.serie);
        blitzSession.punkte += 1 + Math.floor((blitzSession.serie - 1) / 3);
        Core.sound.correct();
      } else {
        blitzSession.falsch += 1;
        blitzSession.serie = 0;
        Core.sound.wrong();
      }
      neueBlitzFrage();
      renderBlitzrunde();
    }));
  }

  /* ===== 2. WORTANGLER — Wörter treiben vorbei, gefangen werden darf nur, was zur
     Regel passt (ein bestimmter Artikel, ein Thema oder ein Niveau). Trainiert das
     schnelle Erkennen von Genus und Sachgebiet statt reinem Vokabelabfragen. ===== */
  let anglerLevel = null;
  let anglerSession = null;
  const ANGLER_RUNDEN = 12;
  function anglerWortpool() {
    return buildDictionaryEntries().filter((e) => e.verified && e.level && e.meaning);
  }
  function neueAnglerSession() {
    anglerLevel = applyDefaultCefrLevel(anglerLevel, (v) => { anglerLevel = v; }, "wortangler");
    anglerSession = { runde: 0, gesamt: ANGLER_RUNDEN, richtig: 0, verpasst: 0, falsch: 0, regel: null, teich: [] };
    neueAnglerRunde();
  }
  function neueAnglerRunde() {
    const pool = anglerWortpool().filter((e) => e.level === anglerLevel);
    const quelle = pool.length >= 12 ? pool : anglerWortpool();
    // Regelarten: nach Artikel oder nach Themenbereich.
    /* Im Lernraum Italienisch gibt es kein der/die/das — dort fände die
       Artikelregel nie einen Fisch, und die Runde bliebe leer. */
    const artikel = imItalienischraum() ? ["il", "lo", "la", "i", "gli", "le"] : ["der", "die", "das"];
    const themen = [...new Set(quelle.map((e) => e.category))].filter(Boolean);
    const nachArtikel = Math.random() < 0.5;
    let regel, passt;
    if (nachArtikel) {
      const a = artikel[Math.floor(Math.random() * artikel.length)];
      regel = { text: `Fang alle Wörter mit „${a}“`, kurz: a };
      passt = (e) => e.word.toLowerCase().startsWith(a + " ");
    } else {
      const t = themen[Math.floor(Math.random() * themen.length)];
      regel = { text: `Fang alle Wörter zum Thema „${t}“`, kurz: t };
      passt = (e) => e.category === t;
    }
    const treffer = Core.shuffle(quelle.filter(passt)).slice(0, 3);
    const nieten = Core.shuffle(quelle.filter((e) => !passt(e))).slice(0, 5);
    if (!treffer.length) { anglerSession.regel = null; return; }
    anglerSession.regel = regel;
    anglerSession.passt = passt;
    anglerSession.teich = Core.shuffle([...treffer, ...nieten]).map((e) => ({ ...e, gefangen: false }));
    anglerSession.zuFangen = treffer.length;
  }
  function renderWortangler() {
    const area = document.getElementById("wortanglerArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "wortangler_neu", "Wortangler", "🎣")) return;
    if (!anglerSession) neueAnglerSession();
    if (anglerSession.runde >= anglerSession.gesamt) { renderWortanglerErgebnis(); return; }
    if (!anglerSession.regel) { neueAnglerRunde(); }
    const s = anglerSession;
    const gefangen = s.teich.filter((e) => e.gefangen && s.passt(e)).length;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Wortangler: " + s.regel.text)}
        <p class="eyebrow">🎣 WORTANGLER · RUNDE ${s.runde + 1} / ${s.gesamt} <span class="subnav-info-icon" data-info="Im Teich schwimmen Wörter. Tippe genau die an, die zur Regel oben passen — die anderen lässt du schwimmen. Alle Wörter kommen aus dem Wörterbuch der Seite.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip angler-level-btn ${anglerLevel === lvl ? "selected" : ""}" data-angler-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        <p style="font-weight:800; font-size:1.05rem; margin:10px 0 4px;">${s.regel.text}</p>
        <p class="empty-note" style="margin:0 0 10px;">${gefangen} von ${s.zuFangen} gefangen</p>
        <div class="angler-teich">
          ${s.teich.map((e, i) => `
            <button type="button" class="angler-fisch ${e.gefangen ? (s.passt(e) ? "angler-treffer" : "angler-niete") : ""}" data-angler="${i}" ${e.gefangen ? "disabled" : ""}>
              <span class="angler-wort">${e.word}</span>
              <span class="angler-bedeutung">${e.meaning}</span>
            </button>`).join("")}
        </div>
        <button type="button" class="btn btn-ghost" id="anglerWeiter" style="margin-top:12px;">Runde beenden ▸</button>
      </div>`;
    area.querySelectorAll(".angler-level-btn").forEach((b) => b.addEventListener("click", () => { anglerLevel = b.dataset.anglerLevel; neueAnglerSession(); renderWortangler(); }));
    area.querySelectorAll("[data-angler]").forEach((b) => b.addEventListener("click", () => {
      const e = s.teich[Number(b.dataset.angler)];
      e.gefangen = true;
      const passt = s.passt(e);
      spielNotiz(passt, `${e.word} — ${e.meaning}`);
      if (passt) { s.richtig += 1; Core.sound.correct(); } else { s.falsch += 1; Core.sound.wrong(); }
      renderWortangler();
    }));
    document.getElementById("anglerWeiter").addEventListener("click", () => {
      s.verpasst += s.teich.filter((e) => !e.gefangen && s.passt(e)).length;
      s.runde += 1;
      if (s.runde < s.gesamt) neueAnglerRunde();
      renderWortangler();
    });
  }
  function renderWortanglerErgebnis() {
    const area = document.getElementById("wortanglerArea");
    const s = anglerSession;
    const punkte = Math.max(0, s.richtig * 2 - s.falsch);
    const prozent = Math.round((s.richtig / Math.max(1, s.richtig + s.falsch + s.verpasst)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: punkte, prozent: prozent, tier: "Wortangler:in",
      charakter: "Wortangler", zeilen: [{ name: "🎣 Richtig gefangen", anteil: prozent, wert: String(s.richtig) }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="anglerNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("anglerNochmal").addEventListener("click", () => { neueAnglerSession(); renderWortangler(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["wortangler"], points: punkte, bonus: 0, percent: prozent, character: "Wortangler:in", badges: [], playedAt: new Date().toISOString() });
    }
  }

  /* ===== 3. WORTLEITER — von A1 nach C2 klettern. Auf jeder Stufe drei Aufgaben
     dieses Niveaus; wer sie schafft, steigt auf. Das macht den Fortschritt sichtbar
     und gibt dem Üben eine Richtung, statt nur Einzelrunden zu spielen. ===== */
  let leiterSession = null;
  const LEITER_STUFEN = ["A1", "A2", "B1", "B2", "C1", "C2"];
  const LEITER_PRO_STUFE = 3;
  function neueLeiterSession() {
    leiterSession = { stufe: 0, richtigAufStufe: 0, fehlerAufStufe: 0, gesamtRichtig: 0, geschafft: [], fertig: false, frage: null, gestellt: [] };
    neueLeiterFrage();
  }
  function neueLeiterFrage() {
    const level = LEITER_STUFEN[leiterSession.stufe];
    const pool = fragenFuerNiveau(level, 10);
    const uebrig = pool.filter((q) => !leiterSession.gestellt.includes(q.prompt));
    const quelle = uebrig.length ? uebrig : pool;
    const q = quelle[Math.floor(Math.random() * quelle.length)];
    leiterSession.gestellt.push(q.prompt);
    leiterSession.frage = q;
  }
  function leiterSvg(stufe, geschafft) {
    const hoehe = 150;
    return `
      <svg viewBox="0 0 90 ${hoehe}" width="70" style="display:block; margin:0 auto;" aria-hidden="true">
        <rect x="28" y="8" width="5" height="${hoehe - 16}" rx="2" fill="#A8794F"/>
        <rect x="57" y="8" width="5" height="${hoehe - 16}" rx="2" fill="#A8794F"/>
        ${LEITER_STUFEN.map((lvl, i) => {
          const y = hoehe - 20 - i * 22;
          const erledigt = geschafft.includes(lvl);
          const aktuell = i === stufe;
          return `<rect x="28" y="${y}" width="34" height="5" rx="2" fill="${erledigt ? "#57C7AE" : aktuell ? "#F2B84B" : "#C9A98A"}"/>
                  <text x="14" y="${y + 5}" font-size="9" font-weight="800" fill="${erledigt ? "#57C7AE" : aktuell ? "#F2B84B" : "#B49B80"}">${lvl}</text>
                  ${erledigt ? `<text x="68" y="${y + 5}" font-size="9">✓</text>` : ""}`;
        }).join("")}
      </svg>`;
  }
  function renderWortleiter() {
    const area = document.getElementById("wortleiterArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "wortleiter_neu", "Wortleiter", "🧗")) return;
    if (!leiterSession) neueLeiterSession();
    const s = leiterSession;
    if (s.fertig) {
      area.innerHTML = `
        <div class="question-card" style="text-align:center;">
          <p class="eyebrow">🧗 WORTLEITER — OBEN ANGEKOMMEN</p>
          ${leiterSvg(LEITER_STUFEN.length - 1, s.geschafft)}
          <h2 style="margin:10px 0;">${s.geschafft.length} von ${LEITER_STUFEN.length} Stufen</h2>
          <p class="empty-note">${s.geschafft.length === LEITER_STUFEN.length ? "Von A1 bis C2 durchgeklettert — das schafft nicht jede und jeder." : `Bis ${s.geschafft[s.geschafft.length - 1] || "A1"} bist du gekommen. Beim nächsten Mal weiter.`}</p>
          <button type="button" class="btn btn-ghost" data-zur-auswertung="1" style="margin-top:14px;">✉️ Ergebnis im Postfach</button>
          <button type="button" class="btn btn-coffee" id="leiterNochmal" style="margin-top:14px;">🔄 Von vorn</button>
        </div>`;
      document.getElementById("leiterNochmal").addEventListener("click", () => { neueLeiterSession(); renderWortleiter(); });
      if (Backend.currentUser()) {
        saveResultAndCheck({ categories: ["wortleiter"], points: s.gesamtRichtig * 3, bonus: s.geschafft.length === LEITER_STUFEN.length ? 20 : 0, percent: Math.round((s.geschafft.length / LEITER_STUFEN.length) * 100), character: "Aufsteiger:in", badges: [], playedAt: new Date().toISOString() });
      }
      return;
    }
    const level = LEITER_STUFEN[s.stufe];
    const q = s.frage;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Wortleiter " + level + ": " + q.prompt)}
        <p class="eyebrow">🧗 WORTLEITER · STUFE ${level} <span class="subnav-info-icon" data-info="Auf jeder Stufe warten drei Aufgaben dieses Niveaus. Schaffst du sie, geht es eine Stufe höher — bis hinauf nach C2. Zwei Fehler auf derselben Stufe beenden den Aufstieg.">ⓘ</span></p>
        ${fortschrittHtml(s.geschafft.length, LEITER_STUFEN.length)}
        <div style="display:flex; gap:14px; align-items:center;">
          ${leiterSvg(s.stufe, s.geschafft)}
          <div style="flex:1; min-width:0;">
            <p class="empty-note" style="margin:0 0 6px;">${s.richtigAufStufe} von ${LEITER_PRO_STUFE} richtig · ${2 - s.fehlerAufStufe} Fehler übrig</p>
            <div class="question-prompt">${q.prompt.replace("___", '<span class="blank-slot">___</span>')}</div>
          </div>
        </div>
        <div class="option-list" style="margin-top:10px;">
          ${q.options.map((opt, i) => `<button type="button" class="option-btn leiter-opt" data-idx="${i}"><span>${opt}</span></button>`).join("")}
        </div>
        <p class="empty-note" id="leiterFeedback" style="margin-top:8px;">${q.catTitle}</p>
      </div>`;
    area.querySelectorAll(".leiter-opt").forEach((b) => b.addEventListener("click", () => {
      const richtig = q.correct.includes(Number(b.dataset.idx));
      const box = document.getElementById("leiterFeedback");
      if (richtig) {
        s.richtigAufStufe += 1; s.gesamtRichtig += 1;
        Core.sound.correct();
        if (s.richtigAufStufe >= LEITER_PRO_STUFE) {
          s.geschafft.push(level);
          s.stufe += 1; s.richtigAufStufe = 0; s.fehlerAufStufe = 0;
          if (s.stufe >= LEITER_STUFEN.length) { s.fertig = true; Core.sound.fanfare(); }
          else { Core.sound.okay(); showToast(`🧗 Stufe ${level} geschafft — weiter auf ${LEITER_STUFEN[s.stufe]}!`); }
        }
      } else {
        s.fehlerAufStufe += 1;
        Core.sound.wrong();
        if (box) box.textContent = q.explain || "Nicht ganz.";
        if (s.fehlerAufStufe >= 2) { s.fertig = true; Core.sound.fail(); }
      }
      if (!s.fertig) neueLeiterFrage();
      setTimeout(() => renderWortleiter(), richtig ? 500 : 1600);
    }));
  }

  /* ===== 4. SILBENTURM — ein Wort ist in seine Silben zerfallen und muss in der
     richtigen Reihenfolge wieder aufgebaut werden. Danach wird gefragt, welche Silbe
     betont ist. Nutzt die Silben- und Betonungsangaben aus dem Wörterbuch. ===== */
  let turmLevel = null;
  let turmSession = null;
  const TURM_RUNDEN = 10;
  function turmWortpool() {
    const alle = buildDictionaryEntries().filter((e) => e.verified && e.syl && e.syl.includes("-") && !e.syl.includes(" ") && e.syl.split("-").length >= 2 && e.syl.split("-").length <= 5 && e.level);
    const eigene = wortQuelleFilter("silbenturm", alle);
    return eigene.length >= TURM_RUNDEN ? eigene : alle;
  }
  function neueTurmSession() {
    turmLevel = applyDefaultCefrLevel(turmLevel, (v) => { turmLevel = v; }, "silbenturm");
    turmSession = { runde: 0, gesamt: TURM_RUNDEN, richtig: 0, phase: "bauen", gelegt: [], wort: null, gespielt: [] };
    neueTurmRunde();
  }
  function neueTurmRunde() {
    const pool = turmWortpool();
    const passend = pool.filter((e) => e.level === turmLevel && !turmSession.gespielt.includes(e.word));
    const quelle = passend.length ? passend : pool.filter((e) => !turmSession.gespielt.includes(e.word));
    if (!quelle.length) { turmSession.runde = turmSession.gesamt; return; }
    const e = quelle[Math.floor(Math.random() * quelle.length)];
    turmSession.gespielt.push(e.word);
    const silben = e.syl.split("-");
    turmSession.wort = { ...e, silben, betontIdx: Core.betonteSilbenIndex(silben) };
    turmSession.gelegt = [];
    turmSession.vorrat = Core.shuffle(silben.map((t, i) => ({ t, i })));
    turmSession.phase = "bauen";
  }
  function renderSilbenturm() {
    const area = document.getElementById("silbenturmArea");
    if (!area) return;
    if (!renderComingSoonGate(area, "silbenturm_neu", "Silbenturm", "🧱")) return;
    if (!turmSession) neueTurmSession();
    if (turmSession.runde >= turmSession.gesamt) { renderSilbenturmErgebnis(); return; }
    const s = turmSession;
    const w = s.wort;
    const fertigGebaut = s.gelegt.length === w.silben.length;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Silbenturm: " + w.word)}
        <p class="eyebrow">🧱 SILBENTURM · RUNDE ${s.runde + 1} / ${s.gesamt} <span class="subnav-info-icon" data-info="Ein Wort ist in seine Silben zerfallen. Bau es von unten nach oben wieder zusammen — und sag danach, welche Silbe betont wird.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip turm-level-btn ${turmLevel === lvl ? "selected" : ""}" data-turm-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("silbenturm")}
        <p class="empty-note" style="margin:10px 0 4px;">Bedeutung: ${w.meaning || "—"}</p>
        <div class="silbenturm-bau">
          ${s.gelegt.length ? s.gelegt.map((x) => `<span class="silben-stein ${s.phase === "betonung" && x.i === w.betontIdx ? "" : ""}">${x.t.toLowerCase()}</span>`).join("") : '<span class="empty-note">Noch nichts gelegt</span>'}
        </div>
        ${s.phase === "bauen" ? `
          <p class="empty-note" style="margin:10px 0 4px;">Silben in der richtigen Reihenfolge antippen:</p>
          <div class="silben-vorrat">
            ${s.vorrat.filter((x) => !s.gelegt.includes(x)).map((x, idx) => `<button type="button" class="silben-stein silben-waehlbar" data-turm-silbe="${s.vorrat.indexOf(x)}">${x.t.toLowerCase()}</button>`).join("")}
          </div>
          ${s.gelegt.length ? `<button type="button" class="btn btn-ghost" id="turmZurueck" style="margin-top:10px;">↩ Letzte Silbe zurück</button>` : ""}
        ` : `
          <p style="font-weight:800; margin:12px 0 6px;">${w.word} — welche Silbe wird betont?</p>
          <div class="silben-vorrat">
            ${w.silben.map((t, i) => `<button type="button" class="silben-stein silben-waehlbar" data-turm-betonung="${i}">${t.toLowerCase()}</button>`).join("")}
          </div>
        `}
        <p class="empty-note" id="turmFeedback" style="margin-top:10px;">${fertigGebaut && s.phase === "bauen" ? "Der Turm steht — gleich geht es weiter." : ""}</p>
      </div>`;
    area.querySelectorAll(".turm-level-btn").forEach((b) => b.addEventListener("click", () => { turmLevel = b.dataset.turmLevel; neueTurmSession(); renderSilbenturm(); }));
    wortQuelleBinden(area, "silbenturm", () => { neueTurmSession(); renderSilbenturm(); });
    area.querySelectorAll("[data-turm-silbe]").forEach((b) => b.addEventListener("click", () => {
      const x = s.vorrat[Number(b.dataset.turmSilbe)];
      const naechsteRichtige = s.gelegt.length;
      if (x.i === naechsteRichtige) {
        s.gelegt.push(x);
        Core.sound.correct();
        if (s.gelegt.length === w.silben.length) s.phase = "betonung";
      } else {
        Core.sound.wrong();
        const box = document.getElementById("turmFeedback");
        if (box) box.textContent = "Diese Silbe kommt später — welche steht ganz vorn?";
        return;
      }
      renderSilbenturm();
    }));
    document.getElementById("turmZurueck")?.addEventListener("click", () => { s.gelegt.pop(); renderSilbenturm(); });
    area.querySelectorAll("[data-turm-betonung]").forEach((b) => b.addEventListener("click", () => {
      const gewaehlt = Number(b.dataset.turmBetonung);
      const box = document.getElementById("turmFeedback");
      spielNotiz(gewaehlt === w.betontIdx, `${w.wort || w.word || w.syl} — betont: ${w.silben[w.betontIdx] || "?"}`);
      if (gewaehlt === w.betontIdx) {
        s.richtig += 1;
        Core.sound.fanfare();
        if (box) box.textContent = "Richtig betont!";
      } else {
        Core.sound.wrong();
        if (box) box.innerHTML = `Betont wird <strong>${w.silben[w.betontIdx] ? w.silben[w.betontIdx].toLowerCase() : "?"}</strong> — ${betonungAnzeigen(w.syl)}`;
      }
      s.runde += 1;
      setTimeout(() => { if (s.runde < s.gesamt) neueTurmRunde(); renderSilbenturm(); }, 1600);
    }));
  }
  function renderSilbenturmErgebnis() {
    const area = document.getElementById("silbenturmArea");
    const s = turmSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.gesamt)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig * 2, prozent: prozent, tier: "Silbenbaumeister:in",
      charakter: "Silbenturm", zeilen: [{ name: "🧱 Richtig betont", anteil: prozent, wert: s.richtig + "/" + s.gesamt }],
      knoepfe: `<button type="button" class="btn btn-coffee" id="turmNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("turmNochmal").addEventListener("click", () => { neueTurmSession(); renderSilbenturm(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["silbenturm"], points: s.richtig * 2, bonus: 0, percent: prozent, character: "Silbenbaumeister:in", badges: [], playedAt: new Date().toISOString() });
    }
  }

  document.querySelector('#learnSubnav [data-sub="sub-blitzrunde"]')?.addEventListener("click", () => renderBlitzrunde());
  document.querySelector('#learnSubnav [data-sub="sub-wortangler"]')?.addEventListener("click", () => renderWortangler());
  document.querySelector('#learnSubnav [data-sub="sub-wortleiter"]')?.addEventListener("click", () => renderWortleiter());
  document.querySelector('#learnSubnav [data-sub="sub-silbenturm"]')?.addEventListener("click", () => renderSilbenturm());


  /* ============================================================
     DER FUCHS AM FLUSS — ein Spiel mit einer Figur, die sich bewegt
     ------------------------------------------------------------
     Die 22 vorhandenen Spiele stellen im Kern alle dieselbe Sorte
     Frage: hier ist EIN Wort, sag etwas darüber. Dieses hier fragt
     andersherum. Für eine ganze Überquerung gilt EINE Regel — „nur
     der-Wörter", „nur Wörter, die auf der ersten Silbe betont werden",
     „nur Wörter aus Essen & Trinken" — und aus drei Steinen muss jedes
     Mal der eine gewählt werden, auf den die Regel passt. Man prüft
     also nicht ein Wort für sich, sondern siebt Wörter gegeneinander.
     Das ist die Bewegung, die man beim Lesen wirklich braucht.

     Der Fuchs ist dabei keine Verzierung. Er steht sichtbar auf dem
     Stein, den man zuletzt getroffen hat, und man sieht am Bild, wie
     weit man ist, ohne eine Zahl zu lesen. Gezeichnet ist er hier im
     Quelltext und nicht als Bilddatei abgelegt: die Dateien werden vom
     Telefon aus von Hand hochgeladen, und ein Spiel, das drei neue
     Bilder braucht, wäre genau deshalb keins geworden.

     Drei Fehler in einer Überquerung, und der Fuchs sitzt im Wasser —
     die Überquerung ist verloren, die Runde aber nicht: die nächste
     beginnt mit einer neuen Regel. Vier Überquerungen ergeben eine
     Runde. So endet ein Fehler nicht das ganze Spiel, kostet aber
     etwas.
     ============================================================ */
  let flussLevel = null;
  let flussSession = null;
  const FLUSS_STEINE = 5;           // Steine je Überquerung
  const FLUSS_UEBERQUERUNGEN = 4;   // Überquerungen je Runde
  const FLUSS_LEBEN = 3;            // Fehltritte je Überquerung

  function flussOhneArtikel(wort) { return String(wort).replace(/^(der|die|das)\s+/i, ""); }
  function flussArtikel(wort) {
    const m = String(wort).match(/^(der|die|das)\s+/i);
    return m ? m[1].toLowerCase() : "";
  }
  function flussSilben(e) { return String(e.syl || "").split("-").filter(Boolean); }
  // Zwei Sammelfächer, die kein Wortfeld sind: „Sonstiges“ ist die Restkiste,
  // „Grundwörter & Struktur“ ein Grammatikfach. Beide taugen weder als
  // gesuchtes Thema noch als Gegenprobe — was dort steht, kann niemand am
  // Wort ablesen.
  const FLUSS_KEIN_WORTFELD = new Set(["Sonstiges", "Grundwörter & Struktur"]);
  const FLUSS_ORDNUNGSZAHL = ["ersten", "zweiten", "dritten", "vierten", "fünften", "sechsten"];

  /* Nur Wörter, die auf einen Stein passen: geprüfte Einträge mit Niveau,
     ohne Leerzeichen und Bindestrich (mehrteilige Stichwörter wie „Erste
     Hilfe" würden den Stein sprengen) und nicht länger als 15 Zeichen. */
  function flussPool() {
    return buildDictionaryEntries().filter((e) => {
      if (!e || !e.verified || !e.word || !e.syl || !e.level) return false;
      const nackt = flussOhneArtikel(e.word);
      return nackt.length >= 3 && nackt.length <= 15 && !/[\s-]/.test(nackt);
    });
  }

  /* Die Regeln. Jede sagt drei Dinge: was auf dem Stein stehen darf
     (passt), was daneben liegen soll (gegen — bewusst KEIN Zufallswort,
     sondern ein knapper Fehlschlag: bei „der-Wörter" liegen die-/das-
     Wörter daneben, nicht Verben), und wie der Fehltritt erklärt wird.
     `ohneArtikel` blendet den Artikel auf dem Stein aus — sonst stünde
     die Antwort bei den Artikelregeln mit auf dem Stein. */
  function flussRegelnFuer(pool) {
    const regeln = [];
    ["der", "die", "das"].forEach((a) => regeln.push({
      id: "artikel-" + a,
      text: `Nur Steine mit <strong>${a}</strong>-Wörtern`,
      hinweis: "Alle drei sind Nomen — nur eines hat diesen Artikel.",
      ohneArtikel: true,
      passt: (e) => flussArtikel(e.word) === a,
      gegen: (e) => { const b = flussArtikel(e.word); return Boolean(b) && b !== a; },
      erklaerung: (e) => `Es heißt <strong>${e.word}</strong>.`,
    }));
    regeln.push({
      id: "betonung-erste",
      text: "Nur Wörter, die auf der <strong>ersten Silbe</strong> betont werden",
      hinweis: "Sprich die Wörter leise mit — wo liegt der Druck?",
      passt: (e) => flussSilben(e).length >= 2 && Core.betonteSilbenIndex(flussSilben(e)) === 0,
      gegen: (e) => flussSilben(e).length >= 2 && Core.betonteSilbenIndex(flussSilben(e)) > 0,
      erklaerung: (e) => `${betonungAnzeigen(e.syl)} — der Druck liegt auf der ${FLUSS_ORDNUNGSZAHL[Core.betonteSilbenIndex(flussSilben(e))] || "letzten"} Silbe.`,
    });
    regeln.push({
      id: "betonung-spaeter",
      text: "Nur Wörter, die <strong>nicht</strong> auf der ersten Silbe betont werden",
      hinweis: "Zwei fangen betont an — eines nicht.",
      passt: (e) => flussSilben(e).length >= 2 && Core.betonteSilbenIndex(flussSilben(e)) > 0,
      gegen: (e) => flussSilben(e).length >= 2 && Core.betonteSilbenIndex(flussSilben(e)) === 0,
      erklaerung: (e) => `${betonungAnzeigen(e.syl)} — der Druck liegt auf der ${FLUSS_ORDNUNGSZAHL[Core.betonteSilbenIndex(flussSilben(e))] || "letzten"} Silbe.`,
    });
    regeln.push({
      id: "silben-zwei",
      text: "Nur Wörter mit <strong>genau zwei Silben</strong>",
      hinweis: "Klatsch die Wörter im Kopf mit.",
      passt: (e) => flussSilben(e).length === 2,
      gegen: (e) => flussSilben(e).length >= 3,
      erklaerung: (e) => `${flussSilbenSchrift(e)} — das sind ${flussSilben(e).length} Silben.`,
    });
    regeln.push({
      id: "silben-viele",
      text: "Nur Wörter mit <strong>drei oder mehr Silben</strong>",
      hinweis: "Klatsch die Wörter im Kopf mit.",
      passt: (e) => flussSilben(e).length >= 3,
      gegen: (e) => flussSilben(e).length === 2,
      erklaerung: (e) => `${flussSilbenSchrift(e)} — das sind ${flussSilben(e).length} Silben.`,
    });
    /* Themenregeln: nicht alle 25 auf einmal, sonst käme eine Artikel-
       oder Betonungsregel kaum noch dran. Drei ausgeloste reichen. */
    const zaehler = {};
    pool.forEach((e) => {
      if (e.category && !FLUSS_KEIN_WORTFELD.has(e.category) && flussArtikel(e.word)) zaehler[e.category] = (zaehler[e.category] || 0) + 1;
    });
    const brauchbar = Object.keys(zaehler).filter((t) => zaehler[t] >= 25);
    Core.shuffle(brauchbar).slice(0, 3).forEach((t) => regeln.push({
      id: "thema-" + t,
      text: `Nur Wörter aus dem Bereich <strong>${t}</strong>`,
      hinweis: "Was gehört zusammen, was nicht?",
      passt: (e) => e.category === t && Boolean(flussArtikel(e.word)),
      gegen: (e) => e.category !== t && !FLUSS_KEIN_WORTFELD.has(e.category) && Boolean(flussArtikel(e.word)),
      erklaerung: (e) => `„${e.word}“ steht bei „${e.category}“.`,
      loesung: (e) => (e.meaning ? `<strong>${e.word}</strong> — ${e.meaning}` : `<strong>${e.word}</strong> gehört dazu.`),
    }));
    return regeln;
  }

  function neueFlussSession() {
    flussLevel = applyDefaultCefrLevel(flussLevel, (v) => { flussLevel = v; }, "flussfuchs");
    const alle = flussPool();
    // Auf dem gewählten Niveau spielen, solange dort genug Wörter liegen —
    // sonst lieber der ganze Wortschatz als eine leere Reihe.
    const passend = alle.filter((e) => e.level === flussLevel);
    let pool = passend.length >= 200 ? passend : alle;
    /* Eine eigene Wortliste kann hier nur die RICHTIGEN Steine stellen —
       für die Gegenproben braucht es weiterhin den ganzen Wortschatz,
       sonst gäbe es keine drei Steine mehr. */
    const eigene = wortQuelleFilter("flussfuchs", pool);
    if (eigene.length >= 30 && eigene.length < pool.length) pool = eigene.concat(pool.filter((e) => !eigene.includes(e)));
    const regeln = flussRegelnFuer(pool).filter((r) => pool.filter(r.passt).length >= 20 && pool.filter(r.gegen).length >= 20);
    flussSession = {
      pool,
      regelVorrat: Core.shuffle(regeln),
      ueberquerung: 0, gesamt: FLUSS_UEBERQUERUNGEN,
      schritt: 0, leben: FLUSS_LEBEN,
      geschafft: 0, steine: 0, fehler: 0,
      regel: null, poolJa: [], poolNein: [], reihe: [],
      zustand: "warten", letzte: null,
      gespielt: [], fertig: false,
    };
    neueFlussUeberquerung();
  }

  function neueFlussUeberquerung() {
    const s = flussSession;
    if (!s.regelVorrat.length) { s.fertig = true; return; }
    s.regel = s.regelVorrat.shift();
    s.poolJa = s.pool.filter(s.regel.passt);
    s.poolNein = s.pool.filter(s.regel.gegen);
    s.schritt = 0;
    s.leben = FLUSS_LEBEN;
    s.zustand = "warten";
    s.letzte = null;
    neueFlussReihe();
  }

  function neueFlussReihe() {
    const s = flussSession;
    const frei = (e) => !s.gespielt.includes(e.word);
    const treffer = s.poolJa.filter(frei);
    const daneben = s.poolNein.filter(frei);
    if (!treffer.length || daneben.length < 2) { s.schritt = FLUSS_STEINE; s.zustand = "drueben"; return; }
    const richtig = treffer[Math.floor(Math.random() * treffer.length)];
    const falsch = Core.shuffle(daneben).slice(0, 2);
    [richtig].concat(falsch).forEach((e) => s.gespielt.push(e.word));
    s.reihe = Core.shuffle([{ e: richtig, ok: true }].concat(falsch.map((e) => ({ e, ok: false }))));
    s.zustand = "warten";
  }

  /* Ein langes Wort auf einem schmalen Telefon bricht sonst irgendwo:
     „Wanderst / iefel". Die Silbengrenzen stehen im Wörterbuch ohnehin
     schon — also werden sie als weiche Trennstellen (\u00AD) eingesetzt,
     und der Browser trennt an einer Stelle, an der man das Wort auch
     schreiben würde. Die Zuordnung ist mechanisch prüfbar: nimmt man aus
     `syl` die Bindestriche heraus, muss exakt das Wort ohne Artikel
     herauskommen — sonst wird gar nicht getrennt. */
  function flussSilbenTeile(eintrag) {
    const teile = String(eintrag.syl || "").split("-").filter(Boolean);
    const nackt = flussOhneArtikel(eintrag.word);
    if (teile.length < 2 || teile.join("").toLowerCase() !== nackt.toLowerCase()) return null;
    const heraus = [];
    let pos = 0;
    teile.forEach((t) => { heraus.push(nackt.substr(pos, t.length)); pos += t.length; });
    return heraus;
  }
  /* F\u00FCrs Trennen zus\u00E4tzlich: eine Silbe aus einem einzigen Buchstaben
     wird mit der Nachbarsilbe zusammengezogen. \u201EE-lek-tro-mo-tor\u201C ist
     als Silbengliederung richtig, als Trennung am Zeilenende aber
     falsch \u2014 ein einzelner Buchstabe bleibt nicht allein stehen. */
  function flussTrennTeile(eintrag) {
    const teile = flussSilbenTeile(eintrag);
    if (!teile) return null;
    const zusammen = [];
    teile.forEach((t, i) => {
      // Eine kurze Silbe hängt sich an die VORIGE an („Vi-de-o-por-tal“ →
      // „Vi-deo-por-tal“). Nur die allererste hat keine vorige — die zieht
      // stattdessen die folgende zu sich („E-lek-tro“ → „Elek-tro“).
      if (i > 0 && t.length < 2) zusammen[zusammen.length - 1] += t;
      else if (zusammen.length && zusammen[zusammen.length - 1].length < 2) zusammen[zusammen.length - 1] += t;
      else zusammen.push(t);
    });
    return zusammen.length > 1 ? zusammen : null;
  }
  function flussSteinText(eintrag, regel) {
    const teile = flussTrennTeile(eintrag);
    const kern = teile ? teile.join("\u00AD") : flussOhneArtikel(eintrag.word);
    const artikel = flussArtikel(eintrag.word);
    // Bei den Artikelregeln bleibt der Artikel weg — er stünde sonst als
    // Antwort mit auf dem Stein.
    return regel && regel.ohneArtikel ? kern : (artikel ? artikel + " " + kern : kern);
  }
  /* Für die Auflösung: „Wan · der · stie · fel" statt alles klein. */
  function flussSilbenSchrift(eintrag) {
    const teile = flussSilbenTeile(eintrag);
    return teile ? teile.join(" · ") : flussOhneArtikel(eintrag.word);
  }

  /* ------------------------------------------------------------
     DIE FUCHSFIGUR — gezeichnet, nicht als Bilddatei
     ------------------------------------------------------------
     Sie gehört keinem einzelnen Spiel: „Der Fuchs am Fluss“ setzt sie
     auf die Steine, „Die Fuchsuhr“ stellt sie neben das Zifferblatt.
     Deshalb steht sie hier für sich und nicht in einem der beiden.

     Der Fuchs, in drei Haltungen. Sie werden bewusst nicht
     ineinander gerechnet, sondern jede für sich gezeichnet: wer
     sitzt, sitzt wirklich auf dem Hinterteil, wer springt, ist
     gestreckt und hat keinen Boden unter den Pfoten, und wer im
     Wasser liegt, schaut nur noch mit Kopf und Schultern heraus.
     Anker ist in allen drei Fällen derselbe Punkt (0 / 0): der
     Boden unter den Vorderpfoten. Dadurch lässt sich der Fuchs
     ohne Umrechnung auf jeden Stein setzen.
     ------------------------------------------------------------ */
  const FUCHS_FELL = "#E2703A", FUCHS_HELL = "#F3A063", FUCHS_BAUCH = "#FBEFE0";
  const FUCHS_DUNKEL = "#4A3428", FUCHS_AUGE = "#2B2018";
  function fuchsKopfSvg(neigung) {
    return `
      <g transform="rotate(${neigung || 0})">
        <path d="M-6.8 -4.2 l-2.2 -8.4 l7.4 4.8 Z" fill="${FUCHS_FELL}"/>
        <path d="M5.6 -4.8 l1.8 -8.2 l-6.8 5.2 Z" fill="${FUCHS_FELL}"/>
        <path d="M-5.4 -4.6 l-1.3 -5 l4.6 2.9 Z" fill="${FUCHS_DUNKEL}"/>
        <path d="M4.7 -5 l1 -4.9 l-4 3.1 Z" fill="${FUCHS_DUNKEL}"/>
        <ellipse cx="0" cy="0" rx="7.2" ry="6.4" fill="${FUCHS_HELL}"/>
        <path d="M3.4 -1.4 q6.4 1.4 9 3.8 q-2.8 2.8 -9 2.6 Z" fill="${FUCHS_BAUCH}" stroke="#D8B78F" stroke-width="0.5"/>
        <ellipse cx="0.4" cy="2.8" rx="4.8" ry="3.2" fill="${FUCHS_BAUCH}" stroke="#D8B78F" stroke-width="0.4"/>
        <circle cx="12.2" cy="2.3" r="1.6" fill="${FUCHS_AUGE}"/>
        <circle cx="3.6" cy="-1.8" r="1.8" fill="${FUCHS_AUGE}"/>
        <circle cx="4.2" cy="-2.5" r="0.7" fill="#ffffff"/>
        <path d="M-3.4 -1.8 a1.8 1.8 0 0 1 3.4 0.4" stroke="${FUCHS_AUGE}" stroke-width="0.8" fill="none" stroke-linecap="round"/>
      </g>`;
  }
  function fuchsFigurSvg(haltung) {
    if (haltung === "springen") {
      // Gestreckt, leicht aufwärts gedreht, alle vier Läufe angezogen,
      // die Rute fliegt hinterher. Kein Schatten — er hat keinen Boden.
      return `
        <g transform="rotate(-14)">
          <path d="M-8 -12 q-14 -3 -18 -11 q-2 -6 4 -6 q0 8 8 10 q6 2 8 5 Z" fill="${FUCHS_FELL}"/>
          <path d="M-24 -25 q-6 -2 -5 -7 q1 -4 5 -2 q-1 5 2 8 Z" fill="${FUCHS_BAUCH}"/>
          <ellipse cx="0" cy="-13" rx="13" ry="7.6" fill="${FUCHS_FELL}"/>
          <path d="M-9 -9.6 q10 4.6 20 -0.6 q-4 4.6 -10.6 4.6 q-6.4 0 -9.4 -4 Z" fill="${FUCHS_BAUCH}"/>
          <path d="M-7 -8 q-4 3 -7.4 2.6 q2 -3.6 5.4 -5 Z" fill="${FUCHS_DUNKEL}"/>
          <path d="M6 -8.4 q4.6 2.6 8 1.6 q-2.4 -3.6 -6 -4.6 Z" fill="${FUCHS_DUNKEL}"/>
          <g transform="translate(11 -21)">${fuchsKopfSvg(-6)}</g>
        </g>`;
    }
    if (haltung === "nass") {
      // Im Wasser: nur Kopf und Schultern über der Linie, Ohren angelegt,
      // drei Ringe darum. Der Rest ist bewusst nicht gezeichnet — was
      // unter Wasser ist, sieht man nicht.
      return `
        <ellipse cx="4" cy="-1" rx="17" ry="3.4" fill="#2E7FA8" opacity="0.5"/>
        <ellipse cx="4" cy="-1" rx="12" ry="2.2" fill="none" stroke="#BFE6F5" stroke-width="1" opacity="0.9"/>
        <ellipse cx="4" cy="-1" rx="19" ry="4.4" fill="none" stroke="#BFE6F5" stroke-width="0.9" opacity="0.6"/>
        <path d="M-3 -3 q5 -7 12 -6 q6 1 7 6 Z" fill="${FUCHS_FELL}"/>
        <g transform="translate(7 -9)">${fuchsKopfSvg(8)}</g>
        <path d="M-1 -13 q3 -4 7 -3" stroke="#BFE6F5" stroke-width="1.1" fill="none" stroke-linecap="round" opacity="0.8"/>`;
    }
    // sitzen — die Ruhehaltung, in der man ihn fragt, wohin es weitergeht
    return `
      <ellipse cx="2" cy="0.6" rx="15" ry="2.4" fill="#123A4E" opacity="0.22"/>
      <path d="M-6 -8 q-13 -2 -15 -12 q-1.4 -7 5 -6.2 q-1 8.4 6.4 10.4 q5.2 1.6 7 5 Z" fill="${FUCHS_FELL}"/>
      <path d="M-20.4 -22.4 q-5.4 -1.4 -5 -6.4 q0.4 -4 4.6 -2.6 q-1.2 5 2 8 Z" fill="${FUCHS_BAUCH}" stroke="#D8B78F" stroke-width="0.5"/>
      <ellipse cx="-1" cy="-9" rx="9.6" ry="9" fill="${FUCHS_FELL}"/>
      <path d="M1.6 -20 q7.4 3 8.2 12.6 q0.4 4.6 -3.4 5.4 l-6.6 0 q-3 -1 -2.4 -6 q0.8 -9 4.2 -12 Z" fill="${FUCHS_HELL}"/>
      <path d="M2.6 -16 q4.6 3.4 5 9.8 q0.2 3 -2.2 3.6 l-3.6 0 q-2 -0.6 -1.8 -3.6 q0.4 -6.4 2.6 -9.8 Z" fill="${FUCHS_BAUCH}"/>
      <rect x="1.4" y="-8.6" width="3.6" height="8" rx="1.7" fill="${FUCHS_HELL}"/>
      <rect x="6.4" y="-8.6" width="3.6" height="8" rx="1.7" fill="${FUCHS_FELL}"/>
      <rect x="1" y="-3.2" width="4.4" height="3.4" rx="1.5" fill="${FUCHS_DUNKEL}"/>
      <rect x="6" y="-3.2" width="4.4" height="3.4" rx="1.5" fill="${FUCHS_DUNKEL}"/>
      <g transform="translate(7 -23)">${fuchsKopfSvg(0)}</g>`;
  }

  /* Die Szene. Sie ist die Fortschrittsanzeige des Spiels: wie weit der
     Fuchs rechts steht, so weit ist man. Die drei Wörter stehen NICHT
     auf den Steinen, sondern darunter als richtige Knöpfe — auf einem
     schmalen Telefon wäre ein Wort wie „Geschwindigkeit" im Stein nur
     noch ein grauer Streifen. */
  function flussSzeneSvg(s) {
    const H = 118, UFER_L = 44, UFER_R = 256;
    const steinX = (i) => 68 + i * 40;
    const steinY = (i) => 86 + (i % 2 ? -6 : 4);
    const drueben = s.zustand === "drueben";
    const abgesoffen = s.zustand === "abgesoffen";
    const teile = [];
    teile.push(`<rect x="0" y="0" width="300" height="${H}" fill="#CFE9F3"/>`);
    // Ferne Bäume am oberen Rand, damit oben nicht nur leere Fläche steht
    for (let i = 0; i < 9; i++) {
      const bx = 12 + i * 34, bh = 14 + ((i * 7) % 9);
      teile.push(`<path d="M${bx} 46 l${-6} 0 l6 -${bh} l6 ${bh} Z" fill="#5C8F5A" opacity="0.55"/>`);
    }
    teile.push(`<rect x="0" y="40" width="300" height="8" fill="#7FBF5A" opacity="0.5"/>`);
    // Wasser
    teile.push(`<rect x="0" y="46" width="300" height="${H - 46}" fill="#3E96C4"/>`);
    for (let i = 0; i < 7; i++) {
      const wy = 56 + i * 11;
      teile.push(`<path d="M-4 ${wy} q14 -4 28 0 t28 0 t28 0 t28 0 t28 0 t28 0 t28 0 t28 0 t28 0 t28 0 t28 0"`
        + ` stroke="#69B4D9" stroke-width="1.6" fill="none" opacity="0.55"/>`);
    }
    // Ufer links und rechts
    teile.push(`<path d="M0 46 h${UFER_L} q-6 8 -4 18 q2 14 -6 20 q-8 6 -6 20 q2 12 -4 ${H} H0 Z" fill="#79B855"/>`);
    teile.push(`<path d="M0 40 h${UFER_L + 2} q-4 6 -2 10 H0 Z" fill="#8FCB63"/>`);
    teile.push(`<path d="M300 46 h-${300 - UFER_R} q6 8 4 18 q-2 14 6 20 q8 6 6 20 q-2 12 4 ${H} H300 Z" fill="#79B855"/>`);
    teile.push(`<path d="M300 40 h-${300 - UFER_R + 2} q4 6 2 10 H300 Z" fill="#8FCB63"/>`);
    // Das Ziel drüben: ein Bau im Hang mit einer kleinen Fahne davor
    teile.push(`<path d="M272 100 q10 -16 20 0 Z" fill="#3F2E22"/>`);
    teile.push(`<rect x="266" y="58" width="2.4" height="30" rx="1" fill="#8B6446"/>`);
    teile.push(`<path d="M268.4 59 l13 5 l-13 5 Z" fill="${drueben ? "#F2B84B" : "#E2703A"}"/>`);
    // Die fünf Steine: was hinter dem Fuchs liegt, ist fest; was vor ihm
    // liegt, schaut nur halb aus dem Wasser.
    for (let i = 0; i < FLUSS_STEINE; i++) {
      const x = steinX(i), y = steinY(i);
      const fest = i < s.schritt || drueben;
      teile.push(`<ellipse cx="${x}" cy="${y + 5}" rx="19" ry="4.4" fill="#1E5C7C" opacity="${fest ? 0.35 : 0.2}"/>`);
      teile.push(`<ellipse cx="${x}" cy="${y}" rx="18.5" ry="8.6" fill="${fest ? "#9AA3A8" : "#6E93A6"}" opacity="${fest ? 1 : 0.75}"/>`);
      teile.push(`<ellipse cx="${x - 3.5}" cy="${y - 2.6}" rx="10.5" ry="3.6" fill="${fest ? "#C2CBD0" : "#89AABA"}" opacity="${fest ? 1 : 0.7}"/>`);
      if (fest) teile.push(`<path d="M${x - 13} ${y + 2} q6 3 13 2" stroke="#7C868C" stroke-width="1" fill="none" opacity="0.7"/>`);
    }
    // Der Stein, der eben weggebrochen ist: ein Spritzer an seiner Stelle
    if (s.zustand === "falsch" || abgesoffen) {
      const x = steinX(Math.min(s.schritt, FLUSS_STEINE - 1)), y = steinY(Math.min(s.schritt, FLUSS_STEINE - 1));
      teile.push(`<ellipse cx="${x}" cy="${y}" rx="18" ry="6" fill="none" stroke="#DCF1FA" stroke-width="1.8" opacity="0.9"/>`);
      teile.push(`<ellipse cx="${x}" cy="${y}" rx="26" ry="9" fill="none" stroke="#DCF1FA" stroke-width="1.2" opacity="0.55"/>`);
      [-14, -6, 4, 13].forEach((dx, n) => teile.push(
        `<circle cx="${x + dx}" cy="${y - 10 - (n % 2) * 6}" r="${2.6 - (n % 2) * 0.8}" fill="#EAF7FD" opacity="0.9"/>`));
    }
    // Der Fuchs
    let fx, fy, haltung;
    if (abgesoffen) {
      fx = steinX(Math.min(s.schritt, FLUSS_STEINE - 1)); fy = steinY(Math.min(s.schritt, FLUSS_STEINE - 1)) + 4; haltung = "nass";
    } else if (drueben) {
      fx = 278; fy = 96; haltung = "sitzen";
    } else if (s.schritt === 0) {
      fx = 22; fy = 96; haltung = s.zustand === "richtig" ? "springen" : "sitzen";
    } else {
      fx = steinX(s.schritt - 1); fy = steinY(s.schritt - 1) - 7; haltung = s.zustand === "richtig" ? "springen" : "sitzen";
    }
    if (haltung === "springen") { fx += 14; fy -= 16; }
    const groesse = haltung === "nass" ? 1 : 0.86;
    teile.push(`<g transform="translate(${fx} ${fy}) scale(${groesse})">${fuchsFigurSvg(haltung)}</g>`);
    return `<svg class="fluss-szene" viewBox="0 0 300 ${H}" role="img"
      aria-label="Der Fuchs steht auf Stein ${Math.min(s.schritt + 1, FLUSS_STEINE)} von ${FLUSS_STEINE}.">${teile.join("")}</svg>`;
  }

  function renderFlussfuchs() {
    const area = document.getElementById("flussfuchsArea");
    if (!area) return;
    /* Der ganze Wortschatz wird erst beim Wechsel nach „Lernen“ geladen.
       Solange er unterwegs ist, hätte eine Reihe zu wenig Wörter zur
       Auswahl — also lieber kurz warten als eine halbe Reihe zeigen.
       Kein Kreislauf: nach dem Laden ist alleThemenDa() wahr. */
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa()) && flussPool().length < 300) {
      area.innerHTML = `<div class="question-card" style="text-align:center;">
        <p class="eyebrow">🦊 DER FUCHS AM FLUSS</p>
        <p class="empty-note">Der Fuchs sucht sich seine Steine zusammen …</p></div>`;
      wortschatzBereit().then(() => renderFlussfuchs());
      return;
    }
    if (!flussSession) neueFlussSession();
    const s = flussSession;
    if (s.fertig || s.ueberquerung >= s.gesamt) { renderFlussfuchsErgebnis(); return; }
    const r = s.regel;
    const pfoten = "🐾".repeat(s.leben) + "<span style=\"opacity:0.3\">" + "🐾".repeat(FLUSS_LEBEN - s.leben) + "</span>";
    const ruht = s.zustand === "drueben" || s.zustand === "abgesoffen";
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Der Fuchs am Fluss: " + (r ? r.id : "?"))}
        <p class="eyebrow">🦊 DER FUCHS AM FLUSS · ÜBERQUERUNG ${Math.min(s.ueberquerung + 1, s.gesamt)} / ${s.gesamt}
          <span class="subnav-info-icon" data-info="Für die ganze Überquerung gilt eine Regel. Von den drei Steinen trägt nur einer — der, auf den die Regel passt. Drei Fehltritte, und der Fuchs sitzt im Wasser.">ⓘ</span></p>
        ${fortschrittHtml(s.ueberquerung, s.gesamt)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip fluss-level-btn ${flussLevel === lvl ? "selected" : ""}" data-fluss-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("flussfuchs")}
        <p class="fluss-regel">${r ? r.text : ""}</p>
        ${flussSzeneSvg(s)}
        <div class="fluss-pfoten">${ruht ? "" : pfoten + " <span class=\"empty-note\">trockene Pfoten</span>"}</div>
        ${ruht ? "" : `<div class="fluss-steine">
          ${s.reihe.map((x, i) => `<button type="button" class="fluss-stein" data-fluss-stein="${i}"><span>${flussSteinText(x.e, r)}</span></button>`).join("")}
        </div>`}
        <p class="empty-note fluss-hinweis" id="flussHinweis">${r ? r.hinweis : ""}</p>
      </div>`;
    area.querySelectorAll(".fluss-level-btn").forEach((b) => b.addEventListener("click", () => {
      flussLevel = b.dataset.flussLevel; neueFlussSession(); renderFlussfuchs();
    }));
    wortQuelleBinden(area, "flussfuchs", () => { neueFlussSession(); renderFlussfuchs(); });
    area.querySelectorAll("[data-fluss-stein]").forEach((b) => b.addEventListener("click", () => flussSchritt(Number(b.dataset.flussStein), b)));
  }

  function flussSchritt(idx, knopf) {
    const s = flussSession;
    if (s.zustand !== "warten") return;
    const wahl = s.reihe[idx];
    const richtig = wahl.ok;
    const r = s.regel;
    spielNotiz(richtig, `${r.text.replace(/<[^>]+>/g, "")} — ${wahl.e.word}`);
    document.querySelectorAll(".fluss-stein").forEach((b) => { b.disabled = true; });
    const hinweis = document.getElementById("flussHinweis");
    if (richtig) {
      knopf.classList.add("fluss-stein-fest");
      s.steine += 1;
      s.schritt += 1;
      s.zustand = "richtig";
      if (hinweis) hinweis.innerHTML = `✅ ${r.erklaerung(wahl.e)}`;
      if (s.schritt >= FLUSS_STEINE) {
        s.zustand = "drueben";
        s.geschafft += 1;
        Core.sound.fanfare();
      } else {
        Core.sound.correct();
      }
    } else {
      knopf.classList.add("fluss-stein-weg");
      s.fehler += 1;
      s.leben -= 1;
      s.zustand = s.leben <= 0 ? "abgesoffen" : "falsch";
      Core.sound.wrong();
      const treffer = s.reihe.find((x) => x.ok);
      document.querySelectorAll(".fluss-stein").forEach((b, i) => { if (s.reihe[i].ok) b.classList.add("fluss-stein-fest"); });
      const aufloesung = (r.loesung || r.erklaerung)(treffer.e);
      if (hinweis) hinweis.innerHTML = `❌ ${r.erklaerung(wahl.e)}<br>Getragen hätte ${aufloesung}`;
      if (s.leben <= 0) Core.sound.fail();
    }
    // Das Bild sofort nachziehen — der Sprung (oder der Spritzer) ist die
    // eigentliche Rückmeldung, der Text daneben nur die Begründung.
    const szene = document.querySelector("#flussfuchsArea .fluss-szene");
    if (szene) szene.outerHTML = flussSzeneSvg(s);
    const pfotenZeile = document.querySelector("#flussfuchsArea .fluss-pfoten");
    if (pfotenZeile) {
      pfotenZeile.innerHTML = (s.zustand === "drueben" || s.zustand === "abgesoffen") ? ""
        : "🐾".repeat(Math.max(0, s.leben)) + "<span style=\"opacity:0.3\">" + "🐾".repeat(FLUSS_LEBEN - Math.max(0, s.leben))
          + "</span> <span class=\"empty-note\">trockene Pfoten</span>";
    }
    const wartezeit = s.zustand === "drueben" ? 2200 : s.zustand === "abgesoffen" ? 2600 : richtig ? 1100 : 2400;
    setTimeout(() => {
      if (s.zustand === "drueben" || s.zustand === "abgesoffen") {
        s.ueberquerung += 1;
        if (s.ueberquerung >= s.gesamt) { renderFlussfuchsErgebnis(); return; }
        neueFlussUeberquerung();
      } else {
        neueFlussReihe();
      }
      renderFlussfuchs();
    }, wartezeit);
  }

  function renderFlussfuchsErgebnis() {
    const area = document.getElementById("flussfuchsArea");
    const s = flussSession;
    const moeglich = FLUSS_STEINE * s.gesamt;
    const prozent = Math.round((s.steine / Math.max(1, moeglich)) * 100);
    const punkte = s.steine * 2 + s.geschafft * 5;
    area.innerHTML = ergebnisSchirmHtml({
      punkte, prozent, tier: "Flussgänger:in", charakter: "Der Fuchs am Fluss",
      bonus: s.geschafft === s.gesamt ? 10 : 0,
      zeilen: [
        { name: "🦊 Überquerungen", anteil: Math.round((s.geschafft / s.gesamt) * 100), wert: s.geschafft + "/" + s.gesamt },
        { name: "🪨 Sichere Steine", anteil: prozent, wert: s.steine + "/" + moeglich },
      ],
      knoepfe: `<button type="button" class="btn btn-coffee" id="flussNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("flussNochmal")?.addEventListener("click", () => { neueFlussSession(); renderFlussfuchs(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["flussfuchs"], points: punkte, bonus: s.geschafft === s.gesamt ? 10 : 0, percent: prozent, character: "Flussgänger:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-flussfuchs"]')?.addEventListener("click", () => renderFlussfuchs());


  /* ============================================================
     MEINE WORTLISTEN — einen ganzen Stapel Wörter einreichen
     ------------------------------------------------------------
     Gewünscht: nicht Wort für Wort im Wörterbuch den Stern antippen,
     sondern eine fertige Liste einwerfen — das Kapitel aus dem
     Kursbuch, die Wörter für die Prüfung am Freitag, was im
     Sprachkurs an der Tafel stand — und danach in den Spielen genau
     damit üben.

     Zum Format: es gibt bewusst KEINES, an das man sich halten muss.
     Getrennt wird an Zeilen, Kommas und Semikolons; Nummerierungen
     („1. der Tisch") und Aufzählungszeichen fallen weg; steht hinter
     einem Gedankenstrich oder Tabulator eine Übersetzung („der Tisch
     – table"), wird sie abgeschnitten. Artikel darf man weglassen,
     groß oder klein schreiben, und eine Pluralform findet ihren
     Singular. Eine Liste, die man erst umformatieren muss, würde
     niemand einreichen.

     Was die App nicht kennt, wird ehrlich als „nicht gefunden"
     ausgewiesen statt stillschweigend geschluckt — sonst übt man mit
     einer Liste, von der man glaubt, sie sei vollständig.
     ============================================================ */
  let wortlistenPruefung = null;   // Ergebnis der letzten Prüfung
  let wortlistenText = "";
  let wortlisteOffen = null;       // welche gespeicherte Liste gerade bearbeitet wird
  let wortlisteArt = "liste";      // "liste" = Wörter einzeln, "text" = ganze Geschichte
  let wortlisteNachtragText = "";  // Eingabefeld beim Nachtragen
  let wortlisteNachtragPruefung = null;

  /* Was das Wörterbuch nicht kennt, wandert ins Sammelbecken. Läuft im
     Hintergrund und ohne Rückmeldung — es ist eine Nebenwirkung des
     Prüfens, keine Handlung, für die jemand um Erlaubnis gefragt
     werden müsste. Gemeldet wird das Wort, nicht die Person. */
  function wortlueckenMelden(fehlend) {
    if (!fehlend || !fehlend.length || !Backend.currentUser()) return;
    if (!Backend.meldeWortluecken) return;
    Backend.meldeWortluecken(fehlend).catch(() => { /* nicht schlimm */ });
  }

  function wortlisteChipsHtml(gefunden, fehlend, mitEntfernen) {
    return `
      ${gefunden.length ? `<div class="wortliste-treffer">
        ${gefunden.map((g) => {
          const wort = typeof g === "string" ? g : g.wort;
          const stufe = typeof g === "string" ? "" : (g.level || "");
          return `<span class="wortliste-chip wortliste-chip-da">✓ ${wort}${stufe ? ` <span class="wortliste-stufe">${stufe}</span>` : ""}${
            mitEntfernen ? ` <button type="button" class="wortliste-weg" data-wort-weg="${String(wort).replace(/"/g, "&quot;")}" title="Aus der Liste nehmen">✕</button>` : ""
          }</span>`;
        }).join("")}
      </div>` : ""}
      ${fehlend.length ? `<div class="wortliste-treffer" style="margin-top:8px;">
        ${fehlend.map((f) => `<span class="wortliste-chip wortliste-chip-fehlt">✕ ${String(f).replace(/</g, "&lt;")}</span>`).join("")}
      </div>` : ""}`;
  }

  /* ============================================================
     AUS EINEM TEXT EINE WORTLISTE MACHEN
     ------------------------------------------------------------
     Funktionswörter tragen die Grammatik, aber man lernt sie nicht
     als Vokabeln — und in einem Fließtext sind sie in der Überzahl.
     Diese Liste hält sie heraus. Sie ist bewusst kurz und enthält
     nur, was zweifelsfrei Funktionswort ist; alles Fragliche darf
     durch, denn ein Wort zu viel ist harmloser als ein fehlendes.
     ============================================================ */
  const TEXT_FUNKTIONSWOERTER = new Set([
    "der", "die", "das", "den", "dem", "des", "ein", "eine", "einen", "einem", "einer", "eines",
    "und", "oder", "aber", "denn", "sondern", "doch", "sowie",
    "ich", "du", "er", "sie", "es", "wir", "ihr", "mich", "dich", "sich", "uns", "euch",
    "mir", "dir", "ihm", "ihn", "ihnen", "man", "mein", "dein", "sein", "unser", "euer",
    "in", "an", "auf", "aus", "bei", "mit", "nach", "seit", "von", "zu", "zur", "zum", "im", "am",
    "vom", "beim", "ins", "aufs", "durch", "für", "gegen", "ohne", "um", "über", "unter", "vor",
    "hinter", "neben", "zwischen", "bis", "ab", "als", "wie", "so", "auch", "noch", "schon",
    "nur", "nicht", "kein", "keine", "keinen", "sehr", "mehr", "immer", "wieder", "dann", "da",
    "hier", "dort", "wo", "wann", "warum", "was", "wer", "wen", "wem", "welche", "welcher",
    "dass", "weil", "wenn", "ob", "damit", "obwohl", "während", "bevor", "nachdem", "sobald",
    "ist", "sind", "war", "waren", "bin", "bist", "sei", "wäre", "hat", "haben", "hatte",
    "hatten", "habe", "hast", "wird", "werden", "wurde", "wurden", "worden", "kann", "können",
    "konnte", "muss", "müssen", "musste", "soll", "sollen", "sollte", "will", "wollen",
    "wollte", "darf", "dürfen", "durfte", "mag", "möchte", "möchten",
    "dieser", "diese", "dieses", "diesen", "diesem", "jener", "jede", "jeder", "jedes", "jedem",
    "alle", "allen", "alles", "aller", "viele", "vielen", "manche", "einige", "beide",
    "jeden", "jedoch", "solche", "solchen", "welchen", "welches",
    "etwas", "nichts", "jemand", "niemand", "selbst", "sogar", "eben", "gerade", "ja", "nein",
    "zwar", "also", "denn", "halt", "mal", "wohl", "eigentlich", "vielleicht",
    "andere", "anderen", "anderer", "anderes", "anderem", "weiter", "weiteren",
    "ganz", "ganze", "ganzen", "erst", "erste", "ersten", "erster", "erstes",
  ]);

  /* Aus einem Text die lernbaren Wörter ziehen, nach Häufigkeit
     sortiert. Zurück kommt genau die Form, die auch wortlisteEinlesen
     liefert — damit passt das Ergebnis in alles, was es schon gibt. */
  function textAuswerten(text, hoechstens) {
    const roh = String(text || "");
    const woerter = roh.match(/[A-Za-zÄÖÜäöüß][A-Za-zÄÖÜäöüß-]{1,}/g) || [];
    const zaehler = new Map();     // Grundform → { anzahl, eintrag }
    const unbekannt = new Map();   // Wort → Anzahl
    woerter.forEach((wort) => {
      if (wort.length < 3) return;
      if (TEXT_FUNKTIONSWOERTER.has(wort.toLowerCase())) return;
      const treffer = wortNachschlagen(wort);
      /* Ohne Sprachniveau ist es kein vollwertiger Wörterbuch-Eintrag:
         dann fehlen auch Betonung und Beispielsatz, und kein Spiel kann
         damit üben. Solche Treffer zählen wie „nicht gefunden". */
      if (!treffer || !treffer.level) {
        // Nur Wörter, die wie Inhaltswörter aussehen, als Lücke melden.
        if (wort.length >= 4) unbekannt.set(wort, (unbekannt.get(wort) || 0) + 1);
        return;
      }
      const k = treffer.word;
      if (!zaehler.has(k)) zaehler.set(k, { anzahl: 0, eintrag: treffer });
      zaehler.get(k).anzahl += 1;
    });
    /* Nach Häufigkeit: Was in DIESEM Text oft vorkommt, ist das, worum
       es geht. Bei Gleichstand entscheidet das Alphabet, damit
       dieselbe Geschichte immer dieselbe Liste ergibt. */
    const sortiert = [...zaehler.entries()]
      .sort((a, b) => (b[1].anzahl - a[1].anzahl) || a[0].localeCompare(b[0], "de"))
      .slice(0, hoechstens || 60);
    return {
      gefunden: sortiert.map(([wort, v]) => ({
        eingabe: wort, wort, level: v.eintrag.level, thema: v.eintrag.category, anzahl: v.anzahl,
      })),
      fehlend: [...unbekannt.entries()].sort((a, b) => b[1] - a[1]).map(([w]) => w).slice(0, 40),
      gesamt: woerter.length,
      saetze: (roh.match(/[.!?]+/g) || []).length,
    };
  }

  /* ============================================================
     EINEN GANZEN TEXT IN EINE WORTLISTE
     ------------------------------------------------------------
     GEWÜNSCHT: „dass alle wichtigen Wörter aus dem heutigen Beitrag
     in einem Rutsch abgespeichert werden können, in eine Wortliste
     übernommen werden können, und man diese Wörter aus diesem Beitrag
     gezielt lernen kann … und man soll andere auch mit seiner eigenen
     Wortliste herausfordern können."

     Der Knopf steht direkt über dem Lesetext. Er nimmt genau das, was
     dort steht, führt jede gebeugte Form auf ihre Wörterbuchform
     zurück (wortNachschlagen() macht das schon für die Wortlisten) und
     legt daraus eine Liste an — fertig zum Üben und zum Herausfordern.
     ============================================================ */
  function textInListeKnopfHtml(titel) {
    return `<button type="button" class="btn btn-ghost text-in-liste-knopf" data-text-in-liste="${escapeHtml(titel || "")}"
              style="font-size:0.78rem; padding:5px 10px; margin-bottom:8px;">
              📋 Alle Wörter dieses Textes in eine Liste
            </button>`;
  }

  async function textInListe(knopf) {
    if (!Backend.currentUser()) { showToast("Zum Anlegen einer Liste bitte zuerst anmelden."); return; }
    /* Der Text steht im selben Kasten wie der Knopf. Gibt es dort
       mehrere Lesestellen, kommen alle zusammen in die Liste. */
    const kasten = knopf.closest(".question-card") || knopf.parentElement;
    const stellen = kasten ? kasten.querySelectorAll(".sammel-text") : [];
    const text = stellen.length
      ? [...stellen].map((e) => e.textContent).join(" ")
      : (kasten ? kasten.textContent : "");
    if (!text || text.trim().length < 40) { showToast("Hier steht noch kein Text zum Sammeln."); return; }
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa())) {
      showToast("Der Wortschatz wird geladen — gleich noch einmal antippen.");
      wortschatzBereit();
      return;
    }
    const ergebnis = textAuswerten(text, 120);
    if (!ergebnis.gefunden.length) { showToast("In diesem Text war kein Wort aus dem Wörterbuch."); return; }
    const name = (knopf.dataset.textInListe || "Lesetext") + " · " + new Date().toLocaleDateString("de-DE");
    const id = await wortlisteSpeichern(name, ergebnis.gefunden.map((g) => g.wort));
    if (!id) { showToast("Die Liste konnte nicht gespeichert werden."); return; }
    wortlueckenMelden(ergebnis.fehlend);
    showToast(`📋 ${ergebnis.gefunden.length} Wörter in „${name}" — du findest sie unter „Meine Wortlisten".`);
  }

  document.addEventListener("click", (ev) => {
    const knopf = ev.target.closest("[data-text-in-liste]");
    if (!knopf) return;
    ev.preventDefault();
    textInListe(knopf);
  });

  function renderWortlisten() {
    const area = document.getElementById("wortlistenArea");
    if (!area) return;
    if (!Backend.currentUser()) {
      area.innerHTML = `<div class="question-card">
        <p class="eyebrow">📋 MEINE WORTLISTEN</p>
        <p class="empty-note">Wortlisten hängen an deinem Konto, damit sie auf jedem Gerät da sind. Dafür musst du angemeldet sein.</p>
      </div>`;
      return;
    }
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa())) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">📋 MEINE WORTLISTEN</p>
        <p class="empty-note">Der Wortschatz wird geladen …</p></div>`;
      wortschatzBereit().then(() => renderWortlisten());
      return;
    }
    const listen = meineWortlisten();
    const p = wortlistenPruefung;
    const gemerkt = meinWortschatz().size;
    area.innerHTML = `
      <div class="question-card">
        <p class="eyebrow">📋 MEINE WORTLISTEN <span class="subnav-info-icon" data-info="Wirf eine Liste Wörter ein — aus dem Kursbuch, von der Tafel, aus einer Nachricht. Danach kannst du in den Spielen genau mit diesen Wörtern üben.">ⓘ</span></p>
        <div class="trophy-case wsm-chips" style="margin-bottom:10px;">
          <button type="button" class="trophy-chip ${wortlisteArt === "liste" ? "selected" : ""}" data-listenart="liste">📋 Einzelne Wörter</button>
          <button type="button" class="trophy-chip ${wortlisteArt === "text" ? "selected" : ""}" data-listenart="text">📖 Ganzer Text</button>
        </div>
        ${wortlisteArt === "text"
          ? `<p class="empty-note" style="margin-top:0;">Füge eine ganze Geschichte, einen Artikel oder ein Kapitel ein. Die App sucht sich die Wörter heraus, mit denen sich üben lässt — Artikel, Pronomen und Hilfsverben lässt sie weg — und sortiert sie danach, wie oft sie in <em>diesem</em> Text vorkommen.</p>`
          : `<p class="empty-note" style="margin-top:0;">Schreib oder füge deine Wörter ein — eines pro Zeile oder mit Komma getrennt. Artikel darfst du weglassen, eine Übersetzung hinter einem Gedankenstrich wird abgeschnitten.</p>`}
        <textarea id="wortlisteEingabe" class="wortliste-feld" rows="${wortlisteArt === "text" ? 10 : 7}" placeholder="${wortlisteArt === "text"
          ? "Es war einmal ein kleiner Fuchs, der am Fluss wohnte. Jeden Morgen ging er zum Wasser und schaute den Fischen zu …"
          : "der Tisch&#10;Fenster&#10;aufstehen – to get up&#10;1. die Verspätung&#10;Bahnhof, Fahrkarte, umsteigen"}">${wortlistenText.replace(/</g, "&lt;")}</textarea>
        <div class="quiz-actions" style="justify-content:flex-start; margin-top:8px;">
          <button type="button" class="btn btn-coffee" id="wortlistePruefen">${wortlisteArt === "text" ? "📖 Wörter heraussuchen" : "🔍 Prüfen"}</button>
          ${wortlistenText ? `<button type="button" class="btn btn-ghost" id="wortlisteLeeren">Leeren</button>` : ""}
        </div>
        ${p ? `
          <div class="wortliste-ergebnis">
            ${p.saetze !== undefined ? `<p class="empty-note" style="margin:12px 0 0;">Aus deinem Text (${p.gesamt} Wörter, ${p.saetze} ${p.saetze === 1 ? "Satz" : "Sätze"}) sind das die <strong>${p.gefunden.length}</strong> lernbaren Wörter — die häufigsten zuerst.</p>` : ""}
            <p class="wortliste-bilanz">
              <span class="wortliste-bilanz-da">✓ ${p.gefunden.length} gefunden</span>
              ${p.fehlend.length ? `<span class="wortliste-bilanz-fehlt">✕ ${p.fehlend.length} unbekannt</span>` : ""}
            </p>
            ${wortlisteChipsHtml(p.gefunden, p.fehlend, false)}
            ${p.fehlend.length ? `
              <p class="empty-note" style="margin:10px 0 0;">Die roten Wörter kennt das Wörterbuch noch nicht — kein Spiel kann sie abfragen, weil weder Betonung noch Beispielsatz dafür hinterlegt sind. Meist ist es ein Tippfehler oder eine gebeugte Form (<em>geh</em> statt <em>gehen</em>). <strong>Gemeldet sind sie schon:</strong> Sie liegen jetzt in Alex' Sammelliste und kommen mit einem der nächsten Updates ins Wörterbuch.</p>` : ""}
            ${p.gefunden.length ? `
              <div class="form-field" style="margin-top:16px;">
                <label>Name der Liste</label>
                <input type="text" id="wortlisteName" maxlength="40" placeholder="${wortlisteArt === "text" ? "z. B. Der Fuchs am Fluss" : "z. B. Kapitel 7 oder Prüfung Freitag"}" />
              </div>
              <div class="quiz-actions" style="justify-content:flex-start;">
                <button type="button" class="btn btn-coffee" id="wortlisteSichern">💾 Als Liste speichern</button>
                <button type="button" class="btn btn-ghost" id="wortlisteAlsWortschatz">★ Alle in meinen Wortschatz</button>
              </div>` : ""}
          </div>` : ""}
      </div>

      ${gemerkt ? `<div class="question-card" style="margin-top:14px;">
        <h3 style="margin-top:0;">★ Dein Wortschatz</h3>
        <p class="empty-note" style="margin-top:0;">${gemerkt} ${gemerkt === 1 ? "Wort" : "Wörter"} hast du im Wörterbuch mit dem Stern markiert. Du kannst daraus jederzeit eine Liste machen — dann lässt sie sich einzeln bearbeiten, ohne deinen Wortschatz zu verändern.</p>
        <button type="button" class="btn btn-ghost" id="wortschatzAlsListe">📋 Daraus eine Wortliste machen</button>
      </div>` : ""}

      <div class="question-card" style="margin-top:14px;">
        <h3 style="margin-top:0;">Gespeicherte Listen</h3>
        ${listen.length ? `<div class="breakdown-list">
          ${listen.map((l) => wortlisteZeileHtml(l)).join("")}
        </div>` : '<p class="empty-note">Noch keine Liste gespeichert.</p>'}
        <p class="empty-note" style="margin-top:12px; font-size:0.74rem;">Wo die Listen wirken: in allen Spielen, die mit einzelnen Wörtern arbeiten. Tippst du <strong>🎮 Damit spielen</strong>, führt dich die App in die Spieleübersicht und hebt genau diese Spiele hervor.</p>
      </div>`;

    const feld = document.getElementById("wortlisteEingabe");
    feld?.addEventListener("input", () => { wortlistenText = feld.value; });
    area.querySelectorAll("[data-listenart]").forEach((b) => b.addEventListener("click", () => {
      wortlisteArt = b.dataset.listenart;
      wortlistenPruefung = null;
      renderWortlisten();
    }));
    document.getElementById("wortlistePruefen")?.addEventListener("click", () => {
      wortlistenText = feld ? feld.value : "";
      wortlistenPruefung = wortlisteArt === "text"
        ? textAuswerten(wortlistenText)
        : wortlisteEinlesen(wortlistenText);
      wortlueckenMelden(wortlistenPruefung.fehlend);
      renderWortlisten();
    });
    document.getElementById("wortlisteLeeren")?.addEventListener("click", () => {
      wortlistenText = ""; wortlistenPruefung = null; renderWortlisten();
    });
    document.getElementById("wortlisteSichern")?.addEventListener("click", async () => {
      const name = (document.getElementById("wortlisteName")?.value || "").trim() || ("Liste vom " + new Date().toLocaleDateString("de-DE"));
      const id = await wortlisteSpeichern(name, wortlistenPruefung.gefunden.map((g) => g.wort));
      if (id) {
        showToast(`📋 „${name}“ gespeichert — du findest sie jetzt in den Spielen.`);
        wortlistenText = ""; wortlistenPruefung = null;
      }
      renderWortlisten();
    });
    document.getElementById("wortlisteAlsWortschatz")?.addEventListener("click", async () => {
      const menge = meinWortschatz();
      wortlistenPruefung.gefunden.forEach((g) => menge.add(g.wort));
      try { await wortschatzSichern(menge); showToast(`★ ${wortlistenPruefung.gefunden.length} Wörter in deinen Wortschatz übernommen.`); }
      catch (e) { showToast("Konnte gerade nicht gespeichert werden."); }
      renderWortlisten();
    });
    document.getElementById("wortschatzAlsListe")?.addEventListener("click", async () => {
      const woerter = [...meinWortschatz()];
      if (!woerter.length) return;
      const name = "Mein Wortschatz (" + new Date().toLocaleDateString("de-DE") + ")";
      const id = await wortlisteSpeichern(name, woerter);
      if (id) showToast(`📋 „${name}“ angelegt — ${woerter.length} Wörter.`);
      renderWortlisten();
    });
    wortlistenZeilenVerdrahten(area);
  }

  /* Eine Zeile in „Gespeicherte Listen" — zugeklappt eine Übersicht,
     aufgeklappt der Editor. */
  function wortlisteZeileHtml(l) {
    const offen = wortlisteOffen === l.id;
    if (!offen) {
      return `
        <div class="breakdown-row" style="flex-direction:column; align-items:flex-start; gap:6px;">
          <span style="display:flex; justify-content:space-between; width:100%; align-items:center;">
            <strong>📋 ${l.name}</strong>
            <span class="empty-note">${l.woerter.length} Wörter</span>
          </span>
          <span class="empty-note" style="font-size:0.74rem;">${l.woerter.slice(0, 8).join(" · ")}${l.woerter.length > 8 ? " …" : ""}</span>
          <span style="display:flex; gap:8px; flex-wrap:wrap;">
            <button type="button" class="btn btn-ghost" style="padding:5px 12px; font-size:0.78rem;" data-liste-spielen="${l.id}">🎮 Damit spielen</button>
            <button type="button" class="btn btn-ghost" style="padding:5px 12px; font-size:0.78rem;" data-liste-auf="${l.id}">✏️ Bearbeiten</button>
            <button type="button" class="btn btn-ghost" style="padding:5px 12px; font-size:0.78rem;" data-liste-stern="${l.id}">★ In meinen Wortschatz</button>
            <button type="button" class="btn btn-ghost" style="padding:5px 12px; font-size:0.78rem;" data-liste-weg="${l.id}">🗑️ Löschen</button>
          </span>
        </div>`;
    }
    const n = wortlisteNachtragPruefung;
    return `
      <div class="breakdown-row wortliste-editor" style="flex-direction:column; align-items:stretch; gap:8px;">
        <div class="form-field" style="margin:0;">
          <label>Name der Liste</label>
          <input type="text" id="wortlisteNameNeu" maxlength="40" value="${String(l.name).replace(/"/g, "&quot;")}" />
        </div>
        <p class="empty-note" style="margin:0;">${l.woerter.length} ${l.woerter.length === 1 ? "Wort" : "Wörter"} — tippe auf ✕, um eines herauszunehmen.</p>
        ${wortlisteChipsHtml(l.woerter, [], true)}
        <label class="empty-note" style="margin-top:6px; font-size:0.76rem;">Wörter nachtragen</label>
        <textarea id="wortlisteNachtrag" class="wortliste-feld" rows="3" placeholder="neue Wörter, eines pro Zeile oder mit Komma">${wortlisteNachtragText.replace(/</g, "&lt;")}</textarea>
        <div class="quiz-actions" style="justify-content:flex-start; margin:0;">
          <button type="button" class="btn btn-ghost" style="padding:5px 12px; font-size:0.78rem;" id="wortlisteNachtragPruefen">🔍 Prüfen</button>
        </div>
        ${n ? `
          <p class="wortliste-bilanz" style="margin:4px 0 0;">
            <span class="wortliste-bilanz-da">✓ ${n.gefunden.length} gefunden</span>
            ${n.fehlend.length ? `<span class="wortliste-bilanz-fehlt">✕ ${n.fehlend.length} unbekannt</span>` : ""}
          </p>
          ${wortlisteChipsHtml(n.gefunden, n.fehlend, false)}
          ${n.fehlend.length ? `<p class="empty-note" style="margin:6px 0 0; font-size:0.74rem;">Die roten sind gemeldet und kommen mit einem Update ins Wörterbuch.</p>` : ""}
        ` : ""}
        <div class="quiz-actions" style="justify-content:flex-start; margin-top:4px;">
          <button type="button" class="btn btn-coffee" style="padding:6px 14px; font-size:0.8rem;" data-liste-speichern="${l.id}">💾 Änderungen speichern</button>
          <button type="button" class="btn btn-ghost" style="padding:6px 14px; font-size:0.8rem;" data-liste-zu="1">Abbrechen</button>
        </div>
      </div>`;
  }

  function wortlistenZeilenVerdrahten(area) {
    area.querySelectorAll("[data-liste-weg]").forEach((b) => b.addEventListener("click", async () => {
      if (!confirm("Diese Liste wirklich löschen?")) return;
      await wortlisteLoeschen(b.dataset.listeWeg); renderWortlisten();
    }));
    area.querySelectorAll("[data-liste-auf]").forEach((b) => b.addEventListener("click", () => {
      wortlisteOffen = b.dataset.listeAuf;
      wortlisteNachtragText = ""; wortlisteNachtragPruefung = null;
      renderWortlisten();
    }));
    area.querySelectorAll("[data-liste-zu]").forEach((b) => b.addEventListener("click", () => {
      wortlisteOffen = null; wortlisteNachtragText = ""; wortlisteNachtragPruefung = null;
      renderWortlisten();
    }));
    const nachtragFeld = document.getElementById("wortlisteNachtrag");
    nachtragFeld?.addEventListener("input", () => { wortlisteNachtragText = nachtragFeld.value; });
    document.getElementById("wortlisteNachtragPruefen")?.addEventListener("click", () => {
      wortlisteNachtragText = nachtragFeld ? nachtragFeld.value : "";
      wortlisteNachtragPruefung = wortlisteEinlesen(wortlisteNachtragText);
      wortlueckenMelden(wortlisteNachtragPruefung.fehlend);
      renderWortlisten();
    });
    /* Ein Wort herausnehmen wirkt sofort im Bild, gespeichert wird es
       aber erst mit „Änderungen speichern" — sonst könnte man ein
       versehentliches ✕ nicht mehr zurücknehmen. */
    area.querySelectorAll("[data-wort-weg]").forEach((b) => b.addEventListener("click", () => {
      b.closest(".wortliste-chip")?.remove();
    }));
    area.querySelectorAll("[data-liste-speichern]").forEach((b) => b.addEventListener("click", async () => {
      const id = b.dataset.listeSpeichern;
      const alteListe = wortlisteMitId(id);
      if (!alteListe) return;
      const editor = b.closest(".wortliste-editor");
      const uebrig = [...editor.querySelectorAll(".wortliste-chip-da [data-wort-weg]")].map((x) => x.dataset.wortWeg);
      const dazu = (wortlisteNachtragPruefung ? wortlisteNachtragPruefung.gefunden.map((g) => g.wort) : []);
      const zusammen = [...new Set([...uebrig, ...dazu])];
      if (!zusammen.length) { showToast("Eine Liste ohne Wörter ergibt keinen Sinn — dann lieber löschen."); return; }
      const name = (document.getElementById("wortlisteNameNeu")?.value || alteListe.name).trim();
      const ok = await wortlisteAendern(id, { name, woerter: zusammen });
      if (ok) {
        showToast(`📋 „${name}“ gespeichert — ${zusammen.length} ${zusammen.length === 1 ? "Wort" : "Wörter"}.`);
        wortlisteOffen = null; wortlisteNachtragText = ""; wortlisteNachtragPruefung = null;
      }
      renderWortlisten();
    }));
    area.querySelectorAll("[data-liste-stern]").forEach((b) => b.addEventListener("click", async () => {
      const l = wortlisteMitId(b.dataset.listeStern);
      if (!l) return;
      const menge = meinWortschatz();
      l.woerter.forEach((w) => menge.add(w));
      try { await wortschatzSichern(menge); showToast(`★ ${l.woerter.length} Wörter übernommen.`); }
      catch (e) { showToast("Konnte gerade nicht gespeichert werden."); }
      renderWortlisten();
    }));
    area.querySelectorAll("[data-liste-spielen]").forEach((b) => b.addEventListener("click", () => {
      const l = wortlisteMitId(b.dataset.listeSpielen);
      // Die Liste für ALLE Spiele auf einmal vorwählen — sonst müsste
      // man sie in jedem Spiel einzeln antippen.
      WORTQUELLE_SPIELE.forEach((spiel) => { wortQuelleWahl[spiel] = "liste:" + b.dataset.listeSpielen; });
      /* Und die Übersicht wissen lassen, worum es geht: sie hebt genau
         die Spiele hervor, die mit dieser Liste üben können. */
      wortlisteImBlick = l ? { id: l.id, name: l.name, anzahl: l.woerter.length } : null;
      wortlisteAnkunft = true;
      document.querySelector('#learnSubnav [data-sub="sub-games"]')?.click();
    }));
  }
  document.querySelector('#learnSubnav [data-sub="sub-wortlisten"]')?.addEventListener("click", () => renderWortlisten());


  /* ============================================================
     DIE SETZEREI — groß oder klein?
     ------------------------------------------------------------
     Die Großschreibung mitten im Satz gibt es so nur im Deutschen.
     Sie ist keine Zierde, sondern eine Lesehilfe: das große S in
     „das Essen" sagt einem, dass hier ein Ding steht und kein Tun.
     Wer sie nicht sieht, liest langsamer — und wer sie nicht setzt,
     wird in jeder Prüfung dafür bezahlen.

     Geübt wird sie hier so, wie man sie früher gesetzt hat: der Satz
     liegt in einem Setzkasten, alles in Kleinbuchstaben. Wo ein
     großer Buchstabe hingehört, tippt man das Wort an — es springt
     hoch. Erst am Ende wird geprüft.

     Die Sätze sind KEINE erfundenen Übungssätze, sondern die
     Beispielsätze aus dem Wörterbuch: sie sind alle von Hand
     geschrieben, und die richtige Lösung ist damit einfach die
     ursprüngliche Schreibweise. Es gibt hier also nichts zu raten
     und nichts zu berechnen — nur zu vergleichen.

     Das erste Wort steht schon groß da. Der Satzanfang ist keine
     Aufgabe, sondern eine Selbstverständlichkeit; stünde er zur
     Wahl, wäre jede Runde zur Hälfte geschenkt.
     ============================================================ */
  let setzLevel = null;
  let setzSession = null;
  const SETZ_RUNDEN = 8;
  const SETZ_ZEICHEN = /^[«»„“”"'(\[]+|[«»„“”"'.,;:!?)\]…]+$/g;

  /* Ein Satz in Wörter zerlegt, mit dem, was jedes Wort im Original
     war. `kern` ist das Wort ohne Anführungszeichen und Satzzeichen —
     nur an ihm hängt die Frage groß oder klein. */
  function setzZerlegen(satz) {
    return String(satz).split(/\s+/).filter(Boolean).map((roh, i) => {
      const vorn = (roh.match(/^[«»„“”"'(\[]+/) || [""])[0];
      const hinten = (roh.match(/[«»„“”"'.,;:!?)\]…]+$/) || [""])[0];
      const kern = roh.slice(vorn.length, roh.length - hinten.length);
      return {
        i, vorn, hinten, kern,
        gross: /^[A-ZÄÖÜ]/.test(kern),
        zaehlt: i > 0 && /^[A-Za-zÄÖÜäöüß]/.test(kern) && kern.length > 0,
      };
    });
  }
  /* Wie schwer ein Satz ist: kurze Sätze mit einer Großschreibung sind
     A1, lange mit mehreren sind C1. Gemessen wird nicht am Niveau des
     Stichworts, sondern am Satz selbst — er ist ja die Aufgabe. */
  function setzSatzStufe(satz) {
    const teile = setzZerlegen(satz);
    const woerter = teile.filter((t) => t.zaehlt).length;
    const grosse = teile.filter((t) => t.zaehlt && t.gross).length;
    if (woerter <= 7 && grosse <= 1) return "A1";
    if (woerter <= 9 && grosse <= 2) return "A2";
    if (woerter <= 12) return "B1";
    if (woerter <= 15) return "B2";
    return "C1";
  }
  function setzPool() {
    const alle = buildDictionaryEntries().filter((e) =>
      e.verified && e.example && e.example.length >= 22 && e.example.length <= 130
      && e.example.split(/\s+/).length >= 5 && !/\d/.test(e.example));
    const eigene = wortQuelleFilter("setzerei", alle);
    return eigene.length >= SETZ_RUNDEN ? eigene : alle;
  }
  function neueSetzSession() {
    setzLevel = applyDefaultCefrLevel(setzLevel, (v) => { setzLevel = v; }, "setzerei");
    const pool = setzPool();
    const passend = pool.filter((e) => setzSatzStufe(e.example) === setzLevel);
    const quelle = passend.length >= SETZ_RUNDEN ? passend : pool;
    setzSession = {
      saetze: Core.shuffle(quelle).slice(0, SETZ_RUNDEN),
      runde: 0, richtig: 0, treffer: 0, moeglich: 0, danebenGesamt: 0,
      gewaehlt: new Set(), geprueft: false, wort: null,
    };
    setzRundeVorbereiten();
  }
  function setzRundeVorbereiten() {
    const s = setzSession;
    const e = s.saetze[s.runde];
    if (!e) return;
    s.teile = setzZerlegen(e.example);
    s.wort = e.word;
    s.gewaehlt = new Set();
    s.geprueft = false;
  }
  function renderSetzerei() {
    const area = document.getElementById("setzereiArea");
    if (!area) return;
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa()) && setzPool().length < 200) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">🅰️ DIE SETZEREI</p>
        <p class="empty-note">Der Setzkasten wird gefüllt …</p></div>`;
      wortschatzBereit().then(() => renderSetzerei());
      return;
    }
    if (!setzSession) neueSetzSession();
    const s = setzSession;
    if (s.runde >= s.saetze.length) { renderSetzereiErgebnis(); return; }
    const noetig = s.teile.filter((t) => t.zaehlt && t.gross).length;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Die Setzerei: " + (s.wort || ""))}
        <p class="eyebrow">🅰️ DIE SETZEREI · SATZ ${s.runde + 1} / ${s.saetze.length}
          <span class="subnav-info-icon" data-info="Der Satz liegt klein gesetzt im Kasten. Tippe jedes Wort an, das im Deutschen groß geschrieben wird — vor allem die Nomen. Das erste Wort steht schon richtig da.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.saetze.length)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1"].map((lvl) => `<button type="button" class="trophy-chip setz-level-btn ${setzLevel === lvl ? "selected" : ""}" data-setz-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("setzerei")}
        <p class="setz-auftrag">Welche Wörter gehören groß? <span class="empty-note">(${noetig} ${noetig === 1 ? "Wort" : "Wörter"})</span></p>
        <div class="setz-kasten">
          ${s.teile.map((t) => {
            if (!t.zaehlt) return `<span class="setz-fest">${t.vorn}${t.i === 0 ? t.kern : t.kern}${t.hinten}</span>`;
            const hoch = s.gewaehlt.has(t.i);
            const klasse = s.geprueft ? (t.gross === hoch ? "setz-ok" : "setz-falsch") : (hoch ? "setz-hoch" : "");
            const zeigen = s.geprueft ? (t.gross ? setzGross(t.kern) : t.kern.toLowerCase())
              : (hoch ? setzGross(t.kern) : t.kern.toLowerCase());
            return `<button type="button" class="setz-type ${klasse}" data-setz-wort="${t.i}" ${s.geprueft ? "disabled" : ""}>${t.vorn}${zeigen}${t.hinten}</button>`;
          }).join("")}
        </div>
        ${s.geprueft ? `
          <p class="setz-aufloesung">${setzAufloesung(s)}</p>
          <button type="button" class="btn btn-coffee" id="setzWeiter">Weiter →</button>`
        : `<button type="button" class="btn btn-coffee" id="setzPruefen">✓ Fertig gesetzt</button>`}
      </div>`;
    area.querySelectorAll(".setz-level-btn").forEach((b) => b.addEventListener("click", () => {
      setzLevel = b.dataset.setzLevel; neueSetzSession(); renderSetzerei();
    }));
    wortQuelleBinden(area, "setzerei", () => { neueSetzSession(); renderSetzerei(); });
    area.querySelectorAll("[data-setz-wort]").forEach((b) => b.addEventListener("click", () => {
      const i = Number(b.dataset.setzWort);
      if (s.gewaehlt.has(i)) s.gewaehlt.delete(i); else s.gewaehlt.add(i);
      renderSetzerei();
    }));
    document.getElementById("setzPruefen")?.addEventListener("click", () => setzPruefen());
    const setzNaechste = () => {
      s.runde += 1;
      if (s.runde < s.saetze.length) setzRundeVorbereiten();
      renderSetzerei();
    };
    document.getElementById("setzWeiter")?.addEventListener("click", () => { autoWeiterAbbrechen(); setzNaechste(); });
    if (s.geprueft) {
      const sauber = s.teile.every((t) => !t.zaehlt || t.gross === s.gewaehlt.has(t.i));
      autoWeiter(sauber, setzNaechste);
    }
  }
  function setzGross(wort) { return wort.charAt(0).toUpperCase() + wort.slice(1); }
  function setzAufloesung(s) {
    const noetig = s.teile.filter((t) => t.zaehlt && t.gross);
    const verpasst = noetig.filter((t) => !s.gewaehlt.has(t.i));
    const daneben = s.teile.filter((t) => t.zaehlt && !t.gross && s.gewaehlt.has(t.i));
    if (!verpasst.length && !daneben.length) {
      return `✅ Alles richtig gesetzt${noetig.length ? `: ${noetig.map((t) => "<strong>" + setzGross(t.kern) + "</strong>").join(", ")}` : ""}.`;
    }
    const stuecke = [];
    if (verpasst.length) stuecke.push(`groß gehören noch: ${verpasst.map((t) => "<strong>" + setzGross(t.kern) + "</strong>").join(", ")}`);
    if (daneben.length) stuecke.push(`klein bleiben: ${daneben.map((t) => "<strong>" + t.kern.toLowerCase() + "</strong>").join(", ")}`);
    return "❌ " + stuecke.join(" · ") + ".";
  }
  function setzPruefen() {
    const s = setzSession;
    if (s.geprueft) return;
    const noetig = s.teile.filter((t) => t.zaehlt && t.gross);
    const getroffen = noetig.filter((t) => s.gewaehlt.has(t.i)).length;
    const daneben = s.teile.filter((t) => t.zaehlt && !t.gross && s.gewaehlt.has(t.i)).length;
    s.treffer += getroffen;
    s.moeglich += noetig.length;
    s.danebenGesamt += daneben;
    const sauber = getroffen === noetig.length && daneben === 0;
    if (sauber) { s.richtig += 1; Core.sound.fanfare(); } else { Core.sound.wrong(); }
    spielNotiz(sauber, `${s.wort} — „${s.saetze[s.runde].example}“`);
    s.geprueft = true;
    renderSetzerei();
  }
  function renderSetzereiErgebnis() {
    const area = document.getElementById("setzereiArea");
    const s = setzSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.saetze.length)) * 100);
    const trefferProzent = Math.round((s.treffer / Math.max(1, s.moeglich)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.treffer * 2 + s.richtig * 3, prozent, tier: "Schriftsetzer:in", charakter: "Die Setzerei",
      bonus: s.danebenGesamt === 0 ? 10 : 0,
      zeilen: [
        { name: "🅰️ Fehlerfreie Sätze", anteil: prozent, wert: s.richtig + "/" + s.saetze.length },
        { name: "🔠 Große Buchstaben gefunden", anteil: trefferProzent, wert: s.treffer + "/" + s.moeglich },
      ],
      knoepfe: `<button type="button" class="btn btn-coffee" id="setzNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("setzNochmal")?.addEventListener("click", () => { neueSetzSession(); renderSetzerei(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["setzerei"], points: s.treffer * 2 + s.richtig * 3, bonus: s.danebenGesamt === 0 ? 10 : 0, percent: prozent, character: "Schriftsetzer:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-setzerei"]')?.addEventListener("click", () => renderSetzerei());


  /* ============================================================
     DIE WORTKETTE
     ------------------------------------------------------------
     Das deutsche Wort baut sich von hinten: im „Gartenschlauch" ist
     der Schlauch das Ding, der Garten sagt nur, welcher. Wer das
     einmal begriffen hat, versteht auch ein Wort, das er noch nie
     gesehen hat — und weiß, welcher Artikel davorgehört.

     Gespielt wird das als Kette, wie im Kinderspiel: das letzte Glied
     eines Wortes ist das erste des nächsten. Feier-ABEND, ABEND-brot,
     BROT-korb. Von drei angebotenen Wörtern passt genau eines an das
     freie Ende.

     Die Ketten werden nicht erfunden, sondern im Wörterbuch gesucht.
     Zerlegt wird mit derselben Funktion, die auch die Betonung
     zusammengesetzter Wörter bestimmt (zerlegeKompositum) — sie
     kennt die Wortstämme der App und rät nicht.

     Eine Feinheit, die eine Menge falscher Ketten verhindert: an ein
     Glied darf ein Fugenzeichen angehängt werden (Kind + er +
     garten), aber nur, wenn die längere Form nicht selbst ein
     eigenes Wort ist. Sonst hinge „der Bergkamm" plötzlich an „die
     Kammermusik", und ein Kamm hat mit einer Kammer nichts zu tun.
     ============================================================ */
  let ketteLevel = null;
  let ketteSession = null;
  const KETTE_GLIEDER = 6;
  const KETTE_FUGEN = ["", "s", "es", "n", "en", "er", "e"];

  let kettenIndexZwischen = null;
  let kettenIndexStand = -1;
  function kettenIndex() {
    const stand = VocabData.WORDS.length;
    if (kettenIndexZwischen && kettenIndexStand === stand) return kettenIndexZwischen;
    const eintraege = buildDictionaryEntries();
    const nomen = new Set();
    eintraege.forEach((e) => { if (/^(der|die|das)\s/.test(e.word)) nomen.add(e.word.replace(/^(der|die|das)\s+/, "").toLowerCase()); });
    const woerter = [];
    eintraege.forEach((e) => {
      if (!e.verified || !e.level || !/^(der|die|das)\s/.test(e.word)) return;
      const nackt = e.word.replace(/^(der|die|das)\s+/, "");
      if (/[\s-]/.test(nackt)) return;
      const teile = zerlegeKompositum(nackt);
      if (!teile || teile.length !== 2) return;
      if (teile[0].length < 3 || teile[1].length < 3) return;
      woerter.push({ wort: e.word, level: e.level, kopf: teile[0].toLowerCase(), schwanz: teile[1].toLowerCase(), teile });
    });
    // Nach Kopf sortiert nachschlagbar machen
    const nachKopf = new Map();
    woerter.forEach((w) => {
      if (!nachKopf.has(w.kopf)) nachKopf.set(w.kopf, []);
      nachKopf.get(w.kopf).push(w);
    });
    kettenIndexZwischen = { woerter, nachKopf, nomen };
    kettenIndexStand = stand;
    return kettenIndexZwischen;
  }
  /* Alle Wörter, die an ein gegebenes Endglied anschließen. Das
     Fugenzeichen ist erlaubt, solange die verlängerte Form nicht
     selbst im Wörterbuch steht — siehe Kamm/Kammer oben. */
  function ketteFortsetzungen(schwanz) {
    const { nachKopf, nomen } = kettenIndex();
    const raus = [];
    KETTE_FUGEN.forEach((f) => {
      const kopf = schwanz + f;
      if (f && nomen.has(kopf)) return;
      (nachKopf.get(kopf) || []).forEach((w) => raus.push(w));
    });
    return raus;
  }
  function neueKetteSession() {
    ketteLevel = applyDefaultCefrLevel(ketteLevel, (v) => { ketteLevel = v; }, "wortkette");
    const idx = kettenIndex();
    const eigene = wortQuelleFilter("wortkette", idx.woerter.map((w) => ({ word: w.wort, ...w })));
    const nachNiveau = idx.woerter.filter((w) => w.level === ketteLevel);
    let start = eigene.length >= 5 ? eigene : (nachNiveau.length >= 30 ? nachNiveau : idx.woerter);
    start = start.filter((w) => ketteFortsetzungen(w.schwanz).some((x) => x.wort !== w.wort));
    if (!start.length) start = idx.woerter.filter((w) => ketteFortsetzungen(w.schwanz).length > 1);
    const erstes = start[Math.floor(Math.random() * start.length)];
    ketteSession = {
      kette: [erstes], benutzt: new Set([erstes.wort]),
      glieder: KETTE_GLIEDER, richtig: 0, fehler: 0,
      zustand: "warten", wahl: [], fertig: false,
    };
    neueKetteWahl();
  }
  function neueKetteWahl() {
    const s = ketteSession;
    const letzte = s.kette[s.kette.length - 1];
    const idx = kettenIndex();
    const weiter = ketteFortsetzungen(letzte.schwanz).filter((w) => !s.benutzt.has(w.wort));
    if (!weiter.length) { s.fertig = true; return; }
    // Auf dem gewählten Niveau bleiben, solange dort etwas steht
    const passend = weiter.filter((w) => w.level === ketteLevel);
    const richtig = (passend.length ? passend : weiter)[Math.floor(Math.random() * (passend.length ? passend.length : weiter.length))];
    // Gegenproben: ebenfalls zusammengesetzte Wörter, die aber NICHT
    // anschließen. Bevorzugt solche mit demselben Endglied wie das
    // gesuchte Wort — dann ist die Frage wirklich „wo passt es AN?"
    // und nicht „welches Wort sieht am ehesten nach etwas aus?".
    const aehnlich = (idx.nachKopf.get(richtig.schwanz) || []).filter((w) => w.wort !== richtig.wort && !s.benutzt.has(w.wort));
    const zufall = idx.woerter;
    const daneben = [];
    const nimm = (kandidaten) => {
      Core.shuffle(kandidaten).forEach((w) => {
        if (daneben.length >= 2) return;
        if (w.wort === richtig.wort || s.benutzt.has(w.wort)) return;
        if (ketteFortsetzungen(letzte.schwanz).some((x) => x.wort === w.wort)) return; // würde ja passen
        if (daneben.some((d) => d.wort === w.wort)) return;
        daneben.push(w);
      });
    };
    nimm(aehnlich);
    if (daneben.length < 2) nimm(zufall.filter((w) => w.level === ketteLevel));
    if (daneben.length < 2) nimm(zufall);
    s.wahl = Core.shuffle([{ w: richtig, ok: true }].concat(daneben.map((w) => ({ w, ok: false }))));
    s.zustand = "warten";
  }
  /* Das Bild: die Kette selbst. Jedes Glied trägt sein Wort, und das
     gemeinsame Stück ist farbig hervorgehoben — daran sieht man, was
     das Spiel eigentlich meint, ohne dass es jemand erklären muss. */
  function ketteGliedHtml(w, neu) {
    return `<span class="kette-glied${neu ? " kette-glied-neu" : ""}">
      <span class="kette-kopf">${w.teile[0]}</span><span class="kette-schwanz">${w.teile[1]}</span>
    </span>`;
  }
  function renderWortkette() {
    const area = document.getElementById("wortketteArea");
    if (!area) return;
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa())) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">⛓️ DIE WORTKETTE</p>
        <p class="empty-note">Die Kette wird geschmiedet …</p></div>`;
      wortschatzBereit().then(() => renderWortkette());
      return;
    }
    if (!ketteSession) neueKetteSession();
    const s = ketteSession;
    if (s.fertig || s.kette.length > s.glieder) { renderWortketteErgebnis(); return; }
    const letzte = s.kette[s.kette.length - 1];
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Die Wortkette: " + letzte.wort)}
        <p class="eyebrow">⛓️ DIE WORTKETTE · GLIED ${s.kette.length} / ${s.glieder}
          <span class="subnav-info-icon" data-info="Das letzte Stück eines Wortes ist das erste des nächsten: Feier-ABEND, ABEND-brot, BROT-korb. Von drei Wörtern passt genau eines an das freie Ende.">ⓘ</span></p>
        ${fortschrittHtml(s.kette.length - 1, s.glieder)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip kette-level-btn ${ketteLevel === lvl ? "selected" : ""}" data-kette-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("wortkette")}
        <div class="kette-band">
          ${s.kette.map((w, i) => ketteGliedHtml(w, i === s.kette.length - 1)).join('<span class="kette-haken">–</span>')}
        </div>
        <p class="kette-frage">Was hängt an <strong>„${letzte.teile[1]}“</strong>?</p>
        <div class="kette-wahl">
          ${s.wahl.map((x, i) => `<button type="button" class="kette-karte" data-kette-wahl="${i}">${x.w.wort}</button>`).join("")}
        </div>
        <p class="empty-note kette-hinweis" id="ketteHinweis">Achte auf den ANFANG der Wörter, nicht auf die Bedeutung.</p>
      </div>`;
    area.querySelectorAll(".kette-level-btn").forEach((b) => b.addEventListener("click", () => {
      ketteLevel = b.dataset.ketteLevel; neueKetteSession(); renderWortkette();
    }));
    wortQuelleBinden(area, "wortkette", () => { neueKetteSession(); renderWortkette(); });
    area.querySelectorAll("[data-kette-wahl]").forEach((b) => b.addEventListener("click", () => ketteAntwort(Number(b.dataset.ketteWahl), b)));
  }
  function ketteAntwort(i, knopf) {
    const s = ketteSession;
    if (s.zustand !== "warten") return;
    const wahl = s.wahl[i];
    const treffer = s.wahl.find((x) => x.ok);
    const letzte = s.kette[s.kette.length - 1];
    s.zustand = wahl.ok ? "richtig" : "falsch";
    spielNotiz(wahl.ok, `${letzte.wort} → ${treffer.w.wort}`);
    document.querySelectorAll(".kette-karte").forEach((b, n) => {
      b.disabled = true;
      if (s.wahl[n].ok) b.classList.add("kette-karte-passt");
      else if (n === i) b.classList.add("kette-karte-passt-nicht");
    });
    const box = document.getElementById("ketteHinweis");
    if (wahl.ok) {
      s.richtig += 1;
      Core.sound.correct();
      if (box) box.innerHTML = `✅ <strong>${treffer.w.teile[0]}</strong>${treffer.w.teile[1]} — passt an „${letzte.teile[1]}“.`;
    } else {
      s.fehler += 1;
      Core.sound.wrong();
      if (box) box.innerHTML = `❌ „${wahl.w.wort}“ fängt mit <strong>${wahl.w.teile[0]}</strong> an, nicht mit „${letzte.teile[1]}“. Es passt: <strong>${treffer.w.teile[0]}</strong>${treffer.w.teile[1]}.`;
    }
    setTimeout(() => {
      s.kette.push(treffer.w);
      s.benutzt.add(treffer.w.wort);
      if (s.kette.length > s.glieder) { renderWortketteErgebnis(); return; }
      neueKetteWahl();
      renderWortkette();
    }, wahl.ok ? 1400 : 2600);
  }
  function renderWortketteErgebnis() {
    const area = document.getElementById("wortketteArea");
    const s = ketteSession;
    const versuche = s.richtig + s.fehler;
    const prozent = Math.round((s.richtig / Math.max(1, versuche)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.richtig * 3, prozent, tier: "Kettenschmied:in", charakter: "Die Wortkette",
      bonus: s.fehler === 0 ? 8 : 0,
      zeilen: [
        { name: "⛓️ Richtig angehängt", anteil: prozent, wert: s.richtig + "/" + versuche },
        { name: "🔗 Länge der Kette", anteil: Math.round((s.kette.length / (s.glieder + 1)) * 100), wert: s.kette.length + " Wörter" },
      ],
      knoepfe: `<button type="button" class="btn btn-coffee" id="ketteNochmal">🔄 Neue Kette</button>`,
    });
    document.getElementById("ketteNochmal")?.addEventListener("click", () => { neueKetteSession(); renderWortkette(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["wortkette"], points: s.richtig * 3, bonus: s.fehler === 0 ? 8 : 0, percent: prozent, character: "Kettenschmied:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-wortkette"]')?.addEventListener("click", () => renderWortkette());


  /* ============================================================
     AUGENBLICK! — der Satz war eben noch da
     ------------------------------------------------------------
     Lesen in einer fremden Sprache heißt am Anfang: Wort für Wort
     entziffern. Bis man am Ende ist, ist der Anfang wieder weg. Was
     fehlt, ist die Spanne — so viel auf einmal aufnehmen zu können,
     dass ein Satz als Satz ankommt und nicht als Kette von
     Einzelteilen.

     Genau das übt dieses Spiel, und zwar mit Absicht unter Zeitdruck:
     der Satz erscheint für ein paar Sekunden und verschwindet dann.
     Danach liegen seine Wörter durcheinander da und müssen in die
     richtige Reihenfolge gebracht werden. Man braucht also beides —
     das Gedächtnis für das Bild des Satzes und das Gefühl dafür, wie
     ein deutscher Satz gebaut ist. Wer sich nicht mehr erinnert, kann
     trotzdem weiterkommen, wenn er die Satzstellung kennt.

     Die Sätze sind die geprüften Beispielsätze aus dem Wörterbuch,
     keine gebauten Übungssätze. Und die Anzeigedauer richtet sich
     nach dem Niveau: A1 bekommt reichlich Zeit für kurze Sätze, C1
     sehr wenig für lange.

     Einmal nachsehen darf man — das kostet aber die Hälfte der
     Punkte für diesen Satz. Wer feststeckt, soll weiterkommen, ohne
     dass das Nachsehen zur Gewohnheit wird.
     ============================================================ */
  let augLevel = null;
  let augSession = null;
  const AUG_RUNDEN = 8;
  const AUG_STUFEN = {
    A1: { woerter: [4, 7], zeit: 4500 },
    A2: { woerter: [5, 9], zeit: 4000 },
    B1: { woerter: [7, 11], zeit: 3500 },
    B2: { woerter: [9, 14], zeit: 3000 },
    C1: { woerter: [11, 18], zeit: 2600 },
    C2: { woerter: [12, 22], zeit: 2200 },
  };
  function augPool() {
    const stufe = AUG_STUFEN[augLevel] || AUG_STUFEN.B1;
    const alle = buildDictionaryEntries().filter((e) => {
      if (!e.verified || !e.example) return false;
      const n = e.example.split(/\s+/).filter(Boolean).length;
      return n >= stufe.woerter[0] && n <= stufe.woerter[1];
    });
    const eigene = wortQuelleFilter("augenblick", alle);
    return eigene.length >= AUG_RUNDEN ? eigene : alle;
  }
  function neueAugSession() {
    augLevel = applyDefaultCefrLevel(augLevel, (v) => { augLevel = v; }, "augenblick");
    const pool = augPool();
    augSession = {
      saetze: Core.shuffle(pool).slice(0, AUG_RUNDEN),
      runde: 0, richtig: 0, punkte: 0, nachgesehen: 0,
      phase: "bereit", gelegt: [], vorrat: [], nochmalBenutzt: false, wort: null,
    };
    augRundeVorbereiten();
  }
  function augRundeVorbereiten() {
    const s = augSession;
    const e = s.saetze[s.runde];
    if (!e) return;
    s.satz = e.example;
    s.wort = e.word;
    s.teile = e.example.split(/\s+/).filter(Boolean);
    s.gelegt = [];
    s.vorrat = Core.shuffle(s.teile.map((t, i) => ({ t, i })));
    s.phase = "bereit";
    s.nochmalBenutzt = false;
  }
  function augZeigen(nochmal) {
    const s = augSession;
    const stufe = AUG_STUFEN[augLevel] || AUG_STUFEN.B1;
    if (nochmal) { s.nochmalBenutzt = true; s.nachgesehen += 1; }
    s.phase = "zeigen";
    renderAugenblick();
    const dauer = nochmal ? Math.round(stufe.zeit * 0.7) : stufe.zeit;
    clearTimeout(augSession.uhr);
    augSession.uhr = setTimeout(() => {
      if (augSession !== s) return;
      s.phase = "legen";
      renderAugenblick();
    }, dauer);
  }
  function renderAugenblick() {
    const area = document.getElementById("augenblickArea");
    if (!area) return;
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa())) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">👁️ AUGENBLICK!</p>
        <p class="empty-note">Die Sätze werden geholt …</p></div>`;
      wortschatzBereit().then(() => renderAugenblick());
      return;
    }
    if (!augSession) neueAugSession();
    const s = augSession;
    if (s.runde >= s.saetze.length) { renderAugenblickErgebnis(); return; }
    const stufe = AUG_STUFEN[augLevel] || AUG_STUFEN.B1;
    const fertig = s.gelegt.length === s.teile.length;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Augenblick!: " + (s.wort || ""))}
        <p class="eyebrow">👁️ AUGENBLICK! · SATZ ${s.runde + 1} / ${s.saetze.length}
          <span class="subnav-info-icon" data-info="Der Satz erscheint kurz und verschwindet wieder. Danach legst du ihn aus seinen Wörtern neu zusammen — aus dem Gedächtnis oder aus dem Gefühl für die Satzstellung.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.saetze.length)}
        <div class="trophy-case wsm-chips">
          ${Object.keys(AUG_STUFEN).map((lvl) => `<button type="button" class="trophy-chip aug-level-btn ${augLevel === lvl ? "selected" : ""}" data-aug-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("augenblick")}
        ${s.phase === "bereit" ? `
          <div class="aug-buehne aug-buehne-leer">
            <p class="empty-note" style="margin:0;">${s.teile.length} Wörter · ${(stufe.zeit / 1000).toFixed(1)} Sekunden</p>
          </div>
          <button type="button" class="btn btn-coffee" id="augLos">👁️ Satz zeigen</button>`
        : s.phase === "zeigen" ? `
          <div class="aug-buehne aug-buehne-satz"><p class="aug-satz">${s.satz}</p></div>
          <p class="empty-note" style="text-align:center;">Einprägen …</p>`
        : `
          <div class="aug-buehne aug-buehne-bau">
            ${s.gelegt.length ? s.gelegt.map((x, n) => `<button type="button" class="aug-wort aug-wort-gelegt" data-aug-zurueck="${n}">${x.t}</button>`).join("")
              : '<span class="empty-note">Tippe die Wörter in der richtigen Reihenfolge an.</span>'}
          </div>
          <div class="aug-vorrat">
            ${s.vorrat.filter((x) => !s.gelegt.includes(x)).map((x) => `<button type="button" class="aug-wort" data-aug-nehmen="${s.vorrat.indexOf(x)}">${x.t}</button>`).join("")}
          </div>
          <div class="quiz-actions" style="justify-content:center; margin-top:12px;">
            ${fertig ? `<button type="button" class="btn btn-coffee" id="augPruefen">✓ So war er</button>` : ""}
            ${!s.nochmalBenutzt ? `<button type="button" class="btn btn-ghost" id="augNochmal">👁️ Noch einmal zeigen (halbe Punkte)</button>` : ""}
          </div>`}
        <p class="empty-note aug-hinweis" id="augHinweis"></p>
      </div>`;
    area.querySelectorAll(".aug-level-btn").forEach((b) => b.addEventListener("click", () => {
      augLevel = b.dataset.augLevel; neueAugSession(); renderAugenblick();
    }));
    wortQuelleBinden(area, "augenblick", () => { neueAugSession(); renderAugenblick(); });
    document.getElementById("augLos")?.addEventListener("click", () => augZeigen(false));
    document.getElementById("augNochmal")?.addEventListener("click", () => augZeigen(true));
    area.querySelectorAll("[data-aug-nehmen]").forEach((b) => b.addEventListener("click", () => {
      s.gelegt.push(s.vorrat[Number(b.dataset.augNehmen)]);
      renderAugenblick();
    }));
    area.querySelectorAll("[data-aug-zurueck]").forEach((b) => b.addEventListener("click", () => {
      s.gelegt.splice(Number(b.dataset.augZurueck), 1);
      renderAugenblick();
    }));
    document.getElementById("augPruefen")?.addEventListener("click", () => augPruefen());
  }
  function augPruefen() {
    const s = augSession;
    const gebaut = s.gelegt.map((x) => x.t).join(" ");
    const stimmt = gebaut === s.satz;
    spielNotiz(stimmt, `${s.wort} — „${s.satz}“`);
    const punkte = stimmt ? (s.nochmalBenutzt ? 2 : 4) : 0;
    s.punkte += punkte;
    if (stimmt) { s.richtig += 1; Core.sound.fanfare(); } else { Core.sound.wrong(); }
    const box = document.getElementById("augHinweis");
    if (box) {
      box.innerHTML = stimmt ? `✅ Wort für Wort richtig.`
        : `❌ So war er: <strong>${s.satz}</strong>`;
    }
    document.querySelectorAll("#augenblickArea .aug-wort").forEach((b) => { b.disabled = true; });
    document.getElementById("augPruefen")?.setAttribute("disabled", "true");
    setTimeout(() => {
      s.runde += 1;
      if (s.runde < s.saetze.length) augRundeVorbereiten();
      renderAugenblick();
    }, stimmt ? 1600 : 3400);
  }
  function renderAugenblickErgebnis() {
    const area = document.getElementById("augenblickArea");
    const s = augSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.saetze.length)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.punkte, prozent, tier: "Schnellleser:in", charakter: "Augenblick!",
      bonus: s.nachgesehen === 0 && s.richtig === s.saetze.length ? 12 : 0,
      zeilen: [
        { name: "👁️ Satz genau getroffen", anteil: prozent, wert: s.richtig + "/" + s.saetze.length },
        { name: "🔁 Noch einmal angesehen", anteil: Math.round(((s.saetze.length - s.nachgesehen) / s.saetze.length) * 100), wert: s.nachgesehen + "×" },
      ],
      knoepfe: `<button type="button" class="btn btn-coffee" id="augNochmalRunde">🔄 Neue Runde</button>`,
    });
    document.getElementById("augNochmalRunde")?.addEventListener("click", () => { neueAugSession(); renderAugenblick(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["augenblick"], points: s.punkte, bonus: 0, percent: prozent, character: "Schnellleser:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-augenblick"]')?.addEventListener("click", () => renderAugenblick());


  /* ============================================================
     MEINE SÄTZE — Beispielsätze zu den eigenen Vokabeln
     ------------------------------------------------------------
     GEWÜNSCHT: „dass du vielleicht Beispielsätze hast für mehrere
     Spiele, wo man die eigenen Vokabeln [benutzt], wo das System
     erkennt."

     Zu jedem Wort im Wörterbuch steht ein Beispielsatz. Wer ein Wort
     mit dem Stern merkt oder in eine Wortliste schreibt, hat damit
     auch dessen Satz. Dieses Spiel schneidet das Wort aus seinem Satz
     heraus und lässt es wieder einsetzen — so übt man das Wort nicht
     nackt, sondern an der Stelle, an der es im Deutschen wirklich
     steht. Ohne eigene Wörter läuft es mit dem ganzen Wörterbuch.
     ============================================================ */
  const MS_RUNDEN = 8;
  let msSession = null;
  let msLevel = "A2";

  /* Das nackte Wort ohne Artikel — nur damit lässt sich im Satz suchen. */
  function msKern(wort) { return String(wort || "").replace(/^(der|die|das)\s+/i, "").trim(); }

  /* Wo steckt das Wort im Satz? Erst wörtlich, dann über den Wortstamm:
     „die Verspätung" steht im Satz vielleicht als „Verspätungen". Ohne
     Fund wird das Wort übersprungen — ein Satz mit falscher Lücke wäre
     schlimmer als ein Wort weniger. */
  function msLuecke(satz, wort) {
    const kern = msKern(wort);
    if (!kern || !satz) return null;
    const escape = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const woertlich = new RegExp("(^|[^\\wÄÖÜäöüß])(" + escape(kern) + ")([^\\wÄÖÜäöüß]|$)", "i");
    let treffer = satz.match(woertlich);
    if (!treffer) {
      const stamm = kern.length > 6 ? kern.slice(0, kern.length - 2) : kern;
      if (stamm.length < 4) return null;
      const mitEndung = new RegExp("(^|[^\\wÄÖÜäöüß])(" + escape(stamm) + "[\\wÄÖÜäöüß]{0,4})([^\\wÄÖÜäöüß]|$)", "i");
      treffer = satz.match(mitEndung);
    }
    if (!treffer) return null;
    const gefunden = treffer[2];
    const stelle = satz.indexOf(gefunden);
    if (stelle < 0) return null;
    return {
      vorn: satz.slice(0, stelle),
      hinten: satz.slice(stelle + gefunden.length),
      form: gefunden,
      /* Steht das Wort im Satz genau so da wie im Wörterbuch? Dann
         passen die Ablenker (die immer in der Grundform kommen)
         dazu — und man kann die Lücke nicht an der Endung erraten. */
      grundform: gefunden.toLowerCase() === kern.toLowerCase(),
    };
  }

  function msPool() {
    const alle = buildDictionaryEntries().filter((e) => e.verified && e.example && e.word);
    const eigene = wortQuelleFilter("meinesaetze", alle);
    const quelle = eigene.length >= MS_RUNDEN ? eigene : alle;
    const stufen = ["A1", "A2", "B1", "B2", "C1", "C2"];
    const grenze = stufen.indexOf(msLevel);
    const passend = quelle.filter((e) => stufen.indexOf(e.level || "A2") <= Math.max(0, grenze));
    return (passend.length >= MS_RUNDEN ? passend : quelle);
  }

  function neueMsSession() {
    msLevel = applyDefaultCefrLevel(msLevel, (v) => { msLevel = v; }, "meinesaetze");
    const pool = msPool();
    const aufgaben = [];
    const nachrangig = [];
    for (const e of Core.shuffle(pool)) {
      if (aufgaben.length >= MS_RUNDEN) break;
      const l = msLuecke(e.example, e.word);
      if (!l) continue;
      const ablenker = Core.shuffle(pool.filter((x) => x.word !== e.word))
        .slice(0, 3).map((x) => msKern(x.word));
      if (ablenker.length < 3) continue;
      const aufgabe = {
        wort: e.word, kern: msKern(e.word), syl: e.syl, uebersetzung: e.en,
        bedeutung: e.de, satz: e.example, luecke: l,
        wahlen: Core.shuffle([l.form].concat(ablenker)),
      };
      if (l.grundform) aufgaben.push(aufgabe); else nachrangig.push(aufgabe);
    }
    // Gebeugte Formen erst auffüllen, wenn die sauberen nicht reichen.
    while (aufgaben.length < MS_RUNDEN && nachrangig.length) aufgaben.push(nachrangig.shift());
    msSession = { aufgaben, runde: 0, richtig: 0, punkte: 0, letzte: null };
  }

  function renderMeineSaetze() {
    const area = document.getElementById("meineSaetzeArea");
    if (!area) return;
    if (!(VocabData.alleThemenDa && VocabData.alleThemenDa())) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">🧩 MEINE SÄTZE</p>
        <p class="empty-note">Der Wortschatz wird geladen …</p></div>`;
      wortschatzBereit().then(() => renderMeineSaetze());
      return;
    }
    if (!msSession) neueMsSession();
    const s = msSession;
    if (!s.aufgaben.length) {
      area.innerHTML = `<div class="question-card"><p class="eyebrow">🧩 MEINE SÄTZE</p>
        <p class="empty-note">Für diese Auswahl gibt es gerade keine Beispielsätze. Markiere im
        Wörterbuch ein paar Wörter mit dem Stern ☆ — dann übt dieses Spiel genau mit deinen Sätzen.</p>
        ${wortQuelleChipsHtml("meinesaetze")}</div>`;
      wortQuelleBinden(area, "meinesaetze", () => { neueMsSession(); renderMeineSaetze(); });
      return;
    }
    if (s.runde >= s.aufgaben.length) { renderMeineSaetzeErgebnis(); return; }
    const a = s.aufgaben[s.runde];
    const l = a.luecke;
    area.innerHTML = `
      <div class="question-card">
        ${miniBugReportBtnHtml("Meine Sätze: " + a.wort)}
        <p class="eyebrow">🧩 MEINE SÄTZE · SATZ ${s.runde + 1} / ${s.aufgaben.length}
          <span class="subnav-info-icon" data-info="Zu jedem Wort im Wörterbuch gehört ein Beispielsatz. Hier fehlt genau dieses Wort — setz es wieder ein. Mit dem Stern gemerkte Wörter kommen zuerst dran.">ⓘ</span></p>
        ${fortschrittHtml(s.runde, s.aufgaben.length)}
        <div class="trophy-case wsm-chips">
          ${["A1", "A2", "B1", "B2", "C1", "C2"].map((lvl) => `<button type="button" class="trophy-chip ms-level-btn ${msLevel === lvl ? "selected" : ""}" data-ms-level="${lvl}">${lvl}</button>`).join("")}
        </div>
        ${wortQuelleChipsHtml("meinesaetze")}
        <p class="ms-satz">${escapeHtml(l.vorn)}<span class="ms-luecke">${s.letzte ? escapeHtml(l.form) : "_____"}</span>${escapeHtml(l.hinten)}</p>
        <div class="ms-wahlen">
          ${a.wahlen.map((w) => {
            const richtig = w === l.form;
            const markiert = s.letzte
              ? (richtig ? " ms-wahl-richtig" : (s.letzte.gewaehlt === w ? " ms-wahl-falsch" : ""))
              : "";
            return `<button type="button" class="btn btn-ghost ms-wahl${markiert}" data-ms-wahl="${escapeHtml(w)}"
                     ${s.letzte ? "disabled" : ""}>${escapeHtml(w)}</button>`;
          }).join("")}
        </div>
        ${s.letzte ? `
          <div class="ms-aufloesung">
            <p style="margin:0 0 4px; font-weight:700;">${escapeHtml(a.wort)}
              <button type="button" class="btn btn-ghost bw-hoerknopf bw-hoerknopf-klein" id="msSprich" aria-label="Satz vorlesen">🔊</button></p>
            <p class="bw-betonung" style="margin:0 0 4px;">${betonungAnzeigen(a.syl)}</p>
            <p class="empty-note" style="margin:0;">${escapeHtml(a.bedeutung || "")}${a.uebersetzung ? " · 🇬🇧 " + escapeHtml(a.uebersetzung) : ""}</p>
          </div>` : ""}
      </div>`;
    area.querySelectorAll("[data-ms-level]").forEach((b) => b.addEventListener("click", () => {
      msLevel = b.dataset.msLevel; neueMsSession(); renderMeineSaetze();
    }));
    wortQuelleBinden(area, "meinesaetze", () => { neueMsSession(); renderMeineSaetze(); });
    area.querySelectorAll("[data-ms-wahl]").forEach((b) => b.addEventListener("click", () => msAntwort(b.dataset.msWahl)));
    document.getElementById("msSprich")?.addEventListener("click", () => Core.speak(a.satz, "de-DE"));
  }

  function msAntwort(gewaehlt) {
    const s = msSession;
    if (!s || s.letzte) return;          // doppeltes Antippen zählt nicht zweimal
    const a = s.aufgaben[s.runde];
    const richtig = gewaehlt === a.luecke.form;
    s.letzte = { gewaehlt, richtig };
    if (richtig) { s.richtig += 1; s.punkte += 3; Core.sound.correct?.(); }
    else Core.sound.wrong?.();
    spielNotiz(richtig, a.wort + " — " + a.satz);
    renderMeineSaetze();
    autoWeiter(richtig, () => {
      s.letzte = null;
      s.runde += 1;
      renderMeineSaetze();
    });
  }

  function renderMeineSaetzeErgebnis() {
    const area = document.getElementById("meineSaetzeArea");
    const s = msSession;
    const prozent = Math.round((s.richtig / Math.max(1, s.aufgaben.length)) * 100);
    area.innerHTML = ergebnisSchirmHtml({
      punkte: s.punkte, prozent, tier: "Satzbauer:in", charakter: "Meine Sätze",
      bonus: s.richtig === s.aufgaben.length ? 6 : 0,
      zeilen: [
        { name: "🧩 Wort richtig eingesetzt", anteil: prozent, wert: s.richtig + "/" + s.aufgaben.length },
      ],
      knoepfe: `<button type="button" class="btn btn-coffee" id="msNochmal">🔄 Neue Runde</button>`,
    });
    document.getElementById("msNochmal")?.addEventListener("click", () => { neueMsSession(); renderMeineSaetze(); });
    if (Backend.currentUser()) {
      saveResultAndCheck({ categories: ["meinesaetze"], points: s.punkte, bonus: 0, percent: prozent,
        character: "Satzbauer:in", badges: [], playedAt: new Date().toISOString() });
      if (activeGameChallengeId) { Backend.submitChallengeResult(activeGameChallengeId, { percent: prozent }); activeGameChallengeId = null; geliehenAlleWeg(); }
    }
  }
  document.querySelector('#learnSubnav [data-sub="sub-meinesaetze"]')?.addEventListener("click", () => renderMeineSaetze());

  /* ============================================================
     STADT · LAND · FLUSS
     ------------------------------------------------------------
     GEWÜNSCHT: „Stadt-Land-Fluss als Gruppenspiel mit
     gleichzeitigem Start."

     Zwei Arten zu spielen:

     Allein — der Fuchs füllt heimlich seinen eigenen Zettel aus.
     Dadurch gilt dieselbe Wertung wie am Küchentisch, ohne dass
     jemand anders online sein müsste.

     Zu zweit — beide bekommen denselben Buchstaben, dieselben
     Spalten UND dieselbe Startzeit. Die steht in der Einladung;
     beide Geräte warten auf dieselbe Sekunde und zählen dann
     gemeinsam herunter. Danach werden die Zettel nebeneinander
     gelegt.

     Gewertet wird klassisch:
        20 Punkte — nur du hast in dieser Spalte etwas stehen
        10 Punkte — du hast etwas, aber ein anderes Wort als die anderen
         5 Punkte — dasselbe Wort wie jemand anders
         0 Punkte — leer oder falscher Anfangsbuchstabe
     ============================================================ */

